# =========================================================
# FinMind token 狀態與 headers
# token 請放 Replit Secrets：FINMIND_TOKEN；畫面只顯示狀態，不顯示 token。
# =========================================================
def get_finmind_token() -> str:
    try:
        token = str(st.secrets.get("FINMIND_TOKEN", "") or "").strip()
    except Exception:
        token = ""
    if not token:
        token = str(os.getenv("FINMIND_TOKEN", "") or "").strip()
    return token


def finmind_headers(extra: Optional[Dict[str, str]] = None) -> Dict[str, str]:
    headers: Dict[str, str] = {"User-Agent": "Mozilla/5.0"}
    if extra:
        headers.update(extra)
    token = get_finmind_token()
    if token:
        headers["Authorization"] = f"Bearer {token}"
    return headers


@st.cache_data(ttl=300, show_spinner=False)
def finmind_token_status() -> Dict[str, Any]:
    token = get_finmind_token()
    if not token:
        return {"ok": False, "label": "FinMind：未帶 token｜300/hr", "detail": "未偵測 FINMIND_TOKEN"}
    try:
        r = requests.get(
            "https://api.web.finmindtrade.com/v2/user_info",
            headers={"Authorization": f"Bearer {token}", "User-Agent": "Mozilla/5.0"},
            timeout=8,
        )
        if r.status_code != 200:
            return {"ok": True, "label": "FinMind：已帶 token｜600/hr", "detail": f"使用量查詢 HTTP {r.status_code}"}
        data = r.json() if r.text else {}
        used = data.get("user_count", "?") if isinstance(data, dict) else "?"
        limit = data.get("api_request_limit", "600") if isinstance(data, dict) else "600"
        return {"ok": True, "label": f"FinMind：已帶 token｜{used}/{limit}", "detail": "token 已偵測"}
    except Exception as e:
        return {"ok": True, "label": "FinMind：已帶 token｜600/hr", "detail": f"使用量查詢失敗：{e}"}


def render_finmind_status_chip() -> None:
    stt = finmind_token_status()
    color = "#22c55e" if stt.get("ok") else "#f59e0b"
    bg = "rgba(34,197,94,.12)" if stt.get("ok") else "rgba(245,158,11,.12)"
    label = str(stt.get("label") or "FinMind 狀態未知")
    detail = str(stt.get("detail") or "")
    st.markdown(
        f"""
        <div style="display:flex;justify-content:flex-end;margin:-8px 0 8px 0;">
          <div title="{detail}" style="font-size:11px;line-height:1.2;color:{color};background:{bg};border:1px solid {color}55;border-radius:999px;padding:4px 9px;white-space:nowrap;">
            {label}
          </div>
        </div>
        """,
        unsafe_allow_html=True,
    )
