# =========================================================
# 基本工具
# =========================================================
def now_tw() -> datetime:
    return datetime.now(TW_TZ)


def to_float(x: Any) -> Optional[float]:
    try:
        if x is None:
            return None
        if isinstance(x, (int, float, np.integer, np.floating)):
            if pd.isna(x):
                return None
            return float(x)
        s = str(x).replace(",", "").replace("%", "").replace("x", "").strip()
        if s in ["", "-", "--", "nan", "None", "NaN", "null"]:
            return None
        return float(s)
    except Exception:
        return None


def safe_div(a: Any, b: Any) -> Optional[float]:
    a, b = to_float(a), to_float(b)
    if a is None or b in [None, 0]:
        return None
    return a / b


def pct_change(a: Any, b: Any) -> Optional[float]:
    a, b = to_float(a), to_float(b)
    if a is None or b in [None, 0]:
        return None
    return (a - b) / abs(b) * 100


def fmt_num(x: Any, digits: int = 0) -> str:
    x = to_float(x)
    if x is None:
        return "—"
    return f"{x:,.{digits}f}"


def fmt_price(x: Any) -> str:
    x = to_float(x)
    if x is None:
        return "—"
    if abs(x) >= 1000:
        return f"{x:,.0f}"
    if abs(x) >= 100:
        return f"{x:,.1f}".rstrip("0").rstrip(".")
    return f"{x:,.2f}".rstrip("0").rstrip(".")


def fmp(x: Any) -> str:
    x = to_float(x)
    if x is None:
        return "—"
    return f"{x:+.2f}%"


# v205｜全APP方向性數字顏色：台股習慣，上漲紅色、下跌綠色。
TW_UP_COLOR = "#f85149"
TW_DOWN_COLOR = "#3fb950"
TW_FLAT_COLOR = "#e5e7eb"


def tw_direction_color(x: Any, flat: str = TW_FLAT_COLOR) -> str:
    v = to_float(x)
    if v is None:
        return flat
    if v > 0:
        return TW_UP_COLOR
    if v < 0:
        return TW_DOWN_COLOR
    return flat


def tw_direction_class(x: Any) -> str:
    v = to_float(x)
    if v is None:
        return "tw-flat"
    if v > 0:
        return "tw-up"
    if v < 0:
        return "tw-down"
    return "tw-flat"


def tw_direction_html(value: Any, display: Any = None) -> str:
    txt = str(display if display is not None else value)
    cls = tw_direction_class(value)
    return f'<span class="{cls}">{txt}</span>'


def fmt_shares(x: Any) -> str:
    x = to_float(x)
    if x is None:
        return "—"
    return f"{x:,.0f}"


def clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, x))


def normalize_date_str(x: Any) -> str:
    try:
        dt = pd.to_datetime(x, errors="coerce")
        if pd.isna(dt):
            return ""
        return dt.strftime("%Y-%m-%d")
    except Exception:
        return ""


