def _merge_stock_app_flow_extension_into_market_pool() -> None:
    """把個股 App 的資金流向擴充股池併入大盤 App 股票池。"""
    try:
        for sector, codes in STOCK_APP_FLOW_EXTENSION_MAPPED.items():
            SECTOR_STOCK_POOL.setdefault(sector, [])
            seen = {clean_stock_id(x[0]) for x in SECTOR_STOCK_POOL.get(sector, []) if isinstance(x, (list, tuple)) and x}
            for code in codes or []:
                sid = clean_stock_id(code)
                if not is_common_stock_id(sid) or sid in seen:
                    continue
                name = STOCK_APP_NAME_LOOKUP.get(sid, sid)
                SECTOR_STOCK_POOL[sector].append((sid, name))
                seen.add(sid)
    except Exception:
        pass


# 立即套用，不改演算法，只補股票池。
_merge_stock_app_flow_extension_into_market_pool()

