def clean_stock_id(x: Any) -> str:
    s = str(x or "").strip()
    s = s.replace("=", "").replace('"', "").replace("'", "")
    return s.zfill(4) if s.isdigit() and len(s) <= 4 else s


def is_common_stock_id(stock_id: str) -> bool:
    sid = clean_stock_id(stock_id)
    # 台股普通股多為 4 碼；排除 ETF / ETN / 權證常見 00 開頭或非純數字。
    return len(sid) == 4 and sid.isdigit() and not sid.startswith("00")


def get_effective_sector_pool(sector: str, extra_pool: Optional[Dict[str, Any]] = None) -> List[Tuple[str, str]]:
    """內建股票池 + 聯網新增候選股。聯網候選放前面，讓掃描時優先納入。"""
    seen = set()
    out: List[Tuple[str, str]] = []

    for item in (extra_pool or {}).get(sector, []) or []:
        if isinstance(item, dict):
            sid, name = clean_stock_id(item.get("stock_id")), str(item.get("stock_name") or "")
        elif isinstance(item, (list, tuple)) and len(item) >= 2:
            sid, name = clean_stock_id(item[0]), str(item[1])
        else:
            continue
        if not is_common_stock_id(sid) or not name or sid in seen:
            continue
        out.append((sid, name))
        seen.add(sid)

    for sid, name in SECTOR_STOCK_POOL.get(sector, []):
        sid = clean_stock_id(sid)
        if sid not in seen:
            out.append((sid, name))
            seen.add(sid)
    return out


