# v143｜退潮頁狀態統一：服務 Nick 心法，不做單純弱勢清單。
# 目的：
# 1) 優質股退潮後，等回基本面支撐。
# 2) 短線退潮者，等重新回到資金流入佈局。
# 3) 反彈弱股視為賣點，不誤判轉強。
# 4) 與「資金流入佈局」頁不互相矛盾。
OUTFLOW_STATUS_MAP = {
    "基本面沒壞，但資金短退": "優質退潮｜等基本面支撐",
    "疑似洗盤，觀察支撐": "優質退潮｜等基本面支撐",
    "高檔鈍化，不追高": "短線退潮｜等重新流入",
    "退潮觀察": "短線退潮｜等重新流入",
    "反彈逃命股": "反彈賣點｜不要誤判轉強",
    "明確退潮，先避開": "明確退潮｜先避開",
}

def normalize_outflow_status(status: Any) -> str:
    s = str(status or "").strip()
    return OUTFLOW_STATUS_MAP.get(s, s)


def flow_rows_sorted(snapshot: Dict[str, Any]) -> List[Dict[str, Any]]:
    """依資金狀態與分數排序，回傳最新資金流向族群列。"""
    rows = ((snapshot or {}).get("flow") or {}).get("rows") or []
    status_rank = {s: i for i, s in enumerate(FLOW_STATUS_OPTIONS)}
    return sorted(
        [r for r in rows if isinstance(r, dict) and r.get("族群")],
        key=lambda r: (status_rank.get(r.get("狀態"), 99), -(to_float(r.get("分數")) or -999)),
    )


def parse_stock_name_from_flow_item(item: Dict[str, Any], code: str) -> str:
    text = str(item.get("股票") or item.get("stock_name") or "").strip()
    code = clean_stock_id(code)
    if code and code in text:
        text = text.replace(code, "").strip(" ｜|-_")
    return text or str(item.get("name") or code)


def build_flow_sector_pool(snapshot: Dict[str, Any], statuses: Optional[List[str]] = None) -> Dict[str, List[Dict[str, str]]]:
    """把資金流向掃出的各族群代表股，轉成個股雷達可掃描的股票池。\n    重點：即使該族群不在 SECTOR_STOCK_POOL，也能掃，避免新族群漏掉。"""
    allowed = set(statuses or FLOW_STATUS_OPTIONS)
    pool: Dict[str, List[Dict[str, str]]] = {}
    seen: Dict[str, set] = {}
    for row in flow_rows_sorted(snapshot):
        sector = str(row.get("族群") or "").strip()
        status = row.get("狀態") or "觀察中"
        if not sector or status not in allowed:
            continue
        pool.setdefault(sector, [])
        seen.setdefault(sector, set())
        for item in row.get("個股") or []:
            if not isinstance(item, dict):
                continue
            sid = clean_stock_id(item.get("代號") or item.get("stock_id") or item.get("code"))
            if not is_common_stock_id(sid) or sid in seen[sector]:
                continue
            name = parse_stock_name_from_flow_item(item, sid)
            pool[sector].append({"stock_id": sid, "stock_name": name})
            seen[sector].add(sid)
    return pool


def merge_sector_pools(*pools: Optional[Dict[str, Any]]) -> Dict[str, List[Any]]:
    """合併 discovered_pool 與資金流向動態股票池，避免重複代號。"""
    merged: Dict[str, List[Any]] = {}
    seen: Dict[str, set] = {}
    for pool in pools:
        if not isinstance(pool, dict):
            continue
        for sector, items in pool.items():
            if not sector:
                continue
            merged.setdefault(sector, [])
            seen.setdefault(sector, set())
            for item in items or []:
                sid = ""
                if isinstance(item, dict):
                    sid = clean_stock_id(item.get("stock_id") or item.get("代號") or item.get("code"))
                elif isinstance(item, (list, tuple)) and item:
                    sid = clean_stock_id(item[0])
                if sid and sid in seen[sector]:
                    continue
                merged[sector].append(item)
                if sid:
                    seen[sector].add(sid)
    return merged


def auto_radar_sectors_from_flow(snapshot: Dict[str, Any], statuses: Optional[List[str]] = None) -> List[str]:
    """依最新資金流向，自動帶入個股雷達族群。"""
    allowed = set(statuses or AUTO_RADAR_DEFAULT_STATUSES)
    out: List[str] = []
    seen = set()
    for row in flow_rows_sorted(snapshot):
        sector = str(row.get("族群") or "").strip()
        if not sector or sector in seen:
            continue
        if (row.get("狀態") or "觀察中") in allowed:
            out.append(sector)
            seen.add(sector)
    return out


def radar_sector_options(snapshot: Dict[str, Any]) -> List[str]:
    """個股雷達可選族群：內建族群 + 最新資金流向族群 + 聯網候選族群。"""
    out: List[str] = []
    seen = set()
    for sector in list(SECTOR_STOCK_POOL.keys()):
        if sector not in seen:
            out.append(sector)
            seen.add(sector)
    for row in flow_rows_sorted(snapshot):
        sector = str(row.get("族群") or "").strip()
        if sector and sector not in seen:
            out.append(sector)
            seen.add(sector)
    for sector in ((snapshot or {}).get("discovered_pool") or {}).keys():
        if sector and sector not in seen:
            out.append(sector)
            seen.add(sector)
    return out



def radar_statuses_for_mode(radar_mode: str) -> List[str]:
    """v163｜依雷達模式決定要掃的資金狀態。

    growth：只看今日資金流入方向，找成長股買點。
    """
    if radar_mode == "outflow":
        return RADAR_OUTFLOW_STATUSES
    return RADAR_INFLOW_STATUSES


def resolve_radar_sectors_for_mode(snapshot: Dict[str, Any], radar_mode: str) -> List[str]:
    """依按鈕模式決定要掃哪些族群；手動模式仍尊重使用者選擇。"""
    source_mode = st.session_state.get("radar_source", "依最新資金流向自動帶入")
    if str(source_mode).startswith("依最新資金流向"):
        statuses = radar_statuses_for_mode(radar_mode)
        sectors = auto_radar_sectors_from_flow(snapshot, statuses)
        if not sectors and radar_mode in ["inflow", "growth"]:
            sectors = snapshot.get("radar_auto_sectors") or []
        return sectors or DEFAULT_RADAR_SECTORS
    return st.session_state.get("radar_sectors", DEFAULT_RADAR_SECTORS)


def flow_status_lookup(snapshot: Dict[str, Any]) -> Dict[str, str]:
    """族群 → 最新資金狀態。"""
    lookup: Dict[str, str] = {}
    for row in flow_rows_sorted(snapshot):
        sector = str(row.get("族群") or "").strip()
        if sector and sector not in lookup:
            lookup[sector] = str(row.get("狀態") or "觀察中")
    return lookup

