def sync_market_flow_to_stock_app(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    """把大盤 App 的最新資金流向同步給個股 App。"""
    flow = (snapshot or {}).get("flow") or {}
    rows = flow.get("rows") or []
    if not isinstance(flow, dict) or not rows:
        return {"ok": False, "note": "尚無大盤資金流向可同步"}

    shared = dict(flow)
    shared["shared_from_market_app"] = True
    shared["shared_updated_at"] = now_tw().strftime("%Y-%m-%d %H:%M:%S")
    shared.setdefault("source", flow.get("source", "market_app_flow"))
    shared["status"] = {
        "level": "ok",
        "included": True,
        "note": "由大盤 App 資金流向同步給個股 App",
    }

    try:
        with SHARED_STOCK_FLOW_PATH.open("w", encoding="utf-8") as f:
            json.dump(shared, f, ensure_ascii=False, indent=2)
        return {"ok": True, "note": f"已同步 {len(rows)} 組資金流向給個股 App"}
    except Exception as e:
        return {"ok": False, "note": f"同步失敗：{e}"}


def add_log(snapshot: Dict[str, Any], action: str, result: str) -> None:
    logs = snapshot.get("log") or []
    logs.insert(0, {"時間": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "動作": action, "結果": result})
    snapshot["log"] = logs[:50]


def status_item(level: str, included: bool, note: str) -> Dict[str, Any]:
    # level: ok / partial / fail / skip
    return {"level": level, "included": included, "note": note}


