def import_yfinance():
    try:
        import yfinance as yf  # type: ignore
        return yf, None
    except Exception as e:
        return None, str(e)


def flatten_yf_columns(df: pd.DataFrame) -> pd.DataFrame:
    if isinstance(df.columns, pd.MultiIndex):
        df = df.copy()
        df.columns = [c[0] if isinstance(c, tuple) else c for c in df.columns]
    return df


# =========================================================
# 大盤 K 線：更新時才抓
# =========================================================
def _finalize_market_kline_df(out: pd.DataFrame) -> Tuple[Optional[pd.DataFrame], str]:
    """大盤K線共同整理：沿用原大盤 App 的均線與量能計算核心。"""
    if out is None or out.empty:
        return None, "K 線資料空白"

    out = out.dropna(subset=["date", "open", "max", "min", "close"]).sort_values("date").reset_index(drop=True)
    if len(out) < 70:
        return None, f"K 線資料不足 70 筆，目前 {len(out)} 筆"

    # 核心不改：維持原本 MA5/MA10/MA20/MA60 與 VolMA5/VolMA20
    out["MA5"] = out["close"].rolling(5).mean()
    out["MA10"] = out["close"].rolling(10).mean()
    out["MA20"] = out["close"].rolling(20).mean()
    out["MA60"] = out["close"].rolling(60).mean()
    out["VolMA5"] = out["volume"].rolling(5).mean()
    out["VolMA20"] = out["volume"].rolling(20).mean()
    return out, ""


def _fetch_market_kline_yahoo_chart() -> Tuple[Optional[pd.DataFrame], str]:
    """Yahoo Chart API 直接抓 ^TWII。

    這裡取代 yfinance 作為大盤更新來源，原因是 yfinance 在 Replit 偶發卡住。
    注意：只改資料來源，不改後面的 K線計算、支撐壓力、盤勢判斷核心。
    """
    try:
        url = "https://query1.finance.yahoo.com/v8/finance/chart/%5ETWII"
        params = {"range": "18mo", "interval": "1d"}
        r = requests.get(
            url,
            params=params,
            timeout=REQUEST_TIMEOUT,
            headers={"User-Agent": "Mozilla/5.0"},
        )
        if r.status_code != 200:
            return None, f"Yahoo Chart HTTP {r.status_code}"

        js = r.json()
        chart = js.get("chart") or {}
        err = chart.get("error")
        if err:
            return None, f"Yahoo Chart error：{err}"

        result = (chart.get("result") or [None])[0] or {}
        timestamps = result.get("timestamp") or []
        quote = (((result.get("indicators") or {}).get("quote") or [None])[0]) or {}

        if not timestamps or not quote:
            return None, "Yahoo Chart 回傳空資料"

        n = len(timestamps)

        def arr(name: str):
            values = quote.get(name) or []
            if len(values) < n:
                values = list(values) + [None] * (n - len(values))
            return values[:n]

        out = pd.DataFrame({
            "date": [datetime.fromtimestamp(int(t), TW_TZ).replace(tzinfo=None) for t in timestamps],
            "open": arr("open"),
            "max": arr("high"),
            "min": arr("low"),
            "close": arr("close"),
            "volume": arr("volume"),
        })

        for c in ["open", "max", "min", "close", "volume"]:
            out[c] = out[c].apply(to_float)

        return _finalize_market_kline_df(out)
    except Exception as e:
        return None, f"Yahoo Chart 失敗：{e}"



def _fetch_twse_taiex_history_month(date_anchor: Optional[datetime] = None) -> Tuple[Optional[pd.DataFrame], str]:
    """抓 TWSE 加權指數歷史日K（月資料）。

    目的：
    - Yahoo Chart 日K有時候會延遲，導致 K線停在舊日期。
    - 這裡用 TWSE 官方 TAIEX 日資料補上最新已完成交易日。
    """
    anchor_dt = date_anchor or now_tw()
    url = "https://www.twse.com.tw/rwd/zh/TAIEX/MI_5MINS_HIST"
    try:
        r = requests.get(
            url,
            params={"date": anchor_dt.strftime("%Y%m%d"), "response": "json"},
            timeout=REQUEST_TIMEOUT,
            headers={"User-Agent": "Mozilla/5.0"},
        )
        if r.status_code != 200:
            return None, f"TWSE TAIEX HTTP {r.status_code}"

        js = r.json()
        data = js.get("data") or []
        fields = js.get("fields") or []
        if not data:
            return None, "TWSE TAIEX 回傳空資料"

        # 常見欄位：日期、開盤指數、最高指數、最低指數、收盤指數
        rows = []
        for row in data:
            if not isinstance(row, list) or len(row) < 5:
                continue
            d_raw = str(row[0]).strip()
            # 民國年格式：115/05/22
            try:
                parts = d_raw.split("/")
                if len(parts) == 3:
                    yy = int(parts[0]) + 1911
                    mm = int(parts[1])
                    dd = int(parts[2])
                    d = pd.Timestamp(year=yy, month=mm, day=dd)
                else:
                    d = pd.to_datetime(d_raw, errors="coerce")
            except Exception:
                d = pd.NaT
            if pd.isna(d):
                continue

            open_p = to_float(row[1])
            high_p = to_float(row[2])
            low_p = to_float(row[3])
            close_p = to_float(row[4])
            if None in [open_p, high_p, low_p, close_p]:
                continue
            rows.append({
                "date": d,
                "open": open_p,
                "max": high_p,
                "min": low_p,
                "close": close_p,
                "volume": 0,
            })

        if not rows:
            return None, "TWSE TAIEX 無有效日K資料"

        out = pd.DataFrame(rows).sort_values("date").reset_index(drop=True)
        return out, ""
    except Exception as e:
        return None, f"TWSE TAIEX 失敗：{e}"


def _merge_twse_taiex_history_into_yahoo(df: pd.DataFrame) -> Tuple[pd.DataFrame, bool, str]:
    """把 TWSE 官方加權日K補進 Yahoo 日K。"""
    if df is None or df.empty:
        return df, False, "Yahoo 日K空白，無法合併"

    # 抓本月；若本月空白，再抓上個月。
    now = now_tw()
    twse_df, err = _fetch_twse_taiex_history_month(now)
    if twse_df is None or twse_df.empty:
        prev_month = (now.replace(day=1) - timedelta(days=1))
        twse_df, err2 = _fetch_twse_taiex_history_month(prev_month)
        if twse_df is None or twse_df.empty:
            return df, False, f"TWSE 日K補強失敗：{err}｜{err2}"

    work = df.copy().sort_values("date").reset_index(drop=True)
    changed = False
    added_dates = []

    # 只補 Yahoo 沒有的新日期，或覆蓋最後同日期 close/open/high/low。
    existing_dates = {pd.to_datetime(x).normalize(): i for i, x in enumerate(work["date"])}

    for _, r in twse_df.iterrows():
        d = pd.to_datetime(r["date"]).normalize()

        # TWSE TAIEX 在盤中可能已出現今天資料；盤中資料不能併入正式日K。
        if not _is_completed_market_date(d):
            continue

        if d in existing_dates:
            # 覆蓋同日期 OHLC，避免 Yahoo 延遲或錯值；但僅限已完成交易日。
            idx = existing_dates[d]
            for col in ["open", "max", "min", "close"]:
                work.loc[idx, col] = to_float(r.get(col))
            changed = True
        else:
            # 僅補入比目前 Yahoo 最後日期新的已完成日K，避免塞入今日盤中K造成昨日K消失。
            last_date = pd.to_datetime(work["date"].iloc[-1]).normalize()
            if d > last_date:
                new_row = {
                    "date": d,
                    "open": to_float(r.get("open")),
                    "max": to_float(r.get("max")),
                    "min": to_float(r.get("min")),
                    "close": to_float(r.get("close")),
                    "volume": to_float(r.get("volume")) or 0,
                }
                work = pd.concat([work, pd.DataFrame([new_row])], ignore_index=True)
                existing_dates[d] = len(work) - 1
                changed = True
                added_dates.append(d.strftime("%Y-%m-%d"))

    if not changed:
        return df, False, "TWSE 日K沒有比 Yahoo 更新"

    for col in ["MA5", "MA10", "MA20", "MA60", "VolMA5", "VolMA20"]:
        if col in work.columns:
            work = work.drop(columns=[col])

    finalized, ferr = _finalize_market_kline_df(work)
    if finalized is None:
        return df, False, f"TWSE 合併後整理失敗：{ferr}"

    latest = normalize_date_str(finalized["date"].iloc[-1])
    if added_dates:
        return finalized, True, f"TWSE 日K補上 {', '.join(added_dates[-3:])}，最新 {latest}"
    return finalized, True, f"TWSE 日K校正完成，最新 {latest}"


def fetch_market_kline() -> Tuple[Optional[pd.DataFrame], str]:
    """大盤 K 線更新：已完成日K + 盤中K分離版。

    - Yahoo Chart 負責抓長資料。
    - TWSE TAIEX 歷史日K只補「已完成交易日」。
    - 今天盤中資料不併入正式日K，會在圖上以盤中K另外顯示。
    - 不使用 yfinance，避免 Replit 卡死。
    """
    df, err = _fetch_market_kline_yahoo_chart()
    if df is None:
        return None, f"大盤K線更新失敗：{err}"

    df, removed_yahoo, remove_note_yahoo = _remove_unfinished_today_kline(df)

    merged_df, merged, note = _merge_twse_taiex_history_into_yahoo(df)
    if merged_df is not None:
        merged_df, removed_twse, remove_note_twse = _remove_unfinished_today_kline(merged_df)
        notes = []
        if merged:
            notes.append(note)
        if removed_yahoo:
            notes.append(remove_note_yahoo)
        if removed_twse:
            notes.append(remove_note_twse)
        merged_df.attrs["twse_merge_note"] = "｜".join([x for x in notes if x])
        return merged_df, merged_df.attrs.get("twse_merge_note", "")

    df.attrs["twse_merge_note"] = remove_note_yahoo if removed_yahoo else ""
    return df, df.attrs.get("twse_merge_note", "")


def df_to_records(df: pd.DataFrame) -> List[Dict[str, Any]]:
    work = df.copy()
    for c in work.columns:
        if pd.api.types.is_datetime64_any_dtype(work[c]):
            work[c] = work[c].dt.strftime("%Y-%m-%d")
    work = work.replace({float("nan"): None})
    return work.to_dict("records")


def records_to_df(records: Any) -> pd.DataFrame:
    if not records:
        return pd.DataFrame()
    df = pd.DataFrame(records)
    if "date" in df.columns:
        df["date"] = pd.to_datetime(df["date"], errors="coerce")
    for c in ["open", "max", "min", "close", "volume", "MA5", "MA10", "MA20", "MA60", "VolMA5", "VolMA20"]:
        if c in df.columns:
            df[c] = df[c].apply(to_float)
    return df.dropna(subset=["date"]).sort_values("date").reset_index(drop=True) if "date" in df.columns else df


def _quote_num(v: Any) -> Optional[float]:
    """TWSE MIS 即時資料清洗。某些欄位會用底線串多筆，取第一個有效值。"""
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        if "_" in s:
            parts = [p for p in s.split("_") if p not in ["", "-", "--"]]
            s = parts[0] if parts else ""
        s = s.replace(",", "").strip()
        if s in ["", "-", "--", "nan", "None", "NaN"]:
            return None
        return to_float(s)
    return to_float(v)


def _quote_date_to_timestamp(date_str: Any) -> pd.Timestamp:
    try:
        s = str(date_str or "").strip()
        if len(s) == 8 and s.isdigit():
            return pd.to_datetime(s, format="%Y%m%d", errors="coerce")
        return pd.to_datetime(s, errors="coerce")
    except Exception:
        return pd.NaT


@st.cache_data(ttl=8, show_spinner=False)
def fetch_market_realtime_quote() -> Tuple[Optional[Dict[str, Any]], str]:
    """抓加權指數盤中即時報價，只用來畫最後一根盤中 K，不納入支撐壓力/均線/裁決計算。"""
    headers = {
        "User-Agent": "Mozilla/5.0",
        "Referer": "https://mis.twse.com.tw/stock/fibest.jsp?stock=t00",
    }
    try:
        ts = int(datetime.now().timestamp() * 1000)
        r = requests.get(
            "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
            params={"ex_ch": "tse_t00.tw", "json": "1", "delay": "0", "_": ts},
            headers=headers,
            timeout=8,
        )
        if r.status_code != 200:
            return None, f"即時報價 HTTP {r.status_code}"
        js = r.json()
        arr = js.get("msgArray", [])
        if not arr:
            return None, "加權指數即時資料空白"
        item = arr[0]

        rt_price = _quote_num(item.get("z"))
        open_p = _quote_num(item.get("o"))
        high_p = _quote_num(item.get("h"))
        low_p = _quote_num(item.get("l"))
        prev_close = _quote_num(item.get("y"))
        volume = _quote_num(item.get("v"))

        if rt_price is None:
            return None, "加權指數即時價空白"

        if open_p is None:
            open_p = prev_close if prev_close is not None else rt_price
        if high_p is None:
            high_p = max(open_p, rt_price)
        if low_p is None:
            low_p = min(open_p, rt_price)

        qdate = _quote_date_to_timestamp(item.get("d"))
        if pd.isna(qdate):
            qdate = pd.Timestamp(now_tw().date())

        qtime = str(item.get("t") or "").strip()
        if qtime and len(qtime) == 6 and qtime.isdigit():
            qtime_s = f"{qtime[:2]}:{qtime[2:4]}:{qtime[4:]}"
        else:
            qtime_s = qtime or now_tw().strftime("%H:%M:%S")

        return {
            "price": rt_price,
            "open": open_p,
            "high": max(high_p, open_p, rt_price),
            "low": min(low_p, open_p, rt_price),
            "prev_close": prev_close,
            "volume": volume,
            "date": qdate.strftime("%Y-%m-%d"),
            "time": qtime_s,
            "source": "TWSE MIS tse_t00.tw",
        }, ""
    except Exception as e:
        return None, f"即時報價失敗：{e}"


def append_intraday_k_for_display(df: pd.DataFrame, realtime_quote: Optional[Dict[str, Any]]) -> Tuple[pd.DataFrame, bool]:
    """只把盤中 K 補到圖上顯示。

    重點：
    - 不重算 MA5/10/20/60。
    - 不重算支撐壓力。
    - 不重算盤後裁決。
    - 新增/覆蓋的盤中列，均線欄位保持 None，避免看起來像已納入均線計算。
    """
    if df is None or df.empty or not realtime_quote:
        return df, False

    q_price = to_float(realtime_quote.get("price"))
    q_date = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
    if q_price is None or pd.isna(q_date):
        return df, False

    work = df.copy().sort_values("date").reset_index(drop=True)
    q_open = to_float(realtime_quote.get("open")) or q_price
    q_high = to_float(realtime_quote.get("high")) or max(q_open, q_price)
    q_low = to_float(realtime_quote.get("low")) or min(q_open, q_price)
    q_volume = to_float(realtime_quote.get("volume")) or 0

    new_row = {
        "date": q_date,
        "open": q_open,
        "max": max(q_high, q_open, q_price),
        "min": min(q_low, q_open, q_price),
        "close": q_price,
        "volume": q_volume,
        "MA5": None,
        "MA10": None,
        "MA20": None,
        "MA60": None,
        "VolMA5": None,
        "VolMA20": None,
    }

    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")

    # 模仿個股分析器：盤中K只新增在最右側，不覆蓋最後一根已完成日K。
    # 若正式日K已經含有同一天，代表它可能是已完成日K或資料源已補值，盤中K就不再覆蓋。
    if not pd.isna(last_date) and q_date.normalize() <= last_date.normalize():
        return work, False

    if pd.isna(last_date) or q_date.normalize() > last_date.normalize():
        for c in work.columns:
            if c not in new_row:
                new_row[c] = None
        work = pd.concat([work, pd.DataFrame([new_row])], ignore_index=True)
        return work, True

    return work, False


# =========================================================
# 大量 K 支撐壓力
# =========================================================
def detect_volume_k_sr_lines(df: pd.DataFrame, lookback: int = 120, max_lines: int = 6, min_gap_pct: float = 0.003) -> List[Dict[str, Any]]:
    if df is None or df.empty or len(df) < 10:
        return []
    required = {"date", "open", "max", "min", "close", "volume"}
    if not required.issubset(set(df.columns)):
        return []

    work = df.copy().sort_values("date").reset_index(drop=True)
    if "VolMA5" not in work.columns:
        work["VolMA5"] = work["volume"].rolling(5).mean()

    current_price = to_float(work["close"].iloc[-1])
    if current_price is None:
        return []

    start = max(1, len(work) - lookback)
    candidates: List[Dict[str, Any]] = []

    for i in range(start, len(work)):
        row = work.iloc[i]
        prev = work.iloc[i - 1]
        vol = to_float(row.get("volume"))
        vol_ma5 = to_float(row.get("VolMA5"))
        prev_vol = to_float(prev.get("volume"))
        if vol is None or vol_ma5 is None or prev_vol is None:
            continue
        if not (vol > vol_ma5 and vol > prev_vol):
            continue

        o, c, h, l = to_float(row.get("open")), to_float(row.get("close")), to_float(row.get("max")), to_float(row.get("min"))
        if None in [o, c, h, l]:
            continue
        if c > o:
            level = l
            source_type = "紅K低點"
        elif c < o:
            level = h
            source_type = "綠K高點"
        else:
            continue

        kind = "支撐" if level <= current_price else "壓力"
        candidates.append(
            {
                "price": float(level),
                "source_date": normalize_date_str(row.get("date")),
                "source_index": int(i),
                "type": source_type,
                "kind": kind,
                "distance_pct": abs(level - current_price) / max(abs(current_price), 1e-9),
                "volume_ratio_ma5": safe_div(vol, vol_ma5),
            }
        )

    candidates = sorted(candidates, key=lambda x: (x["distance_pct"], -x["source_index"]))
    selected: List[Dict[str, Any]] = []
    for item in candidates:
        p = to_float(item.get("price"))
        if p is None:
            continue
        if any(abs(p - to_float(k.get("price"))) / max(abs(p), 1e-9) <= min_gap_pct for k in selected):
            continue
        selected.append(item)
        if len(selected) >= max_lines:
            break
    return selected


def compute_key_levels(df: pd.DataFrame, sr_lines: List[Dict[str, Any]]) -> Dict[str, Any]:
    """大盤支撐壓力。

    v208：
    - 短線防守：最近大量K支撐 / MA20，取較接近現價的位置。
    - 波段防守：MA60 / 主要大量K支撐，取較深、偏波段不能破的位置。
    - fail_line 保留為舊欄位，等於波段防守，避免其他舊模組壞掉。
    """
    if df is None or df.empty:
        return {}
    last = df.iloc[-1]
    close = to_float(last.get("close"))
    if close is None:
        return {}

    ma20 = to_float(last.get("MA20"))
    ma60 = to_float(last.get("MA60"))
    recent_low20 = to_float(df.tail(20)["min"].min())

    sr_support_items = [x for x in (sr_lines or []) if x.get("kind") == "支撐" and to_float(x.get("price")) is not None]
    sr_pressure_items = [x for x in (sr_lines or []) if x.get("kind") == "壓力" and to_float(x.get("price")) is not None]

    sr_support_prices = [to_float(x.get("price")) for x in sr_support_items]
    sr_pressure_prices = [to_float(x.get("price")) for x in sr_pressure_items]

    # 最近大量K支撐：離現價最近、且在現價下方的支撐。
    valid_sr_supports = [p for p in sr_support_prices if p is not None and p < close]
    nearest_sr_support = max(valid_sr_supports) if valid_sr_supports else None

    # 主要大量K支撐：優先看量比大的大量K支撐；避免離現價太遠的歷史支撐亂入，先限定 20% 內。
    major_candidates = []
    for item in sr_support_items:
        p = to_float(item.get("price"))
        if p is None or p >= close:
            continue
        dist = abs(close - p) / max(abs(close), 1e-9)
        if dist <= 0.20:
            major_candidates.append(item)
    if not major_candidates:
        major_candidates = [item for item in sr_support_items if to_float(item.get("price")) is not None and to_float(item.get("price")) < close]

    major_sr_support = None
    if major_candidates:
        major_candidates = sorted(
            major_candidates,
            key=lambda x: (
                -(to_float(x.get("volume_ratio_ma5")) or 0),
                -(to_float(x.get("source_index")) or 0),
                abs((to_float(x.get("price")) or close) - close),
            ),
        )
        major_sr_support = to_float(major_candidates[0].get("price"))

    supports = sr_support_prices + [ma20, ma60, recent_low20]
    pressures = sr_pressure_prices + [to_float(last.get("MA5")), to_float(last.get("MA10")), to_float(df.tail(20)["max"].max())]
    supports = [x for x in supports if x is not None and x < close]
    pressures = [x for x in pressures if x is not None and x > close]
    nearest_support = max(supports) if supports else None
    nearest_pressure = min(pressures) if pressures else None

    # 短線防守：最近大量K支撐 / MA20，取比較接近現價的防守線。
    short_candidates = [x for x in [nearest_sr_support, ma20] if x is not None and x < close]
    short_defense = max(short_candidates) if short_candidates else nearest_support

    # 波段防守：MA60 / 主要大量K支撐，取比較深的防守線。
    swing_candidates = [x for x in [ma60, major_sr_support] if x is not None and x < close]
    swing_defense = min(swing_candidates) if swing_candidates else (ma60 or major_sr_support or nearest_support)

    # 舊欄位保留：fail_line = 波段防守，避免其他舊模組取不到。
    fail_line = swing_defense
    turn_strong = nearest_pressure or to_float(last.get("MA5"))
    return {
        "nearest_support": nearest_support,
        "nearest_pressure": nearest_pressure,
        "nearest_sr_support": nearest_sr_support,
        "major_sr_support": major_sr_support,
        "short_defense": short_defense,
        "swing_defense": swing_defense,
        "ma20": ma20,
        "ma60": ma60,
        "fail_line": fail_line,
        "turn_strong": turn_strong,
    }


def _deduct_state(close: Optional[float], deduct: Optional[float]) -> Tuple[str, Optional[float], str, float]:
    """回傳：狀態、與扣抵值差距%、說明、分數貢獻係數。"""
    gap = pct_change(close, deduct)
    if gap is None:
        return "資料不足", None, "扣抵資料不足", 0.0
    if gap >= 1.0:
        return "順風", gap, "現價高於扣抵值，均線容易上彎", 1.0
    if gap >= 0:
        return "微順風", gap, "現價略高於扣抵值，均線壓力不大", 0.6
    if gap <= -1.0:
        return "逆風", gap, "現價低於扣抵值，均線容易下彎", 0.0
    return "微逆風", gap, "現價略低於扣抵值，短線仍有壓力", 0.3


def compute_ma_deduction(df: pd.DataFrame) -> Dict[str, Any]:
    """計算 5 日 / 20 日扣抵值，用來判斷均線順逆風。

    只使用已完成日K資料，不使用盤中K。
    """
    if df is None or df.empty or len(df) < 25:
        return {
            "state": "資料不足",
            "score_add": 0.0,
            "summary": "K線資料不足，暫不判斷均線扣抵。",
            "rows": [],
            "future_rows": [],
        }

    work = df.copy().sort_values("date").reset_index(drop=True)
    close = to_float(work["close"].iloc[-1])

    rows = []
    score_add = 0.0

    for ma, weight in [(5, 3.0), (20, 5.0)]:
        deduct = to_float(work["close"].iloc[-ma]) if len(work) >= ma else None
        deduct_date = normalize_date_str(work["date"].iloc[-ma]) if len(work) >= ma else "—"
        state, gap, note, factor = _deduct_state(close, deduct)
        add = weight * factor
        score_add += add
        rows.append({
            "項目": f"{ma}日扣抵",
            "扣抵值": deduct,
            "扣抵日": deduct_date,
            "現價差距": gap,
            "狀態": state,
            "解讀": note,
            "分數貢獻": round(add, 1),
        })

    future_rows = []
    for day in range(1, 4):
        item = {"觀察日": f"未來第{day}日"}
        for ma in [5, 20]:
            idx = -ma + (day - 1)
            if abs(idx) <= len(work):
                item[f"{ma}日將扣抵"] = to_float(work["close"].iloc[idx])
                item[f"{ma}日扣抵日"] = normalize_date_str(work["date"].iloc[idx])
            else:
                item[f"{ma}日將扣抵"] = None
                item[f"{ma}日扣抵日"] = "—"
        future_rows.append(item)

    states = {r["項目"]: r["狀態"] for r in rows}
    s5 = states.get("5日扣抵", "資料不足")
    s20 = states.get("20日扣抵", "資料不足")

    if s5 in ["順風", "微順風"] and s20 in ["順風", "微順風"]:
        state = "短線＋波段順風"
        summary = "5日與20日扣抵值皆低於或接近現價，均線結構偏順風。"
        score_add += 2.0
    elif s5 in ["順風", "微順風"] and s20 not in ["順風", "微順風"]:
        state = "短線順風，波段有壓"
        summary = "5日扣抵偏順風，但20日扣抵仍有壓力；短線可彈，波段需確認。"
        score_add += 0.5
    elif s5 not in ["順風", "微順風"] and s20 in ["順風", "微順風"]:
        state = "短線有壓，波段尚可"
        summary = "5日扣抵偏逆風，但20日扣抵仍可支撐；偏震盪，不宜追高。"
        score_add += 0.5
    else:
        state = "短線＋波段逆風"
        summary = "5日與20日扣抵值皆偏高，均線容易形成壓力；反彈需保守看。"

    score_add = max(0.0, min(10.0, score_add))
    return {
        "state": state,
        "score_add": round(score_add, 1),
        "summary": summary,
        "rows": rows,
        "future_rows": future_rows,
    }


