def compute_market_verdict(df: pd.DataFrame, levels: Dict[str, Any], status: Dict[str, Any]) -> Dict[str, Any]:
    if df is None or df.empty or len(df) < 70:
        return {
            "title": "資料不足，先不判斷",
            "light": "灰燈",
            "score": None,
            "max_score": 0,
            "direction": "等待更新",
            "position": "0～2成",
            "version": "資料不足版",
            "confidence": "低",
            "summary": "目前沒有足夠 K 線資料，先按更新資料。",
        }

    last = df.iloc[-1]
    prev = df.iloc[-2]
    close = to_float(last.get("close"))
    ma5 = to_float(last.get("MA5"))
    ma20 = to_float(last.get("MA20"))
    ma60 = to_float(last.get("MA60"))
    ma20_prev = to_float(df["MA20"].iloc[-6]) if len(df) >= 66 else None
    chg = pct_change(close, prev.get("close"))

    score = 0.0
    max_score = 0.0

    # 趨勢結構 30
    max_score += 30
    if close is not None and ma20 is not None and close >= ma20:
        score += 12
    if close is not None and ma60 is not None and close >= ma60:
        score += 8
    if ma20 is not None and ma20_prev is not None and ma20 >= ma20_prev:
        score += 6
    if ma5 is not None and ma20 is not None and ma5 >= ma20:
        score += 4

    # 支撐壓力位置 20
    max_score += 20
    support = to_float(levels.get("nearest_support"))
    pressure = to_float(levels.get("nearest_pressure"))
    if close is not None and support is not None:
        dist_sup = (close - support) / close * 100
        if dist_sup >= 1.0:
            score += 8
        elif dist_sup >= 0:
            score += 5
    if close is not None and pressure is not None:
        dist_pre = (pressure - close) / close * 100
        if dist_pre >= 1.5:
            score += 8
        elif dist_pre >= 0.5:
            score += 5
    if chg is not None and chg >= 0:
        score += 4

    # 均線扣抵壓力 10
    # 5日扣抵看短線順逆風；20日扣抵看波段均線是否容易維持上彎。
    ma_deduction = compute_ma_deduction(df)
    max_score += 10
    score += to_float(ma_deduction.get("score_add")) or 0

    # 其他資料狀態有效權重：v1 先不強灌分數，只依可用性調整版本
    usable_modules = [k for k, v in (status or {}).items() if isinstance(v, dict) and v.get("included")]
    data_ok_count = len(usable_modules)

    ratio = score / max_score * 100 if max_score else 0
    if ratio >= 70:
        title, light, direction, pos = "短線偏多，主流續強", "綠燈", "明日偏多", "5～7成"
    elif ratio >= 55:
        title, light, direction, pos = "震盪偏多，回檔找強勢", "黃燈", "明日震盪偏多", "4～6成"
    elif ratio >= 40:
        title, light, direction, pos = "多空均衡，等待方向表態", "橘燈", "明日震盪", "2～4成"
    else:
        title, light, direction, pos = "短線轉弱，先控部位", "紅燈", "明日偏空震盪", "0～3成"

    if data_ok_count <= 1:
        version = "K線版"
        confidence = "低～中"
    elif data_ok_count <= 3:
        version = "部分資料版"
        confidence = "中"
    else:
        version = "完整盤後版"
        confidence = "中高"

    short_line = fmt_price(levels.get("short_defense"))
    swing_line = fmt_price(levels.get("swing_defense"))
    deduct_text = ma_deduction.get("summary", "")
    summary = (
        f"✏️加權指數收盤：{fmt_price(close)}。<br/>"
        f"✏️短線防守：{short_line}｜最近大量K支撐 / MA20。<br/>"
        f"<span class='summary-indent'>跌破短線防守，先降新倉與追價；未跌破前以震盪偏多處理。</span>"
        f"✏️波段防守：{swing_line}｜MA60 / 主要大量K支撐。<br/>"
        f"<span class='summary-indent'>跌破波段防守，才視為波段結構明顯轉弱。</span>"
        f"✏️均線扣抵：{deduct_text}"
    )

    return {
        "title": title,
        "light": light,
        "score": round(ratio, 1),
        "max_score": 100,
        "raw_score": round(score, 1),
        "raw_max_score": round(max_score, 1),
        "direction": direction,
        "position": pos,
        "version": version,
        "confidence": confidence,
        "summary": summary,
        "change_pct": chg,
        "ma_deduction": ma_deduction,
    }


