def _format_yf_time(x: Any) -> str:
    """將 yfinance 回傳的 Date/Datetime 轉成台北時間短格式。"""
    try:
        dt = pd.to_datetime(x, errors="coerce")
        if pd.isna(dt):
            return ""
        # 盤中 5m 資料通常有時區；日線資料通常只有日期。
        if getattr(dt, "tzinfo", None) is not None:
            dt = dt.tz_convert(TW_TZ) if hasattr(dt, "tz_convert") else dt.astimezone(TW_TZ)
            return dt.strftime("%m/%d %H:%M")
        # 若沒有時間，顯示資料日即可。
        if getattr(dt, "hour", 0) == 0 and getattr(dt, "minute", 0) == 0:
            return dt.strftime("%m/%d")
        return dt.strftime("%m/%d %H:%M")
    except Exception:
        return str(x or "")


def _yf_recent_change(symbol: str) -> Tuple[Optional[float], Optional[float], Optional[float], str, str]:
    yf, err = import_yfinance()
    if yf is None:
        return None, None, None, "", f"yfinance 載入失敗：{err}"
    try:
        # 先抓 5 分鐘資料，讓外部風險雷達更接近盤中狀況；若失敗再回退日線。
        df = yf.download(symbol, period="2d", interval="5m", progress=False, auto_adjust=False, prepost=True)
        source_note = "5m"
        if df is None or df.empty:
            df = yf.download(symbol, period="7d", interval="1d", progress=False, auto_adjust=False)
            source_note = "1d"
        if df is None or df.empty:
            return None, None, None, "", "yfinance 回傳空資料"
        df = flatten_yf_columns(df).reset_index()
        close_col = "Close" if "Close" in df.columns else None
        if close_col is None:
            return None, None, None, "", "缺少 Close 欄位"
        valid = df[df[close_col].apply(to_float).notna()].copy()
        if len(valid) < 2 and source_note == "5m":
            df = yf.download(symbol, period="7d", interval="1d", progress=False, auto_adjust=False)
            source_note = "1d"
            df = flatten_yf_columns(df).reset_index()
            valid = df[df[close_col].apply(to_float).notna()].copy() if close_col in df.columns else pd.DataFrame()
        if len(valid) < 2:
            return None, None, None, "", "有效資料不足"
        last = to_float(valid[close_col].iloc[-1])
        prev = to_float(valid[close_col].iloc[-2])
        chg_pct = pct_change(last, prev)
        diff = None if last is None or prev is None else last - prev
        time_col = "Datetime" if "Datetime" in valid.columns else "Date" if "Date" in valid.columns else valid.columns[0]
        data_time = _format_yf_time(valid[time_col].iloc[-1])
        return last, chg_pct, diff, data_time, source_note
    except Exception as e:
        return None, None, None, "", str(e)


def external_reading(name: str, chg_pct: Optional[float], diff: Optional[float], inverse: bool = False, diff_mode: bool = False) -> Tuple[str, str, float]:
    """回傳：解讀、對台股、分數調整。"""
    if chg_pct is None and diff is None:
        return "資料不足", "不納入", 0.0

    if diff_mode:
        d = to_float(diff) or 0
        if name == "美10年債":
            if d <= -0.05:
                return "殖利率下滑", "高估值壓力降低", 4.0
            if d >= 0.05:
                return "殖利率上升", "高估值股有壓力", -5.0
            return "利率變動不大", "中性", 0.0

    pct = to_float(chg_pct) or 0
    if inverse:
        if pct <= -2:
            return "明顯降溫", "外部壓力下降", 4.0
        if pct < 0:
            return "小幅降溫", "偏多助攻", 2.0
        if pct >= 3:
            return "明顯升溫", "風險壓力上升", -5.0
        if pct > 0:
            return "小幅升溫", "偏空壓力", -2.0
        return "變化不大", "中性", 0.0

    if pct >= 2:
        return "明顯轉強", "偏多助攻", 5.0
    if pct > 0:
        return "小幅轉強", "偏多", 2.0
    if pct <= -2:
        return "明顯轉弱", "偏空壓力", -5.0
    if pct < 0:
        return "小幅轉弱", "偏空", -2.0
    return "變化不大", "中性", 0.0


def fetch_external_risk_snapshot() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    rows = []
    score = 50.0
    ok_count = 0
    errors = []

    for item in EXTERNAL_TICKERS:
        last, chg_pct, diff, data_time, err = _yf_recent_change(item["symbol"])
        reading, impact, raw_adj = external_reading(
            item["name"],
            chg_pct,
            diff,
            inverse=bool(item.get("inverse")),
            diff_mode=bool(item.get("diff_mode")),
        )
        weight = to_float(item.get("weight")) or 1
        adj = raw_adj * (weight / 6.0)
        if last is not None:
            score += adj
            ok_count += 1
        else:
            errors.append(f"{item['name']}:{err}")

        rows.append({
            "指標": item["name"],
            "代號": item["symbol"],
            "分類": item.get("group", ""),
            "最新": last,
            "資料時間": data_time,
            "漲跌幅": chg_pct,
            "差值": diff,
            "解讀": reading,
            "對台股": impact,
            "分數影響": round(adj, 1),
            "錯誤": err,
        })

    score = max(0, min(100, score))
    if score >= 70:
        verdict = "外部助攻"
        summary = "美股科技、風險情緒或匯率條件偏有利，台股隔日承接力較佳。"
    elif score >= 55:
        verdict = "中性偏多"
        summary = "外部環境偏穩，若台股內資與族群續強，可支撐偏多。"
    elif score >= 40:
        verdict = "中性"
        summary = "外部條件沒有明顯助攻，也沒有明顯壓力，仍以台股自身資金為主。"
    elif score >= 30:
        verdict = "外部壓力"
        summary = "外部風險偏高，台股即使內資強也不宜追太滿。"
    else:
        verdict = "風險升溫"
        summary = "外部風險明顯升溫，建議降低追高慾望與部位。"

    snap = {
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "score": round(score, 1),
        "verdict": verdict,
        "summary": summary,
        "rows": rows,
        "source": "Yahoo Finance / yfinance（5m優先，日線備援）",
        "errors": errors[:8],
    }
    status = status_item(
        "ok" if ok_count >= 5 else "partial" if ok_count else "fail",
        ok_count >= 3,
        f"外部指標成功 {ok_count}/{len(EXTERNAL_TICKERS)}；{verdict}",
    )
    return snap, status




