def _num_from_text(x: Any) -> Optional[float]:
    """把 Yahoo / TAIFEX 文字數字轉 float。"""
    try:
        s = str(x or "").strip()
        if not s or s in ["-", "--", "—"]:
            return None
        s = s.replace(",", "").replace("%", "").replace("+", "")
        return float(s)
    except Exception:
        return None


def _quote_dict_for_txf(last: Any, diff: Any = None, pct: Any = None, source: str = "", source_name: str = "台指期近一", time_text: str = "") -> Optional[Dict[str, Any]]:
    last_f = _num_from_text(last)
    if last_f is None:
        return None
    diff_f = _num_from_text(diff)
    pct_f = _num_from_text(pct)

    if pct_f is None and diff_f is not None and last_f not in [None, 0]:
        prev = last_f - diff_f
        if prev:
            pct_f = diff_f / prev * 100

    return {
        "指標": "台指近全",
        "代號": "WTX&",
        "分類": "台股期貨",
        "最新": last_f,
        "資料時間": time_text or now_tw().strftime("%m/%d %H:%M"),
        "漲跌幅": pct_f,
        "差值": diff_f,
        "解讀": "台指期近一",
        "對台股": "台指近",
        "分數影響": 0,
        "錯誤": "",
        "來源名稱": source_name,
        "來源": source,
    }


def fetch_yahoo_txf_near_quote() -> Optional[Dict[str, Any]]:
    """備援來源：Yahoo 台股期權頁，抓「台指期近一 WTX&」。

    目的：
    - TAIFEX MIS 在 Replit / 行動網頁環境常抓不到或欄位變動。
    - Yahoo 期權頁通常會列出台指期近一、成交價、漲跌、漲跌幅。
    """
    try:
        url = "https://tw.stock.yahoo.com/future"
        r = requests.get(
            url,
            headers={
                "User-Agent": "Mozilla/5.0",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "zh-TW,zh;q=0.9,en;q=0.8",
            },
            timeout=REQUEST_TIMEOUT,
        )
        if r.status_code != 200 or not r.text:
            return None

        raw = html.unescape(r.text)
        # 先把 script/style 拿掉，再去除 tags，方便用文字位置解析。
        raw = re.sub(r"<script[\s\S]*?</script>", " ", raw, flags=re.I)
        raw = re.sub(r"<style[\s\S]*?</style>", " ", raw, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", raw)
        text = re.sub(r"\s+", " ", text)

        pos = text.find("台指期近一")
        if pos < 0:
            return None
        row = text[pos:pos + 900]

        # 常見欄位順序：
        # 台指期近一 WTX& 買價 賣價 成交價 漲跌 漲跌幅 成交量 開盤 最高 最低 價差 參考價 未平倉 時間
        # 允許中間有 -。
        m = re.search(
            r"台指期近一\s+WTX&\s+([+\-]?[0-9,]+(?:\.[0-9]+)?|-)\s+([+\-]?[0-9,]+(?:\.[0-9]+)?|-)\s+([+\-]?[0-9,]+(?:\.[0-9]+)?|-)\s+([+\-]?[0-9,]+(?:\.[0-9]+)?|-)\s+([+\-]?[0-9,]+(?:\.[0-9]+)?)%",
            row
        )
        if not m:
            # 備援：從 row 裡抓前幾個數字，第三個多半是成交價、第四個漲跌、第五個漲跌幅。
            nums = re.findall(r"[+\-]?[0-9,]+(?:\.[0-9]+)?%?", row)
            # 避免日期/時間混進來，先找 WTX& 後面的區段。
            row2 = row.split("WTX&", 1)[-1] if "WTX&" in row else row
            nums = re.findall(r"[+\-]?[0-9,]+(?:\.[0-9]+)?%?", row2)
            if len(nums) < 5:
                return None
            bid, ask, last, diff, pct = nums[0], nums[1], nums[2], nums[3], nums[4]
        else:
            bid, ask, last, diff, pct = m.groups()

        last_f = _num_from_text(last)
        if last_f is None:
            bid_f = _num_from_text(bid)
            ask_f = _num_from_text(ask)
            if bid_f is not None and ask_f is not None:
                last_f = (bid_f + ask_f) / 2
            else:
                return None

        # 抓列尾時間，沒有就用目前時間。
        tm = ""
        mt = re.search(r"(\d{2}:\d{2}:\d{2})", row)
        if mt:
            tm = mt.group(1)

        return _quote_dict_for_txf(
            last=last_f,
            diff=diff,
            pct=pct,
            source="Yahoo 台股期權頁",
            source_name="台指期近一 WTX&",
            time_text=tm,
        )
    except Exception:
        return None


def fetch_taifex_txf_night_quote() -> Optional[Dict[str, Any]]:
    """嘗試抓台指近全 / 台指期即時資料。

    v209：
    1. 先試 TAIFEX MIS。
    2. TAIFEX 失敗時，改抓 Yahoo 台股期權頁「台指期近一 WTX&」。
    """
    def _pick_float(obj: Dict[str, Any], keys: List[str]) -> Optional[float]:
        for k in keys:
            if k in obj:
                raw = obj.get(k)
                if raw in [None, "", "-", "--", "—"]:
                    continue
                v = _num_from_text(raw)
                if v is not None:
                    return v
        return None

    def _pick_text(obj: Dict[str, Any], keys: List[str]) -> str:
        for k in keys:
            if k in obj and str(obj.get(k) or "").strip():
                return str(obj.get(k)).strip()
        return ""

    last_keys = [
        "CLastPrice", "LastPrice", "Last", "Price", "LastPx", "Close", "CClosingPrice",
        "LatestPrice", "成交價", "最新價", "最新"
    ]
    pct_keys = [
        "CChangeRate", "ChangeRate", "CPercent", "Percent", "ChangePercent", "Pct",
        "ChgRate", "CChgRate", "漲跌幅", "漲跌%"
    ]
    diff_keys = [
        "CDiff", "Diff", "Change", "NetChange", "CChange", "PriceChange",
        "UpDown", "CUpDownPrice", "漲跌", "漲跌點"
    ]
    ref_keys = [
        "CRefPrice", "ReferencePrice", "RefPrice", "PrevClose", "PreviousClose",
        "YClose", "PreClose", "SettlementPrice", "CSettlementPrice", "昨收", "參考價"
    ]

    # Source 1｜TAIFEX
    try:
        sess = requests.Session()
        headers = {
            "User-Agent": "Mozilla/5.0",
            "Referer": "https://mis.taifex.com.tw/futures/",
            "Accept": "application/json,text/plain,*/*",
        }
        try:
            sess.get("https://mis.taifex.com.tw/futures/", headers=headers, timeout=REQUEST_TIMEOUT)
        except Exception:
            pass

        url = "https://mis.taifex.com.tw/futures/api/getQuoteList"
        param_sets = [
            {"MarketType": "1", "SymbolType": "F", "KindID": "1", "CID": "TXF"},
            {"MarketType": "0", "SymbolType": "F", "KindID": "1", "CID": "TXF"},
        ]

        for params in param_sets:
            r = sess.get(url, params=params, headers=headers, timeout=REQUEST_TIMEOUT)
            if r.status_code != 200 or not r.text:
                continue

            try:
                data = r.json()
            except Exception:
                continue

            qlist = []
            if isinstance(data, dict):
                rt = data.get("RtData") or data.get("rtData") or data.get("RtDataQuoteList") or data
                if isinstance(rt, dict):
                    qlist = (
                        rt.get("QuoteList")
                        or rt.get("quoteList")
                        or rt.get("Data")
                        or rt.get("data")
                        or rt.get("Quote")
                        or []
                    )
                elif isinstance(rt, list):
                    qlist = rt
            elif isinstance(data, list):
                qlist = data

            if not isinstance(qlist, list):
                continue

            candidates = []
            for q in qlist:
                if not isinstance(q, dict):
                    continue
                text = " ".join(str(v) for v in q.values())
                symbol = str(q.get("SymbolID") or q.get("Symbol") or q.get("CID") or q.get("CommodityID") or "")
                if ("TXF" in text) or ("TXF" in symbol) or ("台指" in text) or ("臺指" in text) or ("近月" in text) or ("近全" in text):
                    candidates.append(q)
            if not candidates and qlist:
                candidates = [q for q in qlist if isinstance(q, dict)]

            for q in candidates:
                name = _pick_text(q, ["DispCName", "CName", "Name", "SymbolName", "CommodityName", "商品名稱"]) or "台指近全"
                last = _pick_float(q, last_keys)
                pct = _pick_float(q, pct_keys)
                diff = _pick_float(q, diff_keys)
                ref = _pick_float(q, ref_keys)

                if last is not None and ref not in [None, 0]:
                    if diff is None:
                        diff = last - ref
                    if pct is None:
                        pct = (last - ref) / ref * 100

                if pct is None and last not in [None, 0] and diff is not None:
                    prev = last - diff
                    if prev:
                        pct = diff / prev * 100

                if last is None:
                    continue

                time_text = _pick_text(q, ["CTime", "Time", "QuoteTime", "時間"]) or now_tw().strftime("%m/%d %H:%M")
                market_type = params.get("MarketType")

                out = _quote_dict_for_txf(
                    last=last,
                    diff=diff,
                    pct=pct,
                    source=f"TAIFEX MIS MarketType={market_type}",
                    source_name=name,
                    time_text=time_text,
                )
                if out:
                    out["MarketType"] = market_type
                    return out
    except Exception:
        pass

    # Source 2｜Yahoo 台股期權頁
    return fetch_yahoo_txf_near_quote()



def fetch_night_session_snapshot() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """抓夜盤/外盤即時校正資料。

    定位：
    - 不推翻台股收盤裁決。
    - 只校正明天開盤前的風險：美股科技、費半、ADR、VIX、利率、匯率。
    """
    rows: List[Dict[str, Any]] = []
    primary_pct = None
    txf_quote = fetch_taifex_txf_night_quote()
    txf_ok = bool(txf_quote)
    if txf_quote:
        rows.append(txf_quote)
        primary_pct = to_float(txf_quote.get("漲跌幅"))

    score = 50.0
    ok_count = 0
    errors: List[str] = []
    if not txf_ok:
        errors.append("台指近全:TAIFEX/Yahoo未取得")

    for item in NIGHT_SESSION_TICKERS:
        last, chg_pct, diff, data_time, err = _yf_recent_change(item["symbol"])
        reading, impact, raw_adj = external_reading(
            item["name"],
            chg_pct,
            diff,
            inverse=bool(item.get("inverse")),
            diff_mode=bool(item.get("diff_mode")),
        )
        weight = to_float(item.get("weight")) or 1
        adj = raw_adj * (weight / 6.0)
        if last is not None:
            score += adj
            ok_count += 1
        else:
            errors.append(f"{item['name']}:{err}")

        rows.append({
            "指標": item["name"],
            "代號": item["symbol"],
            "分類": item.get("group", ""),
            "最新": last,
            "資料時間": data_time,
            "漲跌幅": chg_pct,
            "差值": diff,
            "解讀": reading,
            "對台股": impact,
            "分數影響": round(adj, 1),
            "錯誤": err,
        })

    score = max(0, min(100, score))

    if score >= 68:
        verdict = "夜盤偏多"
        tone = "外部助攻"
        reminder = "明天可看主流延續，但若開高太多，先等量能與回檔承接，不追第一根。"
    elif score >= 55:
        verdict = "夜盤中性偏多"
        tone = "偏多但不亢奮"
        reminder = "明天仍可照原本偏多策略，但優先找回檔承接與資金延續，不追高。"
    elif score >= 45:
        verdict = "夜盤中性"
        tone = "外部不干擾"
        reminder = "夜盤沒有明顯改變方向，明天仍以台股資金分流與族群強度為主。"
    elif score >= 35:
        verdict = "夜盤偏空"
        tone = "開盤需防震盪"
        reminder = "今天盤勢若偏多，明天也先看開盤是否回測短線防守；新倉保守，不急追。"
    else:
        verdict = "夜盤明顯偏空"
        tone = "風險升溫"
        reminder = "明天先防開低或急殺，優先看短線防守 / 波段防守是否守住，不急開新倉。"

    snap = {
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "score": round(score, 1),
        "verdict": verdict,
        "tone": tone,
        "reminder": reminder,
        "rows": rows,
        "primary_pct": primary_pct,
        "source": "TAIFEX（若可用）+ Yahoo Finance / yfinance（5m優先，日線備援）",
        "errors": errors[:8],
    }
    status = status_item(
        "ok" if ok_count >= 5 else "partial" if ok_count else "fail",
        ok_count >= 3,
        f"台指近{'已取得' if txf_ok else '未取得'}（TAIFEX/Yahoo）｜外部指標 {ok_count}/{len(NIGHT_SESSION_TICKERS)}；{verdict}",
    )
    return snap, status


def update_night_session(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    night, status = fetch_night_session_snapshot()
    snapshot["night_session"] = night
    statuses = snapshot.get("statuses") or {}
    statuses["夜盤校正"] = status
    snapshot["statuses"] = statuses
    add_log(snapshot, "更新夜盤校正", status.get("note", "完成"))
    save_snapshot(snapshot)
    return snapshot


