def _classify_news_title(title: str, default_cat: str) -> Tuple[str, str, int, str]:
    t = str(title or "")
    risk_words = ["利空", "下修", "降評", "砍單", "衰退", "虧損", "重挫", "賣超", "急貶", "警示", "注意股", "處置", "匯損", "裁員"]
    good_words = ["利多", "上修", "創高", "買超", "成長", "續強", "受惠", "擴產", "旺", "轉強", "大漲", "突破", "優於預期"]
    theme_words = ["AI", "伺服器", "PCB", "半導體", "重電", "機器人", "航運", "金融", "生技", "光通訊", "CPO", "散熱"]

    score = 0
    if any(w in t for w in good_words):
        score += 1
    if any(w in t for w in risk_words):
        score -= 1

    if any(w in t for w in risk_words):
        cat = "風險新聞"
    elif any(w in t for w in theme_words):
        cat = "族群題材"
    elif any(w in t for w in ["美股", "Fed", "聯準會", "費半", "Nasdaq", "VIX", "美債", "美元"]):
        cat = "國際市場"
    elif any(w in t for w in ["法說", "營收", "財報", "重大訊息", "公告"]):
        cat = "個股重大"
    else:
        cat = default_cat

    if score > 0:
        sentiment, impact = "偏多", "可解釋資金流入或風險偏好改善"
    elif score < 0:
        sentiment, impact = "偏空", "需留意資金退潮或開盤壓力"
    else:
        sentiment, impact = "中性", "僅作背景觀察"
    return cat, sentiment, score, impact


def _parse_google_news_time(x: Optional[str]) -> str:
    if not x:
        return ""
    try:
        dt = parsedate_to_datetime(x)
        if dt.tzinfo:
            dt = dt.astimezone(TW_TZ)
        return dt.strftime("%Y-%m-%d %H:%M")
    except Exception:
        return str(x)


def fetch_google_news_rss(query: str, category: str, limit: int = 6) -> List[Dict[str, Any]]:
    q = quote_plus(f"{query} when:2d")
    url = f"https://news.google.com/rss/search?q={q}&hl=zh-TW&gl=TW&ceid=TW:zh-Hant"
    r = requests.get(url, timeout=REQUEST_TIMEOUT, headers={"User-Agent": "Mozilla/5.0"})
    r.raise_for_status()
    root = ET.fromstring(r.content)
    rows = []
    for item in root.findall(".//item")[:limit]:
        title = (item.findtext("title") or "").strip()
        link = (item.findtext("link") or "").strip()
        source_el = item.find("source")
        source = source_el.text.strip() if source_el is not None and source_el.text else ""
        pub = _parse_google_news_time(item.findtext("pubDate"))
        cat, sentiment, score, impact = _classify_news_title(title, category)
        rows.append({
            "分類": cat,
            "標題": title,
            "來源": source,
            "時間": pub,
            "判斷": sentiment,
            "影響": impact,
            "分數": score,
            "連結": link,
        })
    return rows


def fetch_news_snapshot() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    rows = []
    errors = []
    seen = set()
    for category, query in NEWS_QUERIES:
        try:
            items = fetch_google_news_rss(query, category, limit=7)
            for item in items:
                key = item.get("標題")
                if not key or key in seen:
                    continue
                seen.add(key)
                rows.append(item)
        except Exception as e:
            errors.append(f"{category}:{e}")

    pos = sum(1 for r in rows if r.get("判斷") == "偏多")
    neg = sum(1 for r in rows if r.get("判斷") == "偏空")
    neu = sum(1 for r in rows if r.get("判斷") == "中性")

    score = max(0, min(100, 50 + pos * 3 - neg * 4))
    if pos >= 3 and neg >= 3:
        verdict = "新聞分歧"
        summary = "利多與利空同時存在，新聞只作解釋，仍以資金流向與K線為主。"
    elif score >= 62:
        verdict = "新聞偏多"
        summary = "新聞面偏多，可解釋資金風險偏好或主流族群延續。"
    elif score <= 42:
        verdict = "新聞偏空"
        summary = "新聞面偏空，留意開盤壓力、法人調節或族群退潮。"
    else:
        verdict = "新聞中性"
        summary = "新聞沒有明確改變盤勢方向，仍以價量與資金流向為主。"

    snap = {
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "score": round(score, 1),
        "verdict": verdict,
        "summary": summary,
        "positive_count": pos,
        "negative_count": neg,
        "neutral_count": neu,
        "rows": rows[:40],
        "source": "Google News RSS",
        "errors": errors[:8],
    }
    status = status_item(
        "ok" if len(rows) >= 8 else "partial" if rows else "fail",
        len(rows) >= 5,
        f"新聞 {len(rows)} 則；{verdict}",
    )
    return snap, status


def verdict_from_score(score: float) -> Tuple[str, str, str, str]:
    if score >= 70:
        return "短線偏多，主流續強", "綠燈", "明日偏多", "5～7成"
    if score >= 55:
        return "震盪偏多，回檔找強勢", "黃燈", "明日震盪偏多", "4～6成"
    if score >= 40:
        return "多空均衡，等待方向表態", "橘燈", "明日震盪", "2～4成"
    return "短線轉弱，先控部位", "紅燈", "明日偏空震盪", "0～3成"


def apply_context_to_verdict(verdict: Dict[str, Any], snapshot: Dict[str, Any]) -> Dict[str, Any]:
    """外部風險與新聞只做校正，不取代台股K線/資金流向主判斷。"""
    if not verdict or verdict.get("score") is None:
        return verdict

    base_score = to_float(verdict.get("score"))
    if base_score is None:
        return verdict

    ext = snapshot.get("external") or {}
    news = snapshot.get("news") or {}
    ext_score = to_float(ext.get("score"))
    news_score = to_float(news.get("score"))

    adj = 0.0
    notes = []
    if ext_score is not None:
        # 外部風險權重約 15%
        ext_adj = (ext_score - 50) * 0.16
        adj += ext_adj
        notes.append(f"外部：{ext.get('verdict', '—')} {ext_score:.1f}分")
    if news_score is not None:
        # 新聞權重約 8%，只做解釋與微調
        news_adj = (news_score - 50) * 0.08
        adj += news_adj
        notes.append(f"新聞：{news.get('verdict', '—')} {news_score:.1f}分")

    if not notes:
        return verdict

    new_score = max(0, min(100, base_score + adj))
    title, light, direction, pos = verdict_from_score(new_score)
    out = dict(verdict)
    out["base_score"] = round(base_score, 1)
    out["context_adjustment"] = round(adj, 1)
    out["score"] = round(new_score, 1)
    out["title"] = title
    out["light"] = light
    out["direction"] = direction
    out["position"] = pos
    out["version"] = f"{out.get('version', '盤後版')}＋外部/新聞校正"
    base_summary = str(out.get("summary", "") or "").strip()
    context_lines = "<br/>".join(f"✏️{n}" for n in notes)
    out["summary"] = (base_summary + "<br/>" + context_lines).strip("<br/>")
    return out


