def parse_twse_price(x: Any) -> Optional[float]:
    s = str(x or "").strip().replace(",", "")
    if s in ["", "--", "-", "X", "除權", "除息"]:
        return None
    # TWSE OpenAPI 有時漲跌價差會帶 + / - 或特殊字元
    s = s.replace("+", "").replace("−", "-").replace("△", "").replace("▽", "-")
    return to_float(s)


def fetch_twse_daily_all() -> Tuple[pd.DataFrame, str]:
    """抓上市＋上櫃全市場日行情，用於聯網找候選股。

    v1.4.5：
    - TWSE 上市：openapi.twse.com.tw
    - TPEx 上櫃：tpex.org.tw openapi
    - 兩邊合併後再做成交金額 / 漲跌幅篩選，讓中小型上櫃題材股不會漏掉。
    """
    frames = []
    sources = []
    errors = []

    # --- TWSE 上市 ---
    urls = [
        "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL",
        "https://openapi.twse.com.tw/v1/exchangeReport/MI_INDEX20",
    ]
    last_err = ""
    for url in urls:
        try:
            r = requests.get(url, timeout=REQUEST_TIMEOUT, headers={"User-Agent": "Mozilla/5.0"})
            if r.status_code != 200:
                last_err = f"TWSE HTTP {r.status_code}"
                continue
            data = r.json()
            if not isinstance(data, list) or not data:
                last_err = "TWSE 回傳資料空白"
                continue
            df = pd.DataFrame(data)
            code_col = "Code" if "Code" in df.columns else "證券代號" if "證券代號" in df.columns else None
            name_col = "Name" if "Name" in df.columns else "證券名稱" if "證券名稱" in df.columns else None
            close_col = "ClosingPrice" if "ClosingPrice" in df.columns else "收盤價" if "收盤價" in df.columns else None
            change_col = "Change" if "Change" in df.columns else "漲跌價差" if "漲跌價差" in df.columns else None
            value_col = "TradeValue" if "TradeValue" in df.columns else "成交金額" if "成交金額" in df.columns else None
            volume_col = "TradeVolume" if "TradeVolume" in df.columns else "成交股數" if "成交股數" in df.columns else None
            if not all([code_col, name_col, close_col, change_col, value_col]):
                last_err = f"TWSE 欄位不足：{list(df.columns)[:8]}"
                continue
            out = pd.DataFrame({
                "stock_id": df[code_col].apply(clean_stock_id),
                "stock_name": df[name_col].astype(str),
                "close": df[close_col].apply(parse_twse_price),
                "change": df[change_col].apply(parse_twse_price),
                "trade_value": df[value_col].apply(parse_twse_price),
                "trade_volume": df[volume_col].apply(parse_twse_price) if volume_col else None,
                "market": "TWSE",
            })
            out = out[out["stock_id"].apply(is_common_stock_id)].copy()
            out = out.dropna(subset=["close", "trade_value"])
            out = out[out["close"] > 5]
            out["prev_close"] = out["close"] - out["change"].fillna(0)
            out["change_pct"] = out.apply(lambda x: pct_change(x["close"], x["prev_close"]), axis=1)
            out = out.dropna(subset=["change_pct"])
            if out.empty:
                last_err = "TWSE 清洗後資料空白"
                continue
            frames.append(out.reset_index(drop=True))
            sources.append("TWSE OpenAPI")
            break
        except Exception as e:
            last_err = f"TWSE {e}"
    if last_err and not any(s == "TWSE OpenAPI" for s in sources):
        errors.append(last_err)

    # --- TPEx 上櫃 ---
    try:
        tpex_rows, tpex_err = _wmf_fetch_tpex_quotes()
        if tpex_rows:
            tdf = pd.DataFrame(tpex_rows)
            tout = pd.DataFrame({
                "stock_id": tdf["code"].apply(clean_stock_id),
                "stock_name": tdf["name"].astype(str),
                "close": tdf["close"].apply(to_float),
                "change": tdf["change"].apply(to_float),
                "trade_value": tdf["trade_value"].apply(to_float),
                "trade_volume": tdf["volume"].apply(to_float) if "volume" in tdf.columns else None,
                "change_pct": tdf["change_pct"].apply(to_float),
                "market": "TPEx",
            })
            tout = tout[tout["stock_id"].apply(is_common_stock_id)].copy()
            tout = tout.dropna(subset=["close", "trade_value", "change_pct"])
            tout = tout[tout["close"] > 5]
            if not tout.empty:
                frames.append(tout.reset_index(drop=True))
                sources.append("TPEx OpenAPI")
        elif tpex_err:
            errors.append(tpex_err)
    except Exception as e:
        errors.append(f"TPEx {e}")

    if not frames:
        return pd.DataFrame(), "；".join(errors) or "TWSE/TPEx OpenAPI 無法取得資料"

    combined = pd.concat(frames, ignore_index=True)
    combined = combined.drop_duplicates(subset=["stock_id"], keep="first")
    return combined.reset_index(drop=True), " + ".join(sources) + (f"｜部分錯誤：{'；'.join(errors)}" if errors else "")


def fetch_finmind_stock_info_map() -> Tuple[Dict[str, Dict[str, Any]], str]:
    """用 FinMind 抓產業分類，失敗時仍可用名稱規則分類。"""
    try:
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {"dataset": "TaiwanStockInfo"}
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT, headers=finmind_headers())
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            return {}, "FinMind 無資料"
        df = pd.DataFrame(data)
        if "stock_id" not in df.columns:
            return {}, "FinMind 欄位不完整"
        info: Dict[str, Dict[str, Any]] = {}
        for _, row in df.iterrows():
            sid = clean_stock_id(row.get("stock_id"))
            if not is_common_stock_id(sid):
                continue
            info[sid] = {
                "stock_name": str(row.get("stock_name") or row.get("name") or ""),
                "industry_category": str(row.get("industry_category") or ""),
                "type": str(row.get("type") or ""),
            }
        return info, "FinMind TaiwanStockInfo"
    except Exception as e:
        return {}, f"FinMind 失敗：{e}"


def guess_sector_for_stock(stock_id: str, stock_name: str, industry: str = "") -> Optional[str]:
    """用股票名稱 + FinMind 產業分類做主題歸類。
    找不到時回傳 None，交給「未分類強勢資金池」防漏。
    """
    name = str(stock_name or "")
    ind = str(industry or "")
    text = f"{stock_id} {name} {ind}"

    rules = [
        ("光通訊/CPO", ["聯亞", "華星光", "波若威", "上詮", "聯鈞", "前鼎", "眾達", "光通訊", "光纖", "CPO"]),
        ("AI伺服器", ["廣達", "緯穎", "緯創", "英業達", "技嘉", "華擎", "勤誠", "晟銘電", "神達", "伺服器", "電腦及週邊"]),
        ("矽智財/IP", ["力旺", "晶心", "M31", "矽智財", "IP", "ASIC"]),
        ("IC設計", ["聯發科", "創意", "信驊", "義隆", "聯詠", "瑞昱", "原相", "世芯", "IC設計", "半導體業"]),
        ("半導體設備", ["弘塑", "辛耘", "萬潤", "信紘科", "均豪", "京鼎", "由田", "志聖", "半導體設備", "設備", "無塵", "晶圓"]),
        ("先進封裝", ["精測", "旺矽", "京元電子", "日月光", "封裝", "測試", "CoWoS", "先進封裝"]),
        ("ABF載板", ["景碩", "南電", "ABF", "載板"]),
        ("PCB", ["台光電", "台燿", "欣興", "金居", "金像電", "臻鼎", "燿華", "嘉聯益", "PCB", "CCL", "銅箔基板", "印刷電路"]),
        ("散熱", ["奇鋐", "雙鴻", "健策", "建準", "尼得科", "散熱", "水冷", "液冷"]),
        ("連接器", ["嘉澤", "貿聯", "正崴", "詮欣", "宏致", "胡連", "連接器", "線束"]),
        ("DRAM", ["南亞科", "華邦電", "晶豪科", "威剛", "十銓", "群聯", "記憶體", "DRAM", "Flash", "NAND"]),
        ("AI PC/邊緣AI", ["華碩", "宏碁", "微星", "AI PC", "邊緣AI"]),
        ("網通設備", ["智邦", "啟碁", "中磊", "智易", "明泰", "正文", "網通", "通信網路"]),
        ("低軌衛星", ["昇達科", "台揚", "低軌", "衛星", "航太"]),
        ("重電/電力設備", ["東元", "中興電", "亞力", "華城", "大亞", "合機", "士電", "電力", "重電", "電線電纜", "電機機械"]),
        ("綠能/儲能", ["森崴", "元晶", "聯合再生", "國碩", "太陽能", "綠能", "儲能", "再生能源"]),
        ("機器人/自動化", ["上銀", "亞德客", "所羅門", "盟立", "和椿", "機器人", "自動化", "工具機"]),
        ("電動車零件", ["和大", "為升", "胡連", "車", "汽車", "電動車", "汽車工業"]),
        ("電源管理", ["台達電", "矽力", "電源", "電源管理", "電池"]),
        ("被動元件", ["國巨", "華新科", "奇力新", "信昌電", "禾伸堂", "被動", "電阻", "電容", "電感"]),
        ("面板", ["友達", "群創", "彩晶", "元太", "面板", "光電業", "電子紙"]),
        ("資安/軟體", ["零壹", "精誠", "大世科", "訊連", "資訊服務", "軟體", "資安", "雲端"]),
        ("金融保險", ["富邦金", "國泰金", "中信金", "兆豐金", "玉山金", "銀行", "保險", "金融保險"]),
        ("軍工/航太", ["漢翔", "寶一", "晟田", "駐龍", "雷虎", "軍工", "航太", "無人機"]),
        ("航運", ["長榮", "陽明", "萬海", "長榮航", "華航", "台航", "航運", "海運", "航空"]),
        ("觀光餐飲", ["王品", "八方", "晶華", "雄獅", "雲品", "觀光", "餐飲", "飯店", "旅行"]),
        ("營建資產", ["興富發", "華固", "中工", "遠雄", "櫻花建", "營建", "建材營造", "資產"]),
        ("生技醫療", ["藥華", "保瑞", "中裕", "智擎", "高端", "生技", "醫療", "製藥"]),
        ("塑化", ["台塑", "南亞", "台化", "台塑化", "中石化", "塑膠", "化工", "油電燃氣"]),
        ("鋼鐵", ["中鋼", "中鴻", "大成鋼", "新光鋼", "世紀鋼", "鋼鐵"]),
        ("水泥", ["台泥", "亞泥", "嘉泥", "環泥", "水泥"]),
        ("造紙", ["正隆", "華紙", "永豐餘", "榮成", "造紙"]),
    ]
    for sector, keywords in rules:
        if any(k in text for k in keywords):
            return sector

    # 電子以外先歸到傳產大池，但仍會在 discovery 裡保留產業欄位。
    if ind and not any(k in ind for k in ["半導體", "電子", "光電", "通信", "資訊", "電腦", "其他電子"]):
        return "傳統產業"
    return None


def discover_online_candidates(max_per_sector: int = 3, top_n_pool: int = 120, min_trade_value_billion: float = 0.5) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, List[Dict[str, Any]]]]:
    """聯網找候選標的，回傳 discovery、status、discovered_pool。

    v1.4.5 改版重點：
    1. 擴充正式族群。
    2. 找不到正式族群時，不丟掉，改放「未分類強勢資金池」。
    3. 聯網候選股不再拆成「今日新冒出族群 / 已歸類候選股」兩張表，改為一張完整候選清單。
    """
    try:
        qdf, qsrc = fetch_twse_daily_all()
        if qdf.empty:
            return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "rows": [], "unclassified_rows": [], "emerging": []}, status_item("fail", False, f"行情抓取失敗：{qsrc}"), {}

        info_map, info_src = fetch_finmind_stock_info_map()
        min_value = float(min_trade_value_billion) * 100_000_000
        work = qdf[qdf["trade_value"].fillna(0) >= min_value].copy()
        if work.empty:
            work = qdf.copy()

        # 成交金額 + 漲跌幅共同排序，抓「今天市場真的有看」的股票。
        work["amount_rank_score"] = work["trade_value"].rank(pct=True) * 55
        work["change_score"] = work["change_pct"].apply(lambda x: clamp((to_float(x) or 0) + 5, 0, 12) / 12 * 35)
        work["hot_score"] = work["amount_rank_score"] + work["change_score"]
        work = work.sort_values(["hot_score", "trade_value"], ascending=False).head(int(top_n_pool))

        rows: List[Dict[str, Any]] = []
        unclassified_rows: List[Dict[str, Any]] = []
        pool: Dict[str, List[Dict[str, Any]]] = {k: [] for k in SECTOR_STOCK_POOL.keys()}
        seen_by_sector: Dict[str, set] = {k: set() for k in SECTOR_STOCK_POOL.keys()}

        for _, row in work.iterrows():
            sid = clean_stock_id(row.get("stock_id"))
            name = str(row.get("stock_name") or "")
            info = info_map.get(sid, {})
            industry = str(info.get("industry_category") or "")
            sector = guess_sector_for_stock(sid, name, industry)
            is_unclassified = False
            if not sector or sector not in pool:
                sector = "未分類強勢資金池"
                is_unclassified = True

            if sid in seen_by_sector[sector]:
                continue

            item = {
                "sector": sector,
                "stock_id": sid,
                "stock_name": name,
                "industry": industry or "—",
                "close": to_float(row.get("close")),
                "change_pct": to_float(row.get("change_pct")),
                "trade_value": to_float(row.get("trade_value")),
                "hot_score": to_float(row.get("hot_score")),
                "reason": "未對應正式族群，但成交金額/漲跌幅異動，先放入防漏池" if is_unclassified else "成交金額放大＋族群/產業對應，列入候選",
            }
            pool[sector].append(item)
            seen_by_sector[sector].add(sid)
            rows.append(item)
            if is_unclassified:
                unclassified_rows.append(item)

        # 每個族群只保留前 N 檔，避免後續掃描太重；未分類防漏池保留更多一點。
        trimmed_pool: Dict[str, List[Dict[str, Any]]] = {}
        trimmed_rows: List[Dict[str, Any]] = []
        for sector, items in pool.items():
            if not items:
                continue
            keep_n = int(max_per_sector) if sector != "未分類強勢資金池" else max(int(max_per_sector) * 2, 5)
            items = sorted(items, key=lambda x: (to_float(x.get("trade_value")) or 0), reverse=True)[:keep_n]
            trimmed_pool[sector] = items
            trimmed_rows.extend(items)

        if not trimmed_rows:
            return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "rows": [], "unclassified_rows": [], "emerging": []}, status_item("fail", False, "有抓到行情，但無有效候選"), {}

        # 今日新冒出族群：至少 2 檔入選，或單一族群成交金額很大。
        emerging = []
        sector_df = pd.DataFrame(trimmed_rows)
        if not sector_df.empty:
            for sector, sdf in sector_df.groupby("sector"):
                if sector == "未分類強勢資金池":
                    continue
                total_value = float(sdf["trade_value"].apply(to_float).fillna(0).sum())
                avg_chg = sdf["change_pct"].apply(to_float).dropna().mean()
                count = len(sdf)
                if count >= 2 or total_value >= 2_000_000_000:
                    growth_candidates = 0
                    for _, rr in sdf.iterrows():
                        chg = to_float(rr.get("change_pct"))
                        tv = to_float(rr.get("trade_value")) or 0
                        # v165｜初步成長股候選：不是爆噴，成交金額有感，仍可後續進雷達確認。
                        if chg is not None and -3 <= chg <= 10 and tv >= 500_000_000:
                            growth_candidates += 1

                    spread = "多檔擴散" if count >= 3 else ("初步擴散" if count == 2 else "單點異動")
                    emerging.append({
                        "族群": sector,
                        "候選檔數": count,
                        "今日候選數": count,
                        "成交金額(億)": round(total_value / 100_000_000, 2),
                        "平均漲跌": None if pd.isna(avg_chg) else round(float(avg_chg), 2),
                        "成長股候選": growth_candidates,
                        "主力擴散": spread,
                        "提醒": "資金有異動，建議納入追蹤",
                    })
            emerging = sorted(
                emerging,
                key=lambda x: (
                    x.get("成長股候選", 0),
                    x.get("候選檔數", 0),
                    x.get("成交金額(億)", 0),
                    x.get("平均漲跌") or 0,
                ),
                reverse=True,
            )[:12]

        discovery = {
            "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
            "source": f"{qsrc} + {info_src}",
            "max_per_sector": max_per_sector,
            "rows": trimmed_rows,
            "unclassified_rows": [x for x in trimmed_rows if x.get("sector") == "未分類強勢資金池"],
            "emerging": emerging,
        }
        unclassified_count = len(discovery.get("unclassified_rows") or [])
        return discovery, status_item("ok", True, f"聯網新增 {len(trimmed_rows)} 檔候選；防漏池 {unclassified_count} 檔，後續掃描會納入"), trimmed_pool
    except Exception as e:
        return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "rows": [], "unclassified_rows": [], "emerging": []}, status_item("fail", False, f"聯網新增失敗：{e}"), {}


# =========================================================
# 資金流向：更新時才掃股票池價格
# =========================================================
_TWII_BETA_RETURNS_CACHE: Dict[str, Any] = {}


def fetch_twii_returns_for_beta(yf, period: str = "6mo") -> Optional[pd.Series]:
    """v215｜供低基期吃貨 Beta 使用的加權指數報酬快取。

    只抓一次 ^TWII，避免每檔個股都重抓造成掃描變慢。
    """
    global _TWII_BETA_RETURNS_CACHE
    key = str(period or "6mo")
    if key in _TWII_BETA_RETURNS_CACHE:
        return _TWII_BETA_RETURNS_CACHE.get(key)
    try:
        mdf = yf.download("^TWII", period=key, interval="1d", progress=False, auto_adjust=False)
        if mdf is None or mdf.empty:
            _TWII_BETA_RETURNS_CACHE[key] = None
            return None
        mdf = flatten_yf_columns(mdf)
        mclose = mdf["Close"].apply(to_float) if "Close" in mdf.columns else pd.Series(dtype=float)
        mret = mclose.pct_change().dropna().tail(80)
        _TWII_BETA_RETURNS_CACHE[key] = mret
        return mret
    except Exception:
        _TWII_BETA_RETURNS_CACHE[key] = None
        return None


def fetch_stock_price_tech(stock_id: str, period: str = "4mo") -> Optional[Dict[str, Any]]:
    yf, err = import_yfinance()
    if yf is None:
        return None
    for suffix in [".TW", ".TWO"]:
        symbol = f"{stock_id}{suffix}"
        try:
            df = yf.download(symbol, period=period, interval="1d", progress=False, auto_adjust=False)
            if df is None or df.empty or len(df) < 25:
                continue
            df = flatten_yf_columns(df).reset_index()
            close = df["Close"].apply(to_float)
            high = df["High"].apply(to_float) if "High" in df.columns else close
            low = df["Low"].apply(to_float) if "Low" in df.columns else close
            volume = df["Volume"].apply(to_float) if "Volume" in df.columns else pd.Series([None] * len(df))
            ma5 = close.rolling(5).mean()
            ma10 = close.rolling(10).mean()
            ma20 = close.rolling(20).mean()
            ma60 = close.rolling(60).mean()
            ma120 = close.rolling(120).mean()
            vol_ma20 = volume.rolling(20).mean()
            vol_ma40 = volume.rolling(40).mean()
            last_close = to_float(close.iloc[-1])
            last_ma5 = to_float(ma5.iloc[-1])
            last_ma10 = to_float(ma10.iloc[-1])
            last_ma20 = to_float(ma20.iloc[-1])
            last_ma60 = to_float(ma60.iloc[-1])
            last_ma120 = to_float(ma120.iloc[-1])
            ma20_prev_5 = to_float(ma20.iloc[-6]) if len(ma20) >= 26 else None
            ma60_angle_days = 10 if len(ma60) >= 71 else 1
            ma60_prev = to_float(ma60.iloc[-(ma60_angle_days + 1)]) if len(ma60) >= (60 + ma60_angle_days + 1) else None
            bias20 = pct_change(last_close, last_ma20)
            bias60 = pct_change(last_close, last_ma60)

            # v170｜不要用「斜率」判斷健康盤整，改用 MA60 角度。
            ma60_angle_pct = pct_change(last_ma60, ma60_prev)
            ma60_angle = None
            try:
                if ma60_angle_pct is not None:
                    ma60_angle = float(np.degrees(np.arctan(ma60_angle_pct / ma60_angle_days)))
            except Exception:
                ma60_angle = None

            last_vol = to_float(volume.iloc[-1])
            last_vol_ma20 = to_float(vol_ma20.iloc[-1])
            last_vol_ma40 = to_float(vol_ma40.iloc[-1])
            close_5 = to_float(close.iloc[-6]) if len(close) >= 6 else None
            close_20 = to_float(close.iloc[-21]) if len(close) >= 21 else None
            ma60_angle_ok = ma60_angle is not None and ma60_angle > 3
            trade_value_today = None
            try:
                if last_close is not None and last_vol is not None:
                    trade_value_today = float(last_close) * float(last_vol)
            except Exception:
                trade_value_today = None

            # v215｜均線收斂：5/10/20 日均線差距占現價比例。
            ma_values = [x for x in [last_ma5, last_ma10, last_ma20] if x is not None]
            ma_short_spread = None
            try:
                if len(ma_values) >= 2 and last_close not in [None, 0]:
                    ma_short_spread = (max(ma_values) - min(ma_values)) / abs(last_close) * 100
            except Exception:
                ma_short_spread = None

            # v215｜技術線 K：用 9 日 RSV 的 EWMA 近似，避免低基期吃貨追到過熱。
            technical_k = None
            try:
                low9 = low.rolling(9).min()
                high9 = high.rolling(9).max()
                rsv = (close - low9) / (high9 - low9) * 100
                k_series = rsv.replace([np.inf, -np.inf], np.nan).ewm(alpha=1/3, adjust=False).mean()
                technical_k = to_float(k_series.iloc[-1])
            except Exception:
                technical_k = None

            # v215｜Beta60：用個股近60日報酬對加權指數近60日報酬估算。
            beta60 = None
            try:
                sret = close.pct_change().dropna().tail(60)
                mret = fetch_twii_returns_for_beta(yf, period=period)
                if mret is not None and len(sret) >= 20 and len(mret) >= 20:
                    n = min(len(sret), len(mret), 60)
                    s_arr = np.array(sret.tail(n).tolist(), dtype=float)
                    m_arr = np.array(mret.tail(n).tolist(), dtype=float)
                    var_m = float(np.var(m_arr))
                    if var_m > 0:
                        beta60 = float(np.cov(s_arr, m_arr)[0, 1] / var_m)
            except Exception:
                beta60 = None

            low20 = to_float(low.tail(20).min()) if len(low) >= 20 else None
            low60 = to_float(low.tail(60).min()) if len(low) >= 60 else None
            short_support_candidates = [x for x in [last_ma20, low20] if x is not None and last_close is not None and x <= last_close]
            swing_support_candidates = [x for x in [last_ma60, low60] if x is not None and last_close is not None and x <= last_close]
            short_support = max(short_support_candidates) if short_support_candidates else None
            swing_support = max(swing_support_candidates) if swing_support_candidates else None
            short_support_dist = pct_change(last_close, short_support) if short_support not in [None, 0] else None
            swing_support_dist = pct_change(last_close, swing_support) if swing_support not in [None, 0] else None

            return {
                "symbol": symbol,
                "close": last_close,
                "chg_5d": pct_change(last_close, close_5),
                "chg_20d": pct_change(last_close, close_20),
                "ma5": last_ma5,
                "ma10": last_ma10,
                "ma20": last_ma20,
                "ma60": last_ma60,
                "ma120": last_ma120,
                "ma20_prev_5": ma20_prev_5,
                "ma60_prev": ma60_prev,
                "ma60_change_10d_pct": ma60_angle_pct,
                "ma60_angle": ma60_angle,
                "ma60_angle_ok": ma60_angle_ok,
                "ma60_up": ma60_angle_ok,
                "ma_short_spread": ma_short_spread,
                "bias20": bias20,
                "bias60": bias60,
                "technical_k": technical_k,
                "beta60": beta60,
                "volume_today": last_vol,
                "avg_volume20": last_vol_ma20,
                "avg_volume40": last_vol_ma40,
                "trade_value_today": trade_value_today,
                "vol_ratio": safe_div(last_vol, last_vol_ma20),
                "low20": low20,
                "low60": low60,
                "short_support": short_support,
                "swing_support": swing_support,
                "short_support_dist": short_support_dist,
                "swing_support_dist": swing_support_dist,
                "above_ma20": last_close is not None and last_ma20 is not None and last_close >= last_ma20,
                "above_ma60": last_close is not None and last_ma60 is not None and last_close >= last_ma60,
                "ma20_gt_ma60": last_ma20 is not None and last_ma60 is not None and last_ma20 > last_ma60,
                "ma60_gt_ma120": last_ma60 is not None and last_ma120 is not None and last_ma60 > last_ma120,
                "ma20_up_5d": last_ma20 is not None and ma20_prev_5 is not None and last_ma20 > ma20_prev_5,
            }
        except Exception:
            continue
    return None

def _wmf_now_str():
    try:
        return now_tw().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        try:
            return _now_str()
        except Exception:
            return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _wmf_status(level, included, note):
    try:
        return status_item(level, included, note)
    except Exception:
        return {"level": level, "included": included, "note": note}


def _wmf_pick(row, keys):
    for k in keys:
        try:
            if k in row and row.get(k) not in [None, "", "-"]:
                return row.get(k)
        except Exception:
            pass
    return None


def _wmf_clean_code(x):
    try:
        s = str(x).strip()
        m = re.search(r"\d{4}", s)
        return m.group(0) if m else ""
    except Exception:
        return ""


def _wmf_value_to_float(x):
    try:
        if x is None:
            return None
        s = str(x).replace(",", "").replace("+", "").replace("%", "").strip()
        if s in ["", "-", "--", "nan", "None", "NaN", "null"]:
            return None
        return float(s)
    except Exception:
        return to_float(x)


def _wmf_fetch_twse_quotes():
    rows = []
    try:
        r = requests.get(
            "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL",
            headers={"User-Agent": "Mozilla/5.0"},
            timeout=10,
        )
        if r.status_code != 200:
            return [], f"TWSE HTTP {r.status_code}"
        data = r.json()
        for it in data if isinstance(data, list) else []:
            code = _wmf_clean_code(_wmf_pick(it, ["Code", "證券代號", "code", "stock_id"]))
            name = str(_wmf_pick(it, ["Name", "證券名稱", "name", "stock_name"]) or "").strip()
            if not code or not name:
                continue
            close = _wmf_value_to_float(_wmf_pick(it, ["ClosingPrice", "收盤價", "Close", "close"]))
            change = _wmf_value_to_float(_wmf_pick(it, ["Change", "漲跌價差", "漲跌", "change"]))
            trade_value = _wmf_value_to_float(_wmf_pick(it, ["TradeValue", "成交金額", "Amount", "trade_value"]))
            volume = _wmf_value_to_float(_wmf_pick(it, ["TradeVolume", "成交股數", "Volume", "volume"]))
            chg_pct = None
            if close is not None and change is not None:
                prev = close - change
                if prev not in [None, 0]:
                    chg_pct = change / abs(prev) * 100
            rows.append({
                "code": code,
                "name": name,
                "market": "TWSE",
                "close": close,
                "change": change,
                "change_pct": chg_pct,
                "trade_value": trade_value,
                "volume": volume,
            })
        return rows, ""
    except Exception as e:
        return [], f"TWSE {e}"


def _wmf_fetch_tpex_quotes():
    rows = []
    endpoints = [
        "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_quotes",
        "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_peratio_analysis",
    ]
    last_err = ""
    for url in endpoints:
        try:
            r = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
            if r.status_code != 200:
                last_err = f"TPEx HTTP {r.status_code}"
                continue
            data = r.json()
            tmp = []
            for it in data if isinstance(data, list) else []:
                code = _wmf_clean_code(_wmf_pick(it, ["SecuritiesCompanyCode", "Code", "代號", "證券代號", "stock_id"]))
                name = str(_wmf_pick(it, ["CompanyName", "Name", "名稱", "證券名稱", "stock_name"]) or "").strip()
                if not code or not name:
                    continue
                close = _wmf_value_to_float(_wmf_pick(it, ["Close", "ClosingPrice", "收盤", "收盤價", "LatestPrice"]))
                change = _wmf_value_to_float(_wmf_pick(it, ["Change", "漲跌", "漲跌價差", "change"]))
                trade_value = _wmf_value_to_float(_wmf_pick(it, ["TransactionAmount", "TradeValue", "成交金額", "Amount", "trade_value"]))
                volume = _wmf_value_to_float(_wmf_pick(it, ["TradingShares", "TradeVolume", "成交股數", "Volume", "volume"]))
                chg_pct = None
                if close is not None and change is not None:
                    prev = close - change
                    if prev not in [None, 0]:
                        chg_pct = change / abs(prev) * 100
                tmp.append({
                    "code": code,
                    "name": name,
                    "market": "TPEx",
                    "close": close,
                    "change": change,
                    "change_pct": chg_pct,
                    "trade_value": trade_value,
                    "volume": volume,
                })
            if tmp:
                return tmp, ""
        except Exception as e:
            last_err = f"TPEx {e}"
    return rows, last_err


def _wmf_fetch_stock_info_map():
    info = {}
    try:
        url = globals().get("API_URL", "https://api.finmindtrade.com/api/v4/data")
        r = requests.get(
            url,
            params={"dataset": "TaiwanStockInfo"},
            headers=finmind_headers(),
            timeout=12,
        )
        data = r.json().get("data", []) if r.status_code == 200 else []
        for it in data:
            code = _wmf_clean_code(it.get("stock_id"))
            if not code:
                continue
            info[code] = {
                "name": str(it.get("stock_name") or "").strip(),
                "industry": str(it.get("industry_category") or "").strip(),
                "type": str(it.get("type") or "").strip(),
            }
    except Exception:
        pass
    return info


def _wmf_seed_sector_map():
    mapping = {}
    try:
        pools = globals().get("SECTOR_STOCK_POOL")
        if isinstance(pools, dict):
            for sector, items in pools.items():
                for item in items or []:
                    code = _wmf_clean_code(item[0] if isinstance(item, (list, tuple)) else item)
                    if code:
                        mapping.setdefault(code, set()).add(str(sector))
    except Exception:
        pass
    try:
        pools = globals().get("NICK_STOCK_POOLS")
        if isinstance(pools, dict):
            for big, sub in pools.items():
                if isinstance(sub, dict):
                    for sector, codes in sub.items():
                        for code in codes or []:
                            c = _wmf_clean_code(code)
                            if c:
                                mapping.setdefault(c, set()).add(str(sector))
    except Exception:
        pass
    return mapping


