def _wmf_industry_to_sector(industry):
    s = str(industry or "")
    if not s:
        return ""
    if "航運" in s:
        return "航運"
    if "金融" in s or "保險" in s:
        return "金融/金控"
    if "營建" in s or "建材" in s:
        return "營建資產"
    if "觀光" in s:
        return "觀光餐飲"
    if "生技" in s or "醫療" in s:
        return "生技醫療"
    if "鋼鐵" in s:
        return "鋼鐵"
    if "塑膠" in s or "化學" in s:
        return "塑化"
    if "水泥" in s:
        return "水泥"
    if "造紙" in s:
        return "造紙"
    if "半導體" in s:
        return "半導體"
    if "電子零組件" in s:
        return "電子零組件"
    if "通信" in s or "網路" in s:
        return "網通設備"
    if "光電" in s:
        return "光電/面板"
    if "電機" in s or "機械" in s:
        return "電機機械"
    return s.replace("業", "")


def _wmf_guess_sectors(code, name, industry, seed_map):
    sectors = set()
    try:
        sectors.update(seed_map.get(str(code), set()))
    except Exception:
        pass
    text = f"{name} {industry}"
    for sector, kws in _WMF_RULES:
        if any(str(k) and str(k) in text for k in kws):
            sectors.add(sector)
    mapped = _wmf_industry_to_sector(industry)
    if mapped:
        sectors.add(mapped)
    # 避免同一檔被塞進太多相近大類，最多保留 3 個；但保留未分類防漏
    out = [x for x in sectors if x and x not in ["ETF", "指數股票型基金"]]
    return out[:3]


def _wmf_fetch_recent_tech(code):
    try:
        if "fetch_stock_price_tech" in globals():
            return fetch_stock_price_tech(str(code), period="4mo")
    except Exception:
        pass
    try:
        if "_fetch_dynamic_pool_tech" in globals():
            return _fetch_dynamic_pool_tech(str(code))
    except Exception:
        pass
    # 最後備援：直接 yfinance
    try:
        yf_obj = None
        if "import_yfinance" in globals():
            yf_obj, _ = import_yfinance()
        elif globals().get("_YF_OK"):
            yf_obj = globals().get("yf")
        if yf_obj is None:
            return None
        for suffix in [".TW", ".TWO"]:
            symbol = f"{code}{suffix}"
            df = yf_obj.download(symbol, period="4mo", interval="1d", progress=False, auto_adjust=False)
            if df is None or df.empty or len(df) < 25:
                continue
            try:
                if "flatten_yf_columns" in globals():
                    df = flatten_yf_columns(df)
                elif isinstance(df.columns, pd.MultiIndex):
                    df.columns = [c[0] if isinstance(c, tuple) else c for c in df.columns]
            except Exception:
                pass
            df = df.reset_index()
            close = df["Close"].apply(to_float)
            volume = df["Volume"].apply(to_float) if "Volume" in df.columns else pd.Series([None] * len(df))
            ma20 = close.rolling(20).mean()
            ma60 = close.rolling(60).mean()
            vol_ma20 = volume.rolling(20).mean()
            last_close = to_float(close.iloc[-1])
            return {
                "symbol": symbol,
                "close": last_close,
                "chg_5d": pct_change(last_close, to_float(close.iloc[-6]) if len(close) >= 6 else None),
                "chg_20d": pct_change(last_close, to_float(close.iloc[-21]) if len(close) >= 21 else None),
                "ma20": to_float(ma20.iloc[-1]),
                "ma60": to_float(ma60.iloc[-1]),
                "vol_ratio": safe_div(to_float(volume.iloc[-1]), to_float(vol_ma20.iloc[-1])),
                "above_ma20": last_close is not None and to_float(ma20.iloc[-1]) is not None and last_close >= to_float(ma20.iloc[-1]),
                "above_ma60": last_close is not None and to_float(ma60.iloc[-1]) is not None and last_close >= to_float(ma60.iloc[-1]),
            }
    except Exception:
        return None
    return None


def _wmf_score_group(sector, items, max_stocks_each, max_trade_value):
    if not items:
        return None
    # 今日資料：全市場即時/盤後報價，不只內建股池
    df0 = pd.DataFrame(items)
    for c in ["change_pct", "trade_value"]:
        if c in df0.columns:
            df0[c] = df0[c].apply(to_float)
    valid_chg = df0["change_pct"].dropna() if "change_pct" in df0.columns else pd.Series(dtype=float)
    day_avg = valid_chg.mean() if not valid_chg.empty else float("nan")
    day_median = valid_chg.median() if not valid_chg.empty else float("nan")
    up_ratio = float((valid_chg > 0).mean()) if not valid_chg.empty else 0.0
    strong_count = int((valid_chg >= 1.5).sum()) if not valid_chg.empty else 0
    weak_count = int((valid_chg <= -1.5).sum()) if not valid_chg.empty else 0
    trade_sum = df0["trade_value"].dropna().sum() if "trade_value" in df0.columns else 0

    top = sorted(items, key=lambda x: (to_float(x.get("trade_value")) or 0, abs(to_float(x.get("change_pct")) or 0)), reverse=True)[: max(1, int(max_stocks_each or 3))]
    tech_rows = []
    for x in top:
        tech = _wmf_fetch_recent_tech(x.get("code"))
        row = {
            "股票": f"{x.get('name')} {x.get('code')}",
            "代號": x.get("code"),
            "今日漲跌": x.get("change_pct"),
            "成交金額": x.get("trade_value"),
        }
        if tech:
            row.update(tech)
        tech_rows.append(row)

    df = pd.DataFrame(tech_rows)
    avg_5d = df["chg_5d"].apply(to_float).dropna().mean() if "chg_5d" in df else float("nan")
    avg_20d = df["chg_20d"].apply(to_float).dropna().mean() if "chg_20d" in df else float("nan")
    above_ma20_ratio = df["above_ma20"].mean() if "above_ma20" in df else float("nan")
    vol_ratio = df["vol_ratio"].apply(to_float).dropna().mean() if "vol_ratio" in df else float("nan")

    score = 0.0
    if pd.notna(day_avg):
        score += max(0, min(26, (float(day_avg) + 1.5) / 4.5 * 26))
    score += max(0, min(18, up_ratio * 18))
    score += max(0, min(14, strong_count / 5 * 14))
    if max_trade_value and max_trade_value > 0:
        score += max(0, min(16, (float(trade_sum) / max_trade_value) * 16))
    if pd.notna(avg_5d):
        score += max(0, min(12, (float(avg_5d) + 2) / 8 * 12))
    if pd.notna(avg_20d):
        score += max(0, min(10, (float(avg_20d) + 5) / 20 * 10))
    if pd.notna(above_ma20_ratio):
        score += max(0, min(8, float(above_ma20_ratio) * 8))
    if pd.notna(vol_ratio):
        score += max(0, min(6, (float(vol_ratio) - 0.8) / 1.2 * 6))

    day_avg_f = None if pd.isna(day_avg) else float(day_avg)
    avg_5d_f = None if pd.isna(avg_5d) else float(avg_5d)
    avg_20d_f = None if pd.isna(avg_20d) else float(avg_20d)
    above_f = None if pd.isna(above_ma20_ratio) else float(above_ma20_ratio)
    vol_f = None if pd.isna(vol_ratio) else float(vol_ratio)

    # 分類順序：先辨識退潮與鈍化，再分辨低基期/回檔轉強，避免漲多回落被誤判成低基期。
    if (day_avg_f is not None and day_avg_f <= -0.8 and up_ratio < 0.45 and weak_count >= max(1, strong_count)) or score < 32:
        label, note = "退潮轉弱", "今日資金偏流出，族群內弱勢股較多，先避開追價"
    elif avg_20d_f is not None and avg_20d_f >= 5 and ((avg_5d_f is not None and avg_5d_f < 0) or (day_avg_f is not None and day_avg_f < 0.5)):
        label, note = "主流鈍化", "前波已有漲幅，近日追價力道降溫，續抱不追高"
    elif (
        avg_20d_f is not None
        and avg_20d_f <= -3
        and avg_5d_f is not None
        and avg_5d_f <= 2
        and day_avg_f is not None
        and 0.8 <= day_avg_f <= 3.5
        and strong_count >= 1
        and up_ratio >= 0.45
        and score < 58
        and not (avg_5d_f > 2 and score >= 55)
    ):
        label, note = "低基期轉強", "原本偏弱、低位階，尚未全面被追價，今日開始轉強"
    elif (
        avg_20d_f is not None
        and avg_20d_f >= 3
        and avg_5d_f is not None
        and avg_5d_f <= 1.5
        and day_avg_f is not None
        and day_avg_f >= 0.5
        and up_ratio >= 0.50
        and strong_count >= 1
    ):
        label, note = "回檔轉強", "中期仍偏強，短線整理後再度轉強，適合找支撐不破的個股"
    elif score >= 66 and day_avg_f is not None and day_avg_f >= 0.8 and up_ratio >= 0.55 and strong_count >= 2:
        label, note = "明面主流", "成交金額與強勢股同步集中，市場已明顯追進"
    elif score >= 48 and day_avg_f is not None and day_avg_f >= 0 and up_ratio >= 0.48:
        label, note = "偷偷流入", "資金開始回補但尚未全面噴出，留意接棒機會"
    else:
        label, note = "觀察中", "有資金跡象但方向未完全確認"

    return {
        "大類": "全市場資金流向",
        "族群": sector,
        "分數": round(float(score), 1),
        "狀態": label,
        "說明": note,
        "今日均漲跌": None if day_avg_f is None else round(day_avg_f, 2),
        "今日中位數": None if pd.isna(day_median) else round(float(day_median), 2),
        "5日均漲跌": None if avg_5d_f is None else round(avg_5d_f, 2),
        "20日均漲跌": None if avg_20d_f is None else round(avg_20d_f, 2),
        "站上MA20比例": None if above_f is None else round(above_f * 100, 1),
        "量比": None if vol_f is None else round(vol_f, 2),
        "上漲比例": round(up_ratio * 100, 1),
        "強勢股數": strong_count,
        "弱勢股數": weak_count,
        "成交金額(億)": round(float(trade_sum or 0) / 100000000, 2),
        "個股": tech_rows,
    }


def build_whole_market_flow(max_stocks_each=3, max_groups=45):
    twse_rows, twse_err = _wmf_fetch_twse_quotes()
    tpex_rows, tpex_err = _wmf_fetch_tpex_quotes()
    quotes = (twse_rows or []) + (tpex_rows or [])
    if not quotes:
        return {
            "updated_at": _wmf_now_str(),
            "engine": WHOLE_MARKET_FLOW_ENGINE_VERSION,
            "rows": [],
            "source": "TWSE OpenAPI / TPEx OpenAPI",
            "errors": [twse_err, tpex_err],
        }, _wmf_status("fail", False, "全市場行情抓取失敗，無法分析資金流向")

    info_map = _wmf_fetch_stock_info_map()
    seed_map = _wmf_seed_sector_map()
    grouped = {}
    unclassified = []

    for q in quotes:
        code = str(q.get("code") or "").strip()
        info = info_map.get(code, {})
        if info.get("name") and not q.get("name"):
            q["name"] = info.get("name")
        q["industry"] = info.get("industry", "")
        sectors = _wmf_guess_sectors(code, q.get("name", ""), q.get("industry", ""), seed_map)
        chg = to_float(q.get("change_pct"))
        val = to_float(q.get("trade_value")) or 0
        strongish = (chg is not None and abs(chg) >= 1.5) or val >= 300000000
        if not sectors:
            if strongish:
                sectors = ["未分類強勢資金池"]
                unclassified.append(q)
            else:
                continue
        for s in sectors:
            grouped.setdefault(s, []).append(q)

    max_trade_value = 0
    for items in grouped.values():
        val = sum((to_float(x.get("trade_value")) or 0) for x in items)
        max_trade_value = max(max_trade_value, val)

    rows = []
    # 先處理成交金額與異動較大的族群，避免 yfinance 抓太多無效族群。
    group_order = sorted(
        grouped.items(),
        key=lambda kv: (sum((to_float(x.get("trade_value")) or 0) for x in kv[1]), len(kv[1])),
        reverse=True,
    )[: max(10, int(max_groups or 45))]

    for sector, items in group_order:
        if len(items) < 2 and sector != "未分類強勢資金池":
            # 單檔族群除非成交金額很大，否則容易誤判。
            total_value = sum((to_float(x.get("trade_value")) or 0) for x in items)
            if total_value < 500000000:
                continue
        r = _wmf_score_group(sector, items, max_stocks_each=max_stocks_each, max_trade_value=max_trade_value)
        if r:
            rows.append(r)

    rows = sorted(rows, key=lambda r: (to_float(r.get("分數")) or -999, to_float(r.get("成交金額(億)")) or 0), reverse=True)
    snap = {
        "updated_at": _wmf_now_str(),
        "engine": WHOLE_MARKET_FLOW_ENGINE_VERSION,
        "max_stocks_each": max_stocks_each,
        "source": "TWSE OpenAPI + TPEx OpenAPI + FinMind 產業分類 + yfinance 近日價量",
        "quote_count": len(quotes),
        "group_count": len(rows),
        "unclassified_count": len(unclassified),
        "errors": [e for e in [twse_err, tpex_err] if e],
        "rows": rows,
    }
    level = "ok" if rows else "fail"
    included = bool(rows)
    note = f"全市場聯網掃描 {len(quotes)} 檔，產出 {len(rows)} 個資金族群；防漏池 {len(unclassified)} 檔"
    return snap, _wmf_status(level, included, note)


def analyze_sector_flow(selected_sectors: List[str], max_stocks_each: int = 4, extra_pool: Optional[Dict[str, Any]] = None) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """資金流向：v1.4 改為全市場聯網掃描。selected_sectors 只保留相容舊 UI，不再限制掃描範圍。"""
    return build_whole_market_flow(max_stocks_each=max_stocks_each, max_groups=45)


