def fetch_stock_institutional_flow(stock_id: str) -> Dict[str, Any]:
    try:
        end = now_tw().date()
        start = end - timedelta(days=45)
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {
            "dataset": "TaiwanStockInstitutionalInvestorsBuySell",
            "data_id": stock_id,
            "start_date": start.strftime("%Y-%m-%d"),
            "end_date": end.strftime("%Y-%m-%d"),
        }
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT, headers=finmind_headers())
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            return {"inst_5d": None, "inst_20d": None, "source": "FinMind 無資料"}
        df = pd.DataFrame(data)
        if "date" not in df.columns or "buy" not in df.columns or "sell" not in df.columns:
            return {"inst_5d": None, "inst_20d": None, "source": "欄位不完整"}
        df["date"] = pd.to_datetime(df["date"], errors="coerce")
        df["net"] = df["buy"].apply(to_float).fillna(0) - df["sell"].apply(to_float).fillna(0)
        df = df.dropna(subset=["date"]).sort_values("date")
        dates = sorted(df["date"].dropna().unique())
        d5 = dates[-5:]
        d20 = dates[-20:]
        d40 = dates[-40:]
        df5 = df[df["date"].isin(d5)]
        return {
            "inst_5d": float(df5["net"].sum()),
            "inst_20d": float(df[df["date"].isin(d20)]["net"].sum()),
            "inst_40d": float(df[df["date"].isin(d40)]["net"].sum()),
            "inst_buy_days_5": int((df5.groupby("date")["net"].sum() > 0).sum()) if not df5.empty else 0,
            "source": "FinMind",
        }
    except Exception as e:
        return {"inst_5d": None, "inst_20d": None, "source": f"失敗：{e}"}



def fetch_stock_financial_growth(stock_id: str) -> Dict[str, Any]:
    """v173｜抓取近季財報成長，用於營收成長二段買點策略。

    盡量用 FinMind TaiwanStockFinancialStatements。
    由於不同期間 / 欄位名稱可能略有差異，這裡用寬鬆關鍵字對應：
    - EPS / 每股盈餘
    - 營業收入
    - 營業毛利 / Gross Profit
    - 營業利益 / Operating Income

    回傳欄位：
    - eps_yoy, eps_qoq
    - operating_income_yoy
    - gross_profit_yoy
    - gross_margin, gross_margin_yoy_pp
    - operating_margin
    """
    base = {
        "eps_yoy": None,
        "eps_qoq": None,
        "operating_income_yoy": None,
        "gross_profit_yoy": None,
        "gross_margin": None,
        "gross_margin_yoy_pp": None,
        "operating_margin": None,
        "source": "FinMind 財報未取得",
    }
    try:
        end = now_tw().date()
        start = end - timedelta(days=1300)
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {
            "dataset": "TaiwanStockFinancialStatements",
            "data_id": stock_id,
            "start_date": start.strftime("%Y-%m-%d"),
            "end_date": end.strftime("%Y-%m-%d"),
        }
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT, headers=finmind_headers())
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            base["source"] = "FinMind 財報無資料"
            return base

        df = pd.DataFrame(data)
        if df.empty or "date" not in df.columns:
            base["source"] = "FinMind 財報欄位不足"
            return base

        df["date"] = pd.to_datetime(df["date"], errors="coerce")
        df = df.dropna(subset=["date"]).sort_values("date")

        metric_col = None
        for c in ["type", "name", "origin_name", "account", "metric"]:
            if c in df.columns:
                metric_col = c
                break
        value_col = None
        for c in ["value", "amount", "data"]:
            if c in df.columns:
                value_col = c
                break
        if metric_col is None or value_col is None:
            base["source"] = "FinMind 財報無 type/value 欄位"
            return base

        df[value_col] = df[value_col].apply(to_float)
        df = df.dropna(subset=[value_col])
        if df.empty:
            base["source"] = "FinMind 財報有效值空白"
            return base

        def _metric_bucket(name: str) -> str:
            s = str(name or "").lower().replace(" ", "").replace("_", "")
            # EPS / 每股盈餘
            if ("eps" in s) or ("每股盈餘" in s) or ("基本每股" in s):
                return "eps"
            # 營業收入 / Revenue
            if ("營業收入" in s) or ("營收" in s) or ("revenue" in s) or ("sales" in s):
                return "revenue"
            # 營業毛利 / Gross profit
            if ("營業毛利" in s) or ("毛利" in s) or ("grossprofit" in s):
                return "gross_profit"
            # 營業利益 / Operating income
            if ("營業利益" in s) or ("營業損益" in s) or ("operatingincome" in s) or ("incomefromoperations" in s):
                return "operating_income"
            return ""

        rows = []
        for d, g in df.groupby("date"):
            row = {"date": d, "eps": None, "revenue": None, "gross_profit": None, "operating_income": None}
            for _, rr in g.iterrows():
                bucket = _metric_bucket(rr.get(metric_col))
                if not bucket:
                    continue
                val = to_float(rr.get(value_col))
                if val is None:
                    continue
                # 同一 bucket 若多筆，優先取絕對值較合理的非空值；EPS 則直接取最後。
                if bucket == "eps":
                    row[bucket] = val
                else:
                    if row[bucket] is None or abs(val) > abs(row[bucket] or 0):
                        row[bucket] = val
            if any(row.get(k) is not None for k in ["eps", "revenue", "gross_profit", "operating_income"]):
                rows.append(row)

        if not rows:
            base["source"] = "FinMind 財報無可辨識科目"
            return base

        qdf = pd.DataFrame(rows).sort_values("date").reset_index(drop=True)
        latest = qdf.iloc[-1]
        latest_date = latest["date"]

        prev_q = qdf.iloc[-2] if len(qdf) >= 2 else None
        same_y = qdf[
            (qdf["date"].dt.year == latest_date.year - 1)
            & (qdf["date"].dt.month == latest_date.month)
        ]
        same_y = same_y.iloc[-1] if not same_y.empty else None

        def _v(row, col):
            try:
                return to_float(row.get(col)) if row is not None else None
            except Exception:
                return None

        latest_revenue = _v(latest, "revenue")
        latest_gp = _v(latest, "gross_profit")
        latest_op = _v(latest, "operating_income")

        same_revenue = _v(same_y, "revenue")
        same_gp = _v(same_y, "gross_profit")

        latest_gm = safe_div(latest_gp, latest_revenue)
        latest_gm = latest_gm * 100 if latest_gm is not None else None
        same_gm = safe_div(same_gp, same_revenue)
        same_gm = same_gm * 100 if same_gm is not None else None

        latest_om = safe_div(latest_op, latest_revenue)
        latest_om = latest_om * 100 if latest_om is not None else None

        base.update({
            "eps_yoy": pct_change(_v(latest, "eps"), _v(same_y, "eps")),
            "eps_qoq": pct_change(_v(latest, "eps"), _v(prev_q, "eps")),
            "operating_income_yoy": pct_change(_v(latest, "operating_income"), _v(same_y, "operating_income")),
            "gross_profit_yoy": pct_change(latest_gp, same_gp),
            "gross_margin": latest_gm,
            "gross_margin_yoy_pp": (latest_gm - same_gm) if latest_gm is not None and same_gm is not None else None,
            "operating_margin": latest_om,
            "source": "FinMind 財報",
        })
        return base
    except Exception as e:
        base["source"] = f"FinMind 財報失敗：{e}"
        return base


def fetch_stock_month_revenue(stock_id: str) -> Dict[str, Any]:
    """取得月營收 YoY，並補上近3月成長條件。

    v172：
    - revenue_1m_yoy：最新月營收 YoY
    - revenue_3m_yoy_min：近3月 YoY 最低值
    - revenue_3m_yoy_avg：近3月 YoY 平均
    - revenue_3m_all_gt10：近3月 YoY 是否都 > 10
    """
    try:
        end = now_tw().date()
        start = end - timedelta(days=700)
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {
            "dataset": "TaiwanStockMonthRevenue",
            "data_id": stock_id,
            "start_date": start.strftime("%Y-%m-%d"),
            "end_date": end.strftime("%Y-%m-%d"),
        }
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT, headers=finmind_headers())
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            return {"revenue_yoy": None, "source": "FinMind 無資料"}
        df = pd.DataFrame(data)
        if "date" not in df.columns or "revenue" not in df.columns:
            return {"revenue_yoy": None, "source": "欄位不完整"}
        df["date"] = pd.to_datetime(df["date"], errors="coerce")
        df["revenue"] = df["revenue"].apply(to_float)
        df = df.dropna(subset=["date", "revenue"]).sort_values("date")
        if df.empty:
            return {"revenue_yoy": None, "source": "有效資料空白"}

        # 先用 FinMind 已有 YoY 欄位；沒有就用去年同月自己算。
        yoy_col = None
        for c in ["revenue_year_growth_rate", "YoY", "yoy"]:
            if c in df.columns:
                yoy_col = c
                break

        yoy_values = []
        for _, rr in df.iterrows():
            yoy = to_float(rr.get(yoy_col)) if yoy_col else None
            if yoy is None:
                d = rr.get("date")
                prev = df[(df["date"].dt.year == d.year - 1) & (df["date"].dt.month == d.month)]
                if not prev.empty:
                    yoy = pct_change(rr.get("revenue"), prev.iloc[-1].get("revenue"))
            yoy_values.append(yoy)
        df["__yoy"] = yoy_values

        latest_yoy = to_float(df.iloc[-1].get("__yoy"))
        latest_rev = to_float(df.iloc[-1].get("revenue"))
        prev_rev = to_float(df.iloc[-2].get("revenue")) if len(df) >= 2 else None
        revenue_1m_mom = pct_change(latest_rev, prev_rev)

        latest_date = df.iloc[-1].get("date")
        revenue_ytd_yoy = None
        try:
            if pd.notna(latest_date):
                y = int(latest_date.year)
                m = int(latest_date.month)
                cur_ytd = df[(df["date"].dt.year == y) & (df["date"].dt.month <= m)]["revenue"].sum()
                pre_ytd = df[(df["date"].dt.year == y - 1) & (df["date"].dt.month <= m)]["revenue"].sum()
                if pre_ytd not in [None, 0]:
                    revenue_ytd_yoy = pct_change(cur_ytd, pre_ytd)
        except Exception:
            revenue_ytd_yoy = None

        recent3 = [to_float(x) for x in df["__yoy"].dropna().tail(3).tolist()]
        recent3 = [x for x in recent3 if x is not None]

        rev3_min = min(recent3) if recent3 else None
        rev3_avg = sum(recent3) / len(recent3) if recent3 else None
        rev3_all_gt10 = len(recent3) >= 3 and all(x > 10 for x in recent3)

        return {
            "revenue_yoy": latest_yoy,
            "revenue_1m_yoy": latest_yoy,
            "revenue_1m_mom": revenue_1m_mom,
            "revenue_ytd_yoy": revenue_ytd_yoy,
            "revenue_3m_yoy_min": rev3_min,
            "revenue_3m_yoy_avg": rev3_avg,
            "revenue_3m_all_gt10": rev3_all_gt10,
            "source": "FinMind",
        }
    except Exception as e:
        return {"revenue_yoy": None, "source": f"失敗：{e}"}



def stock_position_label(tech: Optional[Dict[str, Any]]) -> str:
    if not tech:
        return "資料不足"
    above20 = bool(tech.get("above_ma20"))
    above60 = bool(tech.get("above_ma60"))
    ma60_angle = to_float(tech.get("ma60_angle"))
    angle_ok = bool(tech.get("ma60_angle_ok"))
    if ma60_angle is not None:
        angle_txt = f"MA60角度{ma60_angle:.1f}°" + ("，角度>3" if angle_ok else "，角度≤3")
    else:
        angle_txt = "MA60角度不足"
    if above20 and above60:
        return f"站上MA20/MA60，{angle_txt}"
    if above20 and not above60:
        return f"站上MA20，仍在MA60下，{angle_txt}"
    if not above20 and above60:
        return f"跌破MA20，MA60仍守住，{angle_txt}"
    return f"跌破MA20/MA60，{angle_txt}"


def classify_stock_for_radar(
    tech: Optional[Dict[str, Any]],
    flow: Dict[str, Any],
    rev: Dict[str, Any],
    radar_mode: str = "inflow",
    sector_flow_status: str = "",
) -> Tuple[str, str, str, str]:
    """依掃描目的分類：資金流入佈局 / 資金退潮風險。

    v143：
    - 退潮頁改成「資金流出後的二次判斷頁」，不是單純弱勢清單。
    - 退潮狀態統一為：優質退潮 / 短線退潮 / 反彈賣點 / 明確退潮。
    - 資金流入頁加入防矛盾閘門：已退潮或短線退潮者，不列入佈局。
    """
    inst5 = to_float(flow.get("inst_5d"))
    inst20 = to_float(flow.get("inst_20d"))
    yoy = to_float(rev.get("revenue_yoy"))
    chg5 = to_float(tech.get("chg_5d")) if tech else None
    chg20 = to_float(tech.get("chg_20d")) if tech else None
    vol_ratio = to_float(tech.get("vol_ratio")) if tech else None
    close = to_float(tech.get("close")) if tech else None
    ma20 = to_float(tech.get("ma20")) if tech else None
    ma60 = to_float(tech.get("ma60")) if tech else None
    above_ma20 = bool(tech.get("above_ma20")) if tech else False
    above_ma60 = bool(tech.get("above_ma60")) if tech else False

    inst5_buy = inst5 is not None and inst5 > 0
    inst20_buy = inst20 is not None and inst20 > 0
    inst5_sell = inst5 is not None and inst5 < 0
    inst20_sell = inst20 is not None and inst20 < 0
    yoy_good = yoy is not None and yoy > 0
    yoy_bad = yoy is not None and yoy <= 0
    sector_is_inflow = sector_flow_status in ["明面主流", "偷偷流入", "低基期轉強", "回檔轉強", "主流鈍化"]
    sector_is_outflow = sector_flow_status in ["退潮轉弱", "主流鈍化"]

    ma20_dist = None
    if close is not None and ma20 not in [None, 0]:
        ma20_dist = (close - ma20) / ma20 * 100

    near_ma20_support = ma20_dist is not None and 0 <= ma20_dist <= 4
    far_from_ma20 = ma20_dist is not None and ma20_dist >= 7
    too_far_from_ma20 = ma20_dist is not None and ma20_dist >= 10

    hot = (chg5 is not None and chg5 >= 8) or (chg20 is not None and chg20 >= 20) or (vol_ratio is not None and vol_ratio >= 2.2)
    moderate_hot = (chg5 is not None and chg5 >= 5) or (chg20 is not None and chg20 >= 12) or (vol_ratio is not None and vol_ratio >= 1.8)
    weak_trend = (not above_ma20) and (chg5 is not None and chg5 < 0)
    deep_weak = (not above_ma20) and (not above_ma60) and (chg20 is not None and chg20 < -5)

    inst20_abs = abs(inst20) if inst20 is not None else 0
    inst5_abs = abs(inst5) if inst5 is not None else 0
    large_liquid_like = (
        (close is not None and close >= 500)
        or inst20_abs >= 5000
        or (inst5_abs >= 2500 and above_ma20)
        or (sector_flow_status == "明面主流" and above_ma20 and inst20_abs >= 1500)
    )

    data_has_basic = yoy is not None
    data_has_inst = inst5 is not None or inst20 is not None
    data_has_tech = tech is not None and close is not None and (ma20 is not None or chg5 is not None or chg20 is not None)
    truly_data_insufficient = not data_has_basic and not data_has_inst and not data_has_tech

    if radar_mode == "outflow":
        # 反彈賣點：基本面/趨勢已弱，短線反彈優先視為減碼點，不誤判成轉強。
        if yoy_bad and deep_weak and (chg5 is not None and chg5 > 0):
            return (
                "反彈賣點｜不要誤判轉強",
                "基本面與趨勢都偏弱，短線反彈較像逃命波；不要把反彈當成資金重新流入。",
                "反彈賣點 / 不追",
                "高",
            )

        # 明確退潮：資金與技術同步轉弱，先避開。
        if inst5_sell and inst20_sell and not above_ma20 and (sector_flow_status == "退潮轉弱" or deep_weak):
            return (
                "明確退潮｜先避開",
                "法人短線與波段同步賣，且技術跌破短均；這類不是等回檔，是先避開。",
                "避開 / 不接刀",
                "高",
            )

        # 優質退潮：基本面還在，但資金退潮或回檔，等基本面支撐區與支撐守住。
        if yoy_good and not (inst20_sell and deep_weak) and (
            inst5_sell
            or weak_trend
            or (not above_ma20 and (vol_ratio is None or vol_ratio < 1.8))
        ):
            return (
                "優質退潮｜等基本面支撐",
                "營收仍有支撐，但短線資金退場或回檔；先等回基本面支撐區 / 技術支撐，不急著買。",
                "等基本面支撐 / 觀察承接",
                "中",
            )

        # 短線退潮：主流或高檔鈍化，不追高；等它重新回到資金流入佈局頁。
        if chg20 is not None and chg20 >= 8 and ((chg5 is not None and chg5 <= 1) or not above_ma20) and (inst5_sell or sector_flow_status == "主流鈍化"):
            return (
                "短線退潮｜等重新流入",
                "前波已有漲幅，短線追價力道降溫；不追高，等重新站回資金流入佈局。",
                "等重新流入 / 不追高",
                "中",
            )

        if sector_is_outflow or inst5_sell or not above_ma20:
            return (
                "短線退潮｜等重新流入",
                "已有資金轉弱訊號，但尚未確認基本面失效；先退出佈局判斷，等重新流入再看。",
                "等待重新流入",
                "中",
            )

        return "暫無明確退潮", "目前沒有明顯退潮訊號，列入觀察即可。", "觀察", "低"

    # 資金流入頁防矛盾：退潮中或短線轉弱，不列入資金流入佈局。
    if sector_flow_status == "退潮轉弱":
        return (
            "不列主雷達｜退潮中",
            "族群目前屬退潮狀態，避免與資金流入佈局互相矛盾；等重新流入再回來。",
            "等待重新流入",
            "中",
        )

    if sector_flow_status == "主流鈍化" and ((inst5_sell and weak_trend) or (inst20_sell and not above_ma20)):
        return (
            "不列主雷達｜短線退潮待重新流入",
            "主流已鈍化且個股轉弱，暫不列入流入佈局；等重新站回支撐、量能回溫、法人賣壓縮小。",
            "等待重新流入",
            "中",
        )

    if truly_data_insufficient:
        if large_liquid_like:
            return "權值/龍頭型｜需估值位置驗證", "不是公司資料不足，而是雷達層缺少足夠欄位；這類要回個股法醫看估值、EPS與買點", "不列主雷達 / 法醫驗證", "中"
        return "不列主雷達｜資料待補", "營收、法人、技術欄位都不足，無法驗證是否符合 Nick 心法", "暫不判斷", "中"

    unsupported_hot = hot and (not yoy_good and not inst20_buy)
    revenue_and_inst_not_support = yoy_bad and not inst20_buy and (chg5 is not None and chg5 > 3)
    far_hot_without_support = moderate_hot and too_far_from_ma20 and not (yoy_good and (inst5_buy or inst20_buy))

    if unsupported_hot or revenue_and_inst_not_support or far_hot_without_support:
        if large_liquid_like:
            return "權值/龍頭型｜需估值位置驗證", "股價/題材已有反應，但大型或高流動標的不能用雷達簡化條件下結論；請回個股法醫驗證估值、EPS、法人與支撐", "法醫驗證 / 不追高", "中"
        return "不列主雷達｜題材待驗證", "題材或股價先跑，但營收與法人波段買盤未同步通過 Nick 心法閘門", "不追 / 等驗證", "中～高"

    if hot:
        if yoy_good and (inst5_buy or inst20_buy) and sector_is_inflow and not too_far_from_ma20:
            return "強股過熱｜等回檔", "基本面或法人有支撐，但短線位置偏熱；保留追蹤，等回支撐再看", "等回檔", "中"
        if large_liquid_like:
            return "權值/龍頭型｜需估值位置驗證", "大型/高流動標的已先反應，雷達不直接追；回個股法醫檢查估值與支撐", "法醫驗證 / 不追高", "中"
        return "不列主雷達｜過熱不追", "短線漲幅、波段漲幅或量比已過熱，且支撐條件不足；不符合目前雷達甜點", "等降溫", "中"

    pullback_stock = (
        sector_flow_status == "回檔轉強"
        and above_ma20
        and chg20 is not None
        and chg20 >= 3
        and (chg5 is None or chg5 <= 4)
    )
    if pullback_stock and (yoy_good or inst5_buy):
        if near_ma20_support:
            return "回檔轉強｜承接佳", "回檔後仍守MA20，且離MA20不遠，承接位置較舒服；再看法人賣壓是否擴大", "支撐不破可觀察", "中"
        if far_from_ma20:
            return "回檔轉強｜已反彈不追", "族群有轉強味，但個股已離MA20較遠，不是舒服回檔甜點", "等回測 / 不追", "中"
        return "回檔轉強｜承接觀察", "族群屬回檔轉強，個股仍站上20日線；等待支撐與法人承接確認", "觀察支撐", "中"

    if yoy_good and above_ma20 and inst5_buy and (inst20 is None or inst20 <= 0):
        return "基本面轉強，法人剛卡位", "營收有改善，法人短線剛開始卡位，但20日法人尚未全面轉強；觀察是否延續買超", "追蹤 / 等法人延續", "中"

    if inst5_buy and inst20_buy and yoy_good and above_ma20:
        return "優先觀察｜資金與基本面同向", "法人短線與波段都有買，營收年增為正，趨勢仍在；下一步丟進個股法醫確認買點", "優先觀察 / 等回檔", "低～中"

    low_base_core = (
        sector_flow_status == "低基期轉強"
        and chg20 is not None
        and chg20 <= 5
        and (chg5 is None or chg5 <= 5)
        and (not above_ma60 or not above_ma20)
        and yoy_good
    )
    if low_base_core and inst20_buy:
        return "低基期轉強｜確認觀察", "低位階剛轉強，營收有改善，法人已有小幅波段卡位；仍需確認股價沒有過度反應", "追蹤 / 等回檔", "中"
    if low_base_core:
        return "低基期轉強｜早期觀察", "基本面有改善，但股價仍在低位階或剛翻上短均；法人尚未全面進場", "追蹤 / 等法人確認", "中"

    if inst5_buy and (inst20 is None or inst20 <= 0) and above_ma20:
        return "偷偷回補｜法人初步卡位", "法人短線剛回補，但基本面尚未明確確認或資料不足；適合先放觀察名單", "先觀察 / 不急追", "中"

    if large_liquid_like:
        return "權值/龍頭型｜需估值位置驗證", "大型或高流動標的不是雷達甜點；需回個股法醫確認估值、EPS、法人與買點", "法醫驗證 / 不追高", "中"

    return "不列主雷達｜心法未過", "尚未同時看到基本面改善、法人可能回補、位置不過熱等 Nick 心法條件", "暫不列主雷達", "中"


def scan_sector_stock_radar(
    selected_sectors: List[str],
    max_stocks_each: int = 4,
    extra_pool: Optional[Dict[str, Any]] = None,
    radar_mode: str = "inflow",
    sector_status_lookup: Optional[Dict[str, str]] = None,
    progress_cb=None,
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """掃描族群個股雷達。

    v195：同股去重＋今日資料快取。
    v196：兩段式掃描。
    v197：安全平行掃描，預設同時掃 5 檔；快取由主執行緒統一寫入。
    """
    rows: List[Dict[str, Any]] = []
    mode_label = RADAR_MODE_LABELS.get(radar_mode, "資金流入佈局")
    total_items = 0
    duplicated_hits = 0
    cache_hits = 0
    fast_skips = 0
    fin_fetches = 0
    completed = 0

    try:
        code_map: Dict[str, Dict[str, Any]] = {}
        for sector in selected_sectors:
            sector_flow_status = (sector_status_lookup or {}).get(sector, "")
            for stock_id, stock_name in get_effective_sector_pool(sector, extra_pool)[:max_stocks_each]:
                sid = clean_stock_id(stock_id)
                if not sid:
                    continue
                if sid not in code_map:
                    code_map[sid] = {
                        "stock_id": sid,
                        "stock_name": stock_name,
                        "hits": [],
                    }
                if not any(h.get("sector") == sector for h in code_map[sid]["hits"]):
                    code_map[sid]["hits"].append({"sector": sector, "status": sector_flow_status})
                else:
                    duplicated_hits += 1

        scan_items = list(code_map.values())
        duplicated_hits += max(0, sum(len(v.get("hits", [])) for v in scan_items) - len(scan_items))
        total_items = len(scan_items)

        # 快取只在主執行緒讀一次、最後寫一次。
        today = _radar_cache_today_key()
        cache = load_radar_stock_cache()
        day_cache = cache.setdefault(today, {}) if isinstance(cache, dict) else {}

        if progress_cb:
            try:
                progress_cb(0, total_items, "", "", "", 0, cache_hits=0, duplicated_hits=duplicated_hits, fast_skips=0, fin_fetches=0)
            except Exception:
                pass

        def _process_one(item: Dict[str, Any]) -> Dict[str, Any]:
            stock_id = item.get("stock_id", "")
            stock_name = item.get("stock_name", "")
            hits = item.get("hits", []) or []
            sector_preview = "、".join([str(h.get("sector")) for h in hits[:2] if h.get("sector")])
            if len(hits) > 2:
                sector_preview += f"…等{len(hits)}組"

            base_item = day_cache.get(stock_id, {}) if isinstance(day_cache, dict) else {}

            # 第一段：只抓技術/法人/月營收，不主動抓財報。
            bundle, all_hit, hit_detail, updated_item, fetched_detail = get_radar_stock_bundle_parallel_item(
                stock_id, stock_name, base_item=base_item, include_fin=False
            )

            tech = bundle.get("tech") or {}
            flow = bundle.get("flow") or {}
            rev = bundle.get("rev") or {}

            should_fetch_fin = False
            quick_reasons = []
            for hit in hits:
                ok, reason = radar_fast_precheck_for_fin(
                    tech, flow, rev,
                    radar_mode=radar_mode,
                    sector_flow_status=str(hit.get("status", "") or ""),
                )
                quick_reasons.append(reason)
                if ok:
                    should_fetch_fin = True

            fin = {}
            local_fin_fetches = 0
            quick_status = "二段快篩通過"
            quick_reason = "；".join(dict.fromkeys([r for r in quick_reasons if r]))[:180]

            if should_fetch_fin:
                # 第二段：用第一段 updated_item 當 base，避免重抓 tech/flow/rev。
                bundle2, all_hit2, hit_detail2, updated_item, fetched_detail2 = get_radar_stock_bundle_parallel_item(
                    stock_id, stock_name, base_item=updated_item, include_fin=True
                )
                fin = (bundle2.get("fin") or {})
                if fetched_detail2.get("fin"):
                    local_fin_fetches += 1
                all_cache_hit = bool(all_hit2)
            else:
                quick_status = "二段快篩排除"
                all_cache_hit = bool(all_hit)
                fin = {}

            local_rows = []
            for hit in hits:
                sector = hit.get("sector", "")
                sector_flow_status = hit.get("status", "")
                status, note, action, risk = classify_stock_for_radar(
                    tech, flow, rev, radar_mode=radar_mode, sector_flow_status=sector_flow_status
                )
                if not should_fetch_fin and radar_mode in ["growth", "inflow"]:
                    note = (note + "｜" if note else "") + "快篩未進財報段"

                local_rows.append(
                    {
                        "掃描模式": mode_label,
                        "族群": sector,
                        "族群資金狀態": sector_flow_status or "—",
                        "股票": f"{stock_name} {stock_id}",
                        "即時股價": tech.get("close") if tech else None,
                        "狀態": status,
                        "風險等級": risk,
                        "法人5日": flow.get("inst_5d"),
                        "法人20日": flow.get("inst_20d"),
                        "法人40日": flow.get("inst_40d"),
                        "法人5日買超天數": flow.get("inst_buy_days_5"),
                        "月營收YoY": rev.get("revenue_yoy"),
                        "近1月營收YoY": rev.get("revenue_1m_yoy"),
                        "近1月營收MoM": rev.get("revenue_1m_mom"),
                        "近1月累計營收YoY": rev.get("revenue_ytd_yoy"),
                        "近3月營收YoY低": rev.get("revenue_3m_yoy_min"),
                        "近3月營收YoY均": rev.get("revenue_3m_yoy_avg"),
                        "近3月營收全>10": bool(rev.get("revenue_3m_all_gt10")),
                        "近1季EPSYoY": fin.get("eps_yoy"),
                        "近1季EPSQoQ": fin.get("eps_qoq"),
                        "近1季營益YoY": fin.get("operating_income_yoy"),
                        "近1季毛利YoY": fin.get("gross_profit_yoy"),
                        "近1季毛利率": fin.get("gross_margin"),
                        "近1季毛利率YoY差": fin.get("gross_margin_yoy_pp"),
                        "近1季營益率": fin.get("operating_margin"),
                        "財報來源": fin.get("source") if fin else ("快篩未抓財報" if not should_fetch_fin else ""),
                        "二段快篩": quick_status,
                        "二段快篩原因": quick_reason,
                        "快取命中": "是" if all_cache_hit else "部分/否",
                        "5日漲跌": tech.get("chg_5d") if tech else None,
                        "20日漲跌": tech.get("chg_20d") if tech else None,
                        "量比": tech.get("vol_ratio") if tech else None,
                        "20乖離": tech.get("bias20") if tech else None,
                        "60乖離": tech.get("bias60") if tech else None,
                        "MA5": tech.get("ma5") if tech else None,
                        "MA10": tech.get("ma10") if tech else None,
                        "MA20": tech.get("ma20") if tech else None,
                        "MA60": tech.get("ma60") if tech else None,
                        "MA120": tech.get("ma120") if tech else None,
                        "MA20>MA60": bool(tech.get("ma20_gt_ma60")) if tech else False,
                        "MA60>MA120": bool(tech.get("ma60_gt_ma120")) if tech else False,
                        "MA20上升": bool(tech.get("ma20_up_5d")) if tech else False,
                        "MA60角度": tech.get("ma60_angle") if tech else None,
                        "MA60十日變化": tech.get("ma60_change_10d_pct") if tech else None,
                        "均線差距": tech.get("ma_short_spread") if tech else None,
                        "站上MA60": bool(tech.get("above_ma60")) if tech else False,
                        "MA60角度>3": bool(tech.get("ma60_angle_ok")) if tech else False,
                        "MA60向上": bool(tech.get("ma60_angle_ok")) if tech else False,
                        "今日成交值": tech.get("trade_value_today") if tech else None,
                        "20日均量": tech.get("avg_volume20") if tech else None,
                        "40日均量": tech.get("avg_volume40") if tech else None,
                        "技術線K": tech.get("technical_k") if tech else None,
                        "Beta60": tech.get("beta60") if tech else None,
                        "短線支撐": tech.get("short_support") if tech else None,
                        "波段支撐": tech.get("swing_support") if tech else None,
                        "短線支撐距離": tech.get("short_support_dist") if tech else None,
                        "波段支撐距離": tech.get("swing_support_dist") if tech else None,
                        "位置": stock_position_label(tech),
                        "操作": action,
                        "操作提醒": note,
                    }
                )

            return {
                "stock_id": stock_id,
                "stock_name": stock_name,
                "sector_preview": sector_preview,
                "rows": local_rows,
                "cache_item": updated_item,
                "cache_hit": 1 if all_cache_hit else 0,
                "fast_skip": 0 if should_fetch_fin else 1,
                "fin_fetch": local_fin_fetches,
            }

        max_workers = max(1, min(int(RADAR_PARALLEL_WORKERS or 5), total_items or 1))
        results = []
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_map = {executor.submit(_process_one, item): item for item in scan_items}
            for future in as_completed(future_map):
                item0 = future_map.get(future) or {}
                try:
                    result = future.result()
                except Exception as e:
                    stock_id = item0.get("stock_id", "")
                    stock_name = item0.get("stock_name", "")
                    result = {
                        "stock_id": stock_id,
                        "stock_name": stock_name,
                        "sector_preview": "",
                        "rows": [],
                        "cache_item": None,
                        "cache_hit": 0,
                        "fast_skip": 0,
                        "fin_fetch": 0,
                        "error": str(e)[:80],
                    }

                results.append(result)
                rows.extend(result.get("rows") or [])
                cache_hits += int(result.get("cache_hit") or 0)
                fast_skips += int(result.get("fast_skip") or 0)
                fin_fetches += int(result.get("fin_fetch") or 0)
                completed += 1

                sid = str(result.get("stock_id") or "").strip()
                cache_item = result.get("cache_item")
                if sid and isinstance(cache_item, dict):
                    day_cache[sid] = cache_item

                if progress_cb:
                    try:
                        progress_cb(
                            completed,
                            total_items,
                            result.get("sector_preview", ""),
                            result.get("stock_name", ""),
                            result.get("stock_id", ""),
                            len(rows),
                            cache_hits=cache_hits,
                            duplicated_hits=duplicated_hits,
                            fast_skips=fast_skips,
                            fin_fetches=fin_fetches,
                        )
                    except Exception:
                        pass

        # 主執行緒統一寫入快取，避免平行寫檔。
        cache[today] = day_cache
        save_radar_stock_cache(cache)

        if progress_cb:
            try:
                progress_cb(total_items, total_items, "", "", "", len(rows), cache_hits=cache_hits, duplicated_hits=duplicated_hits, fast_skips=fast_skips, fin_fetches=fin_fetches)
            except Exception:
                pass

        payload = {
            "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
            "mode": radar_mode,
            "mode_label": mode_label,
            "rows": rows,
            "scan_total": total_items,
            "scan_unique_total": total_items,
            "scan_duplicate_hits": duplicated_hits,
            "cache_hits": cache_hits,
            "fast_skips": fast_skips,
            "fin_fetches": fin_fetches,
            "parallel_workers": max_workers,
        }
        if not rows:
            return payload, status_item("fail", False, "沒有掃到有效資料")
        return payload, status_item("ok", True, f"{mode_label}完成掃描 {len(rows)} 筆命中 / 去重 {total_items} 檔 / 平行 {max_workers} 檔 / 快篩省財報 {fast_skips} 檔 / 快取 {cache_hits} 檔")
    except Exception as e:
        payload = {
            "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
            "mode": radar_mode,
            "mode_label": mode_label,
            "rows": rows,
            "scan_total": total_items or len(rows),
            "scan_unique_total": total_items or len(rows),
            "scan_duplicate_hits": duplicated_hits,
            "cache_hits": cache_hits,
            "fast_skips": fast_skips,
            "fin_fetches": fin_fetches,
            "parallel_workers": RADAR_PARALLEL_WORKERS,
        }
        return payload, status_item("partial", bool(rows), f"部分完成：{e}")



def _market_quote_after_close(realtime_quote: Optional[Dict[str, Any]]) -> bool:
    """判斷 TWSE MIS 報價是否可視為「已完成日K」補值。

    修正版重點：
    - 當天 13:30 後：可以補今天收盤。
    - 隔天早上：如果 MIS 報價日期已經是昨天或更早，代表那是已完成交易日，也可以補。
    - 盤中：如果 MIS 日期等於今天且未到收盤，不能納入計算，只能畫盤中K。
    """
    if not realtime_quote:
        return False

    try:
        now = now_tw()
        qdate = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
        if not pd.isna(qdate):
            q_norm = qdate.normalize()
            today_norm = pd.Timestamp(now.date())
            # 隔天或非當日盤中看到的 MIS 報價，視為上一個完成交易日，可以補進日K。
            if q_norm < today_norm:
                return True
    except Exception:
        pass

    try:
        qtime = str(realtime_quote.get("time") or "").strip()
        if qtime:
            parts = qtime.split(":")
            if len(parts) >= 2:
                hh = int(parts[0])
                mm = int(parts[1])
                if (hh, mm) >= (13, 30):
                    return True
    except Exception:
        pass

    try:
        now = now_tw()
        return (now.hour, now.minute) >= (13, 35)
    except Exception:
        return False


def _is_completed_market_date(dt: Any) -> bool:
    """判斷某日期是否可視為已完成日K。

    原則：
    - 早於今天：完成日K。
    - 今天：必須 13:35 後才算完成日K。
    - 今天盤中：不可併入正式日K，只能當盤中K顯示。
    """
    d = pd.to_datetime(dt, errors="coerce")
    if pd.isna(d):
        return False
    try:
        now = now_tw()
        d_norm = d.normalize()
        today_norm = pd.Timestamp(now.date())
        if d_norm < today_norm:
            return True
        if d_norm > today_norm:
            return False
        return (now.hour, now.minute) >= (13, 35)
    except Exception:
        return False


def _remove_unfinished_today_kline(df: pd.DataFrame) -> Tuple[pd.DataFrame, bool, str]:
    """移除 Yahoo/TWSE 可能塞進來的今日盤中日K。

    這是為了讓大盤K線行為跟個股分析器一致：
    - 已完成日K保留
    - 盤中K只在圖上另外新增
    - 盤中K不得覆蓋最後一根已完成日K
    """
    if df is None or df.empty or "date" not in df.columns:
        return df, False, "無資料"
    work = df.copy().sort_values("date").reset_index(drop=True)
    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")
    if pd.isna(last_date):
        return work, False, "最後日期無效"
    if not _is_completed_market_date(last_date):
        work = work.iloc[:-1].copy().reset_index(drop=True)
        finalized, err = _finalize_market_kline_df(work)
        if finalized is None:
            return df, False, f"移除盤中日K後整理失敗：{err}"
        return finalized, True, f"已移除未收盤日K {last_date.strftime('%Y-%m-%d')}，改由盤中K顯示"
    return work, False, "最後一根已完成"


def merge_market_realtime_quote_for_update(
    df: pd.DataFrame,
    realtime_quote: Optional[Dict[str, Any]],
) -> Tuple[pd.DataFrame, bool, str]:
    """大盤更新後補 TWSE MIS 最新報價。

    用途：
    - Yahoo Chart 日K常常盤後延遲，導致按「更新大盤」仍停在舊收盤。
    - 若已過收盤時間，MIS 有今日加權指數報價，則把它補成最新一根K。
    - 補值後重新計算 MA/VolMA，讓總覽、K線與裁決同步更新。

    注意：
    - 只有收盤後才補進計算。
    - 盤中仍維持原本規則：即時K只顯示，不納入計算。
    """
    if df is None or df.empty or not realtime_quote:
        return df, False, "無即時報價可補"

    q_price = to_float(realtime_quote.get("price"))
    q_date = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
    if q_price is None or pd.isna(q_date):
        return df, False, "即時報價價格或日期無效"

    work = df.copy().sort_values("date").reset_index(drop=True)
    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")
    q_norm = q_date.normalize()

    # 是否可把 MIS 報價併入日K：
    # 1) 收盤後可併入；
    # 2) 隔天早上若 MIS 日期比 Yahoo 日K 新，也要併入，避免 Yahoo 日K延遲造成圖停在舊日期。
    can_merge_quote = _market_quote_after_close(realtime_quote)
    try:
        now_norm = pd.Timestamp(now_tw().date())
        if not pd.isna(last_date) and q_norm > last_date.normalize() and q_norm < now_norm:
            can_merge_quote = True
    except Exception:
        pass

    if not can_merge_quote:
        return df, False, "尚未收盤，盤中報價不納入大盤計算"

    q_open = to_float(realtime_quote.get("open")) or q_price
    q_high = to_float(realtime_quote.get("high")) or max(q_open, q_price)
    q_low = to_float(realtime_quote.get("low")) or min(q_open, q_price)
    q_volume = to_float(realtime_quote.get("volume")) or 0

    new_row = {
        "date": q_norm,
        "open": q_open,
        "max": max(q_high, q_open, q_price),
        "min": min(q_low, q_open, q_price),
        "close": q_price,
        "volume": q_volume,
    }

    merged = False
    if pd.isna(last_date) or q_norm > last_date.normalize():
        # Yahoo 日K還沒更新到今天：append 今日收盤
        work = pd.concat([work, pd.DataFrame([new_row])], ignore_index=True)
        merged = True
        note = f"已用 TWSE MIS 補上 {q_norm.strftime('%Y-%m-%d')} 收盤"
    elif q_norm == last_date.normalize():
        # 同一天但 Yahoo 值可能延遲/不同：用 MIS 覆蓋最新一根
        for k, v in new_row.items():
            if k in work.columns:
                work.loc[work.index[-1], k] = v
        merged = True
        note = f"已用 TWSE MIS 覆蓋 {q_norm.strftime('%Y-%m-%d')} 收盤"
    else:
        return work, False, "TWSE MIS 日期沒有比日K新"

    # 補值後重新計算均線與量均線，讓總覽與K線同步更新。
    for col in ["MA5", "MA10", "MA20", "MA60", "VolMA5", "VolMA20"]:
        if col in work.columns:
            work = work.drop(columns=[col])

    finalized, err = _finalize_market_kline_df(work)
    if finalized is None:
        return df, False, f"補值後整理失敗：{err}"

    return finalized, merged, note



