# 盤後資金結構 / 上漲來源
# =========================================================
def _parse_twse_money_value(v: Any) -> Optional[float]:
    """TWSE 金額欄位轉 float，保留元為單位。"""
    if v is None:
        return None
    try:
        s = str(v).replace(",", "").replace("+", "").strip()
        if s in ["", "-", "--", "nan", "None", "null"]:
            return None
        return float(s)
    except Exception:
        return None


def _twse_api_json(url: str, params: Dict[str, Any]) -> Tuple[Optional[Any], str]:
    """TWSE API helper with small retry.

    fix24:
    Streamlit Cloud / iPad WebView 偶發 TWSE API timeout 或回傳空資料。
    這裡加上較完整 headers 與 2 次短重試，降低盤後法人資料變成空白的機率。
    """
    headers = {
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Safari/604.1",
        "Accept": "application/json,text/plain,*/*",
        "Accept-Language": "zh-TW,zh;q=0.9,en;q=0.8",
        "Referer": "https://www.twse.com.tw/",
    }
    last_err = ""
    for attempt in range(2):
        try:
            r = requests.get(url, params=params, timeout=max(REQUEST_TIMEOUT, 12), headers=headers)
            if r.status_code != 200:
                last_err = f"HTTP {r.status_code}"
                continue
            js = r.json()
            return js, ""
        except Exception as e:
            last_err = str(e)
    return None, last_err


def fetch_twse_institutional_amount(date: Optional[datetime] = None, lookback_days: int = 14) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """抓 TWSE 三大法人買賣超金額。

    僅抓上市 TWSE，因為加權指數主體是上市市場。
    單位換算成億元。若今日盤後資料尚未更新，往前找最近一個有資料的交易日。
    """
    base_d = date or now_tw()
    url = "https://www.twse.com.tw/rwd/zh/fund/BFI82U"
    last_err = ""

    for offset in range(0, max(1, int(lookback_days))):
        d = base_d - timedelta(days=offset)
        ymd = d.strftime("%Y%m%d")
        js, err = _twse_api_json(url, {"date": ymd, "response": "json"})
        if js is None:
            last_err = f"{ymd} {err}"
            continue

        data = js.get("data") or []
        if not data:
            last_err = f"{ymd} 無資料"
            continue

        result = {
            "date": ymd,
            "source": "TWSE BFI82U",
            "rows": [],
            "foreign": None,
            "investment_trust": None,
            "dealer": None,
            "total_inst": None,
            "other_estimate": None,
        }

        total_diff = 0.0
        has_any = False

        def classify_name(name: str) -> str:
            n = str(name)
            if "外資" in n or "陸資" in n:
                return "foreign"
            if "投信" in n:
                return "investment_trust"
            if "自營商" in n:
                return "dealer"
            return "other"

        for row in data:
            if not isinstance(row, list) or len(row) < 4:
                continue
            name = str(row[0])
            buy = _parse_twse_money_value(row[1])
            sell = _parse_twse_money_value(row[2])
            diff = _parse_twse_money_value(row[3])
            if diff is None and buy is not None and sell is not None:
                diff = buy - sell
            if diff is None:
                continue

            diff_100m = diff / 100_000_000
            key = classify_name(name)
            if key in ["foreign", "investment_trust", "dealer"]:
                if result.get(key) is None:
                    result[key] = 0.0
                result[key] += diff_100m
                total_diff += diff_100m
                has_any = True

            result["rows"].append({
                "名稱": name,
                "買進(億)": None if buy is None else round(buy / 100_000_000, 2),
                "賣出(億)": None if sell is None else round(sell / 100_000_000, 2),
                "買賣超(億)": round(diff_100m, 2),
            })

        if not has_any:
            last_err = f"{ymd} 格式異常"
            continue

        result["total_inst"] = total_diff
        # 其他資金推估：不是散戶，也不是主力；只是三大法人以外資金的相對方向估計。
        result["other_estimate"] = -total_diff
        status_note = f"TWSE 三大法人成功更新：{ymd}"
        if offset > 0:
            status_note += "（今日資料未出，採最近交易日）"
        return result, status_item("ok", True, status_note)

    return {}, status_item("partial", False, f"TWSE 三大法人資料尚未更新或抓取失敗：{last_err}")






def get_snapshot_trade_date(snapshot: Dict[str, Any]) -> str:
    """取得資料交易日，不用掃描當天日期。

    目的：
    - 週六/週日重掃週五資料時，仍記錄為週五交易日。
    - 族群強度歷史、資金流、雷達結果都用同一個資料交易日。
    """
    def _clean_date(v: Any) -> Optional[str]:
        if v in [None, "", "—"]:
            return None
        try:
            d = pd.to_datetime(v, errors="coerce")
            if not pd.isna(d):
                return d.strftime("%Y-%m-%d")
        except Exception:
            pass
        try:
            s = normalize_date_str(v)
            if s and s not in ["—", "NaT", "None"]:
                d = pd.to_datetime(s, errors="coerce")
                if not pd.isna(d):
                    return d.strftime("%Y-%m-%d")
        except Exception:
            pass
        return None

    snapshot = snapshot or {}
    market = snapshot.get("market") or {}
    breadth = snapshot.get("market_breadth") or {}
    flow = snapshot.get("flow") or {}

    candidates: List[Any] = [
        (market.get("last") or {}).get("date"),
        breadth.get("trade_date"),
        flow.get("trade_date"),
    ]

    # 大盤 K 線最後一根日期最可靠，因為這是已完成交易日資料。
    try:
        kline = market.get("kline") or []
        if isinstance(kline, list) and kline:
            candidates.insert(1, (kline[-1] or {}).get("date"))
    except Exception:
        pass

    # 若各雷達已有交易日，也可當備援。
    try:
        rbm = snapshot.get("radar_by_mode") or {}
        if isinstance(rbm, dict):
            for rv in rbm.values():
                if isinstance(rv, dict):
                    candidates.append(rv.get("trade_date"))
    except Exception:
        pass

    for c in candidates:
        d = _clean_date(c)
        if d:
            return d

    # 最後才用系統今天，避免沒有大盤資料時整個流程掛掉。
    try:
        return now_tw().strftime("%Y-%m-%d")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d")



def update_market_breadth_price_history(snapshot: Dict[str, Any], df: pd.DataFrame, keep_days: int = 70) -> List[Dict[str, Any]]:
    """累積全市場日行情收盤價，用於市場寬度 MA20/MA60、新高/新低。

    設計重點：
    - 不逐檔額外抓 K 線，只利用「更新大盤資料」時已抓到的上市櫃日行情。
    - 需要連續累積資料；不足 20/60 天時會顯示資料累積中。
    - 每天同一日期只保留最新一份，避免重複塞資料。
    """
    if df is None or df.empty:
        return snapshot.get("market_breadth_price_history") or []

    trade_date = get_snapshot_trade_date(snapshot)
    scan_time = now_tw().strftime("%Y-%m-%d %H:%M:%S")
    prices = {}
    for _, r in df.iterrows():
        sid = clean_stock_id(r.get("stock_id"))
        close = to_float(r.get("close"))
        if is_common_stock_id(sid) and close is not None and close > 0:
            prices[sid] = round(float(close), 4)

    if not prices:
        return snapshot.get("market_breadth_price_history") or []

    history = snapshot.get("market_breadth_price_history") or []
    if not isinstance(history, list):
        history = []

    history = [h for h in history if isinstance(h, dict) and h.get("date") != trade_date]
    history.append({"date": trade_date, "scan_time": scan_time, "prices": prices})
    history = sorted(history, key=lambda x: str(x.get("date") or ""))[-keep_days:]
    snapshot["market_breadth_price_history"] = history
    return history


def _compute_price_history_breadth(df: pd.DataFrame, price_history: Optional[List[Dict[str, Any]]]) -> Dict[str, Any]:
    """用已累積的每日收盤價計算 MA20/MA60 與 20日新高新低家數。"""
    result = {
        "history_days": 0,
        "ma20_ready": False,
        "ma60_ready": False,
        "above_ma20_count": None,
        "above_ma60_count": None,
        "above_ma20_ratio": None,
        "above_ma60_ratio": None,
        "new_high_20_count": None,
        "new_low_20_count": None,
        "new_high_20_ratio": None,
        "new_low_20_ratio": None,
        "advanced_note": "市場寬度進階資料累積中。",
    }

    if not price_history or not isinstance(price_history, list):
        return result

    hist = [h for h in price_history if isinstance(h, dict) and isinstance(h.get("prices"), dict)]
    hist = sorted(hist, key=lambda x: str(x.get("date") or ""))
    result["history_days"] = len(hist)
    if not hist:
        return result

    current_prices = {}
    for _, r in df.iterrows():
        sid = clean_stock_id(r.get("stock_id"))
        close = to_float(r.get("close"))
        if is_common_stock_id(sid) and close is not None and close > 0:
            current_prices[sid] = float(close)

    if not current_prices:
        return result

    def _series_for_sid(sid: str) -> List[float]:
        arr = []
        for h in hist:
            px = to_float((h.get("prices") or {}).get(sid))
            if px is not None and px > 0:
                arr.append(float(px))
        return arr

    total = 0
    above20 = above60 = high20 = low20 = 0
    ma20_ready_count = ma60_ready_count = 0

    for sid, close in current_prices.items():
        arr = _series_for_sid(sid)
        if not arr:
            continue
        # 若今天已在 history 內，arr[-1]通常就是今天；否則以 current close 補入。
        if abs(arr[-1] - close) > 1e-6:
            arr = arr + [close]

        total += 1
        if len(arr) >= 20:
            ma20_ready_count += 1
            last20 = arr[-20:]
            ma20 = sum(last20) / len(last20)
            if close >= ma20:
                above20 += 1
            if close >= max(last20):
                high20 += 1
            if close <= min(last20):
                low20 += 1

        if len(arr) >= 60:
            ma60_ready_count += 1
            last60 = arr[-60:]
            ma60 = sum(last60) / len(last60)
            if close >= ma60:
                above60 += 1

    if ma20_ready_count > 0:
        result["ma20_ready"] = True
        result["above_ma20_count"] = above20
        result["above_ma20_ratio"] = round(above20 / ma20_ready_count * 100, 1)
        result["new_high_20_count"] = high20
        result["new_low_20_count"] = low20
        result["new_high_20_ratio"] = round(high20 / ma20_ready_count * 100, 1)
        result["new_low_20_ratio"] = round(low20 / ma20_ready_count * 100, 1)

    if ma60_ready_count > 0:
        result["ma60_ready"] = True
        result["above_ma60_count"] = above60
        result["above_ma60_ratio"] = round(above60 / ma60_ready_count * 100, 1)

    notes = []
    if result["ma20_ready"]:
        notes.append(f"站上 MA20 比例 {result['above_ma20_ratio']}%，用來看短線反彈廣度。")
    else:
        notes.append("MA20 寬度資料累積中，需至少 20 個更新交易日。")
    if result["ma60_ready"]:
        notes.append(f"站上 MA60 比例 {result['above_ma60_ratio']}%，用來看中期結構是否轉強。")
    else:
        notes.append("MA60 寬度資料累積中，需至少 60 個更新交易日。")
    if result["ma20_ready"]:
        notes.append(f"20日新高 {result['new_high_20_count']} 家 / 20日新低 {result['new_low_20_count']} 家，用來看市場攻擊力與破底壓力。")

    result["advanced_note"] = " ".join(notes)
    return result


def compute_market_breadth_from_daily_all(df: pd.DataFrame, price_history: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
    """市場寬度：判斷今天是真的強，還是指數被少數權值撐起來。"""
    if df is None or df.empty or "change_pct" not in df.columns:
        return {
            "ok": False,
            "score": None,
            "verdict": "資料不足",
            "summary": "尚無上市櫃日行情，無法判斷市場寬度。",
            "rows": [],
        }

    work = df.copy()
    work["change_pct"] = work["change_pct"].apply(to_float)
    work = work.dropna(subset=["change_pct"])
    work = work[work["stock_id"].astype(str).str.match(r"^\d{4}$", na=False)]
    if work.empty:
        return {
            "ok": False,
            "score": None,
            "verdict": "資料不足",
            "summary": "上市櫃日行情清洗後無有效資料。",
            "rows": [],
        }

    total = int(len(work))
    adv = int((work["change_pct"] > 0).sum())
    dec = int((work["change_pct"] < 0).sum())
    flat = int((work["change_pct"] == 0).sum())
    strong_up = int((work["change_pct"] >= 3).sum())
    strong_down = int((work["change_pct"] <= -3).sum())
    limit_up = int((work["change_pct"] >= 9.5).sum())
    limit_down = int((work["change_pct"] <= -9.5).sum())
    median_chg = float(work["change_pct"].median())
    avg_chg = float(work["change_pct"].mean())
    adv_ratio = adv / total * 100 if total else 0
    dec_ratio = dec / total * 100 if total else 0
    strong_balance = strong_up - strong_down
    limit_balance = limit_up - limit_down

    score = 50.0
    score += (adv_ratio - 50) * 0.55
    score += max(-12, min(12, median_chg * 5.0))
    score += max(-10, min(10, strong_balance / max(total, 1) * 250))
    score += max(-6, min(6, limit_balance * 0.8))

    advanced = _compute_price_history_breadth(work, price_history)
    ma20_ratio = to_float(advanced.get("above_ma20_ratio"))
    ma60_ratio = to_float(advanced.get("above_ma60_ratio"))
    nh20 = to_float(advanced.get("new_high_20_count"))
    nl20 = to_float(advanced.get("new_low_20_count"))

    # 進階寬度只做輕度修正，避免剛開始資料不完整時影響太大。
    if ma20_ratio is not None:
        score += max(-6, min(6, (ma20_ratio - 50) * 0.12))
    if ma60_ratio is not None:
        score += max(-5, min(5, (ma60_ratio - 50) * 0.10))
    if nh20 is not None and nl20 is not None:
        score += max(-5, min(5, (nh20 - nl20) * 0.05))

    score = max(0, min(100, score))

    if score >= 72:
        verdict = "市場全面偏強"
        summary = "上漲家數與強勢股同步擴散，屬於比較健康的進攻盤。"
    elif score >= 58:
        verdict = "市場寬度偏多"
        summary = "多數股票有跟上，適合從資金分流中找回檔轉強與主流延伸。"
    elif score >= 45:
        verdict = "市場寬度普通"
        summary = "不是全面強盤，容易出現族群輪動；要精選資金有流入的標的。"
    elif score >= 32:
        verdict = "市場寬度偏弱"
        summary = "下跌家數偏多，指數若上漲也可能是權值撐盤；新倉要保守。"
    else:
        verdict = "市場寬度轉弱"
        summary = "市場多數股票偏弱，優先防守，個股只看最強族群與明確支撐。"

    rows = [
        {"項目": "上漲家數", "數值": adv, "解讀": f"{adv_ratio:.1f}%"},
        {"項目": "下跌家數", "數值": dec, "解讀": f"{dec_ratio:.1f}%"},
        {"項目": "平盤家數", "數值": flat, "解讀": "市場觀望"},
        {"項目": "強漲 ≥3%", "數值": strong_up, "解讀": "攻擊股數量"},
        {"項目": "強跌 ≤-3%", "數值": strong_down, "解讀": "退潮股數量"},
        {"項目": "漲停近似", "數值": limit_up, "解讀": "短線情緒"},
        {"項目": "跌停近似", "數值": limit_down, "解讀": "風險情緒"},
        {"項目": "中位數漲跌", "數值": f"{median_chg:.2f}%", "解讀": "多數股票體感"},
        {"項目": "平均漲跌", "數值": f"{avg_chg:.2f}%", "解讀": "全市場平均"},
        {"項目": "站上 MA20 比例", "數值": "累積中" if advanced.get("above_ma20_ratio") is None else f"{advanced.get('above_ma20_ratio')}%", "解讀": "短線反彈廣度"},
        {"項目": "站上 MA60 比例", "數值": "累積中" if advanced.get("above_ma60_ratio") is None else f"{advanced.get('above_ma60_ratio')}%", "解讀": "中期結構廣度"},
        {"項目": "20日新高 / 新低", "數值": "累積中" if advanced.get("new_high_20_count") is None else f"{advanced.get('new_high_20_count')} / {advanced.get('new_low_20_count')}", "解讀": "攻擊力 vs 破底壓力"},
    ]

    return {
        "ok": True,
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "score": round(score, 1),
        "verdict": verdict,
        "summary": summary,
        "total": total,
        "advancers": adv,
        "decliners": dec,
        "flat": flat,
        "adv_ratio": round(adv_ratio, 1),
        "dec_ratio": round(dec_ratio, 1),
        "strong_up": strong_up,
        "strong_down": strong_down,
        "limit_up": limit_up,
        "limit_down": limit_down,
        "median_change": round(median_chg, 2),
        "avg_change": round(avg_chg, 2),
        "rows": rows,
        **advanced,
    }


def render_market_breadth_card(snapshot: Dict[str, Any]) -> None:
    """總覽頁：市場寬度。判斷大盤是真的強，還是權值股撐盤。"""
    breadth = snapshot.get("market_breadth") or {}
    if not breadth:
        st.markdown("### 🌊 市場寬度｜是真的強，還是權值撐盤？")
        st.info("尚未更新市場寬度。請按「更新大盤資料」，系統會同步抓上市櫃日行情。")
        return

    score = to_float(breadth.get("score"))
    score_text = "—" if score is None else f"{score:.1f}/100"

    if score is None:
        color = "#94a3b8"
    elif score >= 72:
        color = "#86efac"
    elif score >= 58:
        color = "#bef264"
    elif score >= 45:
        color = "#facc15"
    elif score >= 32:
        color = "#fdba74"
    else:
        color = "#fca5a5"

    ma20_text = "累積中" if breadth.get("above_ma20_ratio") is None else f"{breadth.get('above_ma20_ratio')}%"
    ma60_text = "累積中" if breadth.get("above_ma60_ratio") is None else f"{breadth.get('above_ma60_ratio')}%"
    highlow_text = "累積中" if breadth.get("new_high_20_count") is None else f"{breadth.get('new_high_20_count')} / {breadth.get('new_low_20_count')}"

    st.markdown("### 🌊 市場寬度｜是真的強，還是權值撐盤？")
    st.markdown(
        f"""
<div class="card">
  <div class="card-title">市場寬度分數</div>
  <div class="big-verdict" style="color:{color};">{score_text}｜{breadth.get('verdict', '—')}</div>
  <div class="subtle">{breadth.get('summary', '')}</div>
  <div class="metric-row">
    <span class="metric-pill">上漲：{breadth.get('advancers', '—')} 家</span>
    <span class="metric-pill">下跌：{breadth.get('decliners', '—')} 家</span>
    <span class="metric-pill">上漲占比：{breadth.get('adv_ratio', '—')}%</span>
    <span class="metric-pill">強漲≥3%：{breadth.get('strong_up', '—')} 家</span>
    <span class="metric-pill">強跌≤-3%：{breadth.get('strong_down', '—')} 家</span>
  </div>
  <hr />
  <div class="metric-row">
    <span class="metric-pill">站上MA20：{ma20_text}</span>
    <span class="metric-pill">站上MA60：{ma60_text}</span>
    <span class="metric-pill">20日新高 / 新低：{highlow_text}</span>
  </div>
  <div class="subtle">{breadth.get('advanced_note', '進階市場寬度資料累積中。')}</div>
  <div class="subtle">資料交易日：{breadth.get('trade_date') or get_snapshot_trade_date(snapshot)}｜掃描時間：{breadth.get('scan_time') or breadth.get('updated_at', '—')}</div>
  <div class="subtle">重點：MA20看短線反彈廣度；MA60看中期結構；20日新高/新低看攻擊力與破底壓力。</div>
</div>
""",
        unsafe_allow_html=True,
    )

    rows = breadth.get("rows") or []
    if rows:
        with st.expander("查看市場寬度明細", expanded=False):
            st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)



def compute_market_rise_sources(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    """判斷今日大盤上漲來源。

    這不是精準指數貢獻分解，而是用目前 App 已有資料做「來源判讀」：
    - 大盤漲跌
    - 市場寬度
    - 資金流向分類
    - 三大法人買賣超
    - 外部環境分數
    """
    market = snapshot.get("market") or {}
    flow = snapshot.get("flow") or {}
    inst = snapshot.get("institutional") or {}
    external = snapshot.get("external") or {}
    breadth = snapshot.get("market_breadth") or {}

    last = market.get("last") or {}
    change_pct = to_float(last.get("change_pct"))
    close = to_float(last.get("close"))

    rows = flow.get("rows") or []
    status_counts: Dict[str, int] = {}
    for r in rows:
        s = r.get("狀態") or "觀察中"
        status_counts[s] = status_counts.get(s, 0) + 1

    foreign = to_float(inst.get("foreign"))
    trust = to_float(inst.get("investment_trust"))
    dealer = to_float(inst.get("dealer"))
    total_inst = to_float(inst.get("total_inst"))

    # 外部風險快照的 score 在 external["score"]，
    # 不是 external["summary"]["score"]；summary 是文字。
    external_score = to_float(external.get("score"))

    breadth_score = to_float(breadth.get("score"))
    adv_ratio = to_float(breadth.get("adv_ratio"))
    strong_up = int(to_float(breadth.get("strong_up")) or 0)
    strong_down = int(to_float(breadth.get("strong_down")) or 0)

    main_count = status_counts.get("明面主流", 0)
    stealth_count = status_counts.get("偷偷流入", 0)
    low_count = status_counts.get("低基期轉強", 0)
    pullback_count = status_counts.get("回檔轉強", 0)
    dull_count = status_counts.get("主流鈍化", 0)
    weak_count = status_counts.get("退潮轉弱", 0)
    inflow_count = main_count + stealth_count + low_count + pullback_count

    clues = []
    source_rows = []

    def _add_source(name: str, score_v: Any, signal: str, read: str, action: str) -> None:
        source_rows.append({
            "來源": name,
            "強度": score_v,
            "訊號": signal,
            "解讀": read,
            "導向": action,
        })

    # 1) 指數本身
    if change_pct is not None:
        if change_pct >= 2:
            idx_signal = "指數大漲"
            idx_read = "先確認是否全面擴散，或只是權值拉抬。"
            idx_score = "強"
            clues.append("指數大漲，先判斷是否由權值股、外資回補或少數大型股推動。")
        elif change_pct >= 0.8:
            idx_signal = "指數明顯上漲"
            idx_read = "觀察市場寬度與族群是否同步擴散。"
            idx_score = "中強"
            clues.append("指數明顯上漲，觀察族群是否同步擴散。")
        elif change_pct >= 0:
            idx_signal = "指數小漲"
            idx_read = "偏震盪回穩，不能只因指數紅就追高。"
            idx_score = "普通"
            clues.append("指數小漲，偏震盪回穩。")
        else:
            idx_signal = "指數下跌"
            idx_read = "先看支撐與退潮族群，不急著開新倉。"
            idx_score = "弱"
            clues.append("指數下跌或壓回。")
        _add_source("指數表現", idx_score, idx_signal, idx_read, "先看盤勢裁決")
    else:
        _add_source("指數表現", "—", "資料不足", "尚無大盤漲跌資料。", "先更新大盤資料")

    # 2) 市場寬度
    if breadth_score is not None:
        if breadth_score >= 72:
            b_signal = "全面擴散"
            b_read = f"上漲占比 {adv_ratio if adv_ratio is not None else '—'}%，強漲股多，屬健康上漲。"
            b_action = "可看主流＋回檔轉強"
            clues.append("市場寬度偏強，代表不是只有權值股撐盤。")
        elif breadth_score >= 58:
            b_signal = "寬度偏多"
            b_read = f"多數股票有跟上，市場承接尚可。"
            b_action = "看資金流入成長股雷達"
            clues.append("市場寬度偏多，資金有擴散跡象。")
        elif breadth_score >= 45:
            b_signal = "寬度普通"
            b_read = "不是全面強盤，容易變成族群輪動。"
            b_action = "只做資金分流強的族群"
            clues.append("市場寬度普通，需精選族群。")
        else:
            b_signal = "寬度偏弱"
            b_read = "指數若上漲，可能是權值撐盤或少數股拉抬。"
            b_action = "看退潮雷達 / 控倉"
            clues.append("市場寬度偏弱，需小心指數強但多數股票弱。")
        _add_source("市場寬度", f"{breadth_score:.1f}/100", b_signal, b_read, b_action)
    else:
        _add_source("市場寬度", "—", "未更新", "尚未計算市場寬度。", "更新大盤資料")

    # 3) 資金分流
    if main_count >= 3:
        flow_signal = "明面主流"
        flow_read = f"明面主流 {main_count} 組，資金有明確追價方向。"
        flow_action = "看明面主流＋回檔轉強"
        clues.append(f"明面主流 {main_count} 組，市場資金有明顯追價族群。")
    elif stealth_count + pullback_count + low_count >= 6:
        flow_signal = "分流回補"
        flow_read = f"偷偷流入/回檔轉強/低基期合計 {stealth_count + pullback_count + low_count} 組，資金正在分散卡位。"
        flow_action = "看偷偷流入 / 低基期 / 回檔轉強"
        clues.append(f"偷偷流入/回檔轉強/低基期合計 {stealth_count + pullback_count + low_count} 組，偏資金回補但未全面主流化。")
    elif weak_count >= 10:
        flow_signal = "退潮偏多"
        flow_read = f"退潮轉弱 {weak_count} 組，指數若上漲可能集中在少數權值。"
        flow_action = "看資金流入成長股雷達"
        clues.append(f"退潮轉弱 {weak_count} 組，代表指數上漲可能集中在少數權值，不是全面擴散。")
    elif dull_count >= 5:
        flow_signal = "舊主流鈍化"
        flow_read = f"主流鈍化 {dull_count} 組，資金可能在換手或尋找新方向。"
        flow_action = "等新主流接棒"
        clues.append(f"主流鈍化 {dull_count} 組，舊主流熱度下降。")
    else:
        flow_signal = "族群普通"
        flow_read = "族群廣度普通，需看權值股與法人是否主導。"
        flow_action = "觀察族群擴散"
        clues.append("族群廣度普通，需看權值股與法人是否主導。")
    _add_source("資金分流", inflow_count, flow_signal, flow_read, flow_action)

    # 4) 法人資金
    if total_inst is not None:
        if total_inst > 100:
            inst_signal = "法人明顯買超"
            inst_read = f"三大法人買超約 {total_inst:.1f} 億，偏外資/法人推升。"
            inst_action = "可看權值與主流族群"
            clues.append(f"三大法人買超約 {total_inst:.1f} 億，偏法人推升。")
        elif total_inst < -100:
            inst_signal = "法人明顯賣超"
            inst_read = f"三大法人賣超約 {abs(total_inst):.1f} 億，指數若上漲需小心內資撐盤。"
            inst_action = "控倉 / 看承接"
            clues.append(f"三大法人賣超約 {abs(total_inst):.1f} 億，指數若上漲可能由內資或軋空推動。")
        else:
            inst_signal = "法人中性"
            inst_read = "法人買賣超不大，指數來源需看內資與族群輪動。"
            inst_action = "看資金分流"
            clues.append("法人買賣超不大，指數來源需看內資與權值結構。")
        _add_source("法人資金", f"{total_inst:.1f}億", inst_signal, inst_read, inst_action)
    else:
        _add_source("法人資金", "—", "資料不足", "三大法人資料尚未更新。", "更新大盤資料")

    # 5) 外部風險
    if external_score is not None:
        if external_score >= 65:
            ext_signal = "外部助攻"
            ext_read = "美股/費半/VIX等外部環境偏友善，台股承接力較強。"
            ext_action = "可放大觀察主流"
            clues.append("外部環境偏助攻，台股承接力較強。")
        elif external_score <= 40:
            ext_signal = "外部壓力"
            ext_read = "外部環境仍有壓力，台股上漲需確認不是短線修復。"
            ext_action = "降低追價"
            clues.append("外部環境仍有壓力，台股上漲需看是否只是短線修復。")
        else:
            ext_signal = "外部中性"
            ext_read = "外部沒有明確助攻或壓力，仍以台股價量與資金為主。"
            ext_action = "回到盤面訊號"
        _add_source("外部環境", f"{external_score:.1f}/100", ext_signal, ext_read, ext_action)
    else:
        _add_source("外部環境", "—", "未更新", "外部風險尚未更新。", "可更新外部風險")

    # 綜合結論
    if change_pct is not None and change_pct >= 0 and breadth_score is not None and breadth_score < 45:
        conclusion = "指數紅但市場寬度不足，偏權值撐盤；不要只看指數追高。"
        source_type = "權值撐盤型"
    elif breadth_score is not None and breadth_score >= 58 and main_count >= 3:
        conclusion = "指數、寬度與主流族群同步偏強，屬擴散型上漲。"
        source_type = "全面擴散型"
    elif main_count >= 3:
        conclusion = "主流族群明確，但仍要看市場寬度是否跟上。"
        source_type = "主流推升型"
    elif stealth_count + pullback_count + low_count >= 6:
        conclusion = "市場偏回補型上漲，資金有回流但主流尚未完全定調。"
        source_type = "分流回補型"
    elif weak_count >= 10:
        conclusion = "退潮族群仍多，需小心指數上漲但個股不跟。"
        source_type = "退潮警戒型"
    else:
        conclusion = "上漲來源混合，需搭配法人、寬度與資金分流確認。"
        source_type = "混合觀察型"

    return {
        "close": close,
        "change_pct": change_pct,
        "status_counts": status_counts,
        "institutional": inst,
        "external_score": external_score,
        "breadth_score": breadth_score,
        "clues": clues,
        "source_rows": source_rows,
        "source_type": source_type,
        "conclusion": conclusion,
        "strong_up": strong_up,
        "strong_down": strong_down,
    }




def render_after_market_funds_card(snapshot: Dict[str, Any], compact: bool = False) -> None:
    """盤後資金結構。

    v3.2.1：
    - compact=True 時給總裁決內嵌使用
    - 拿掉「說明」欄，避免手機畫面太擠
    """
    inst = snapshot.get("institutional") or {}
    status = (snapshot.get("statuses") or {}).get("盤後資金結構") or {}

    title = "💰 盤後資金結構"
    if not compact:
        st.markdown(f"### {title}")

    if not inst:
        st.info("尚未更新盤後資金結構。請按上方「更新大盤資料」後查看。")
        return

    def fmt_bil(v):
        x = to_float(v)
        if x is None:
            return "—"
        sign = "+" if x > 0 else ""
        return f"{sign}{x:.1f} 億"

    source = compute_market_rise_sources(snapshot)
    counts = source.get("status_counts") or {}
    main_count = counts.get("明面主流", 0)
    stealth_count = counts.get("偷偷流入", 0)
    pullback_count = counts.get("回檔轉強", 0)
    weak_count = counts.get("退潮轉弱", 0)

    if main_count >= 3:
        smart = "強"
    elif stealth_count + pullback_count >= 6:
        smart = "中偏強"
    elif weak_count >= 10:
        smart = "弱 / 偏權值"
    else:
        smart = "中性"

    rows = [
        {"項目": "外資", "買賣超": fmt_bil(inst.get("foreign"))},
        {"項目": "投信", "買賣超": fmt_bil(inst.get("investment_trust"))},
        {"項目": "自營商", "買賣超": fmt_bil(inst.get("dealer"))},
        {"項目": "三大法人合計", "買賣超": fmt_bil(inst.get("total_inst"))},
        {"項目": "其他資金推估", "買賣超": fmt_bil(inst.get("other_estimate"))},
        {"項目": "主力跡象", "買賣超": smart},
    ]

    if compact:
        st.markdown("#### 💰 盤後資金結構")
