def update_sector_flow_strength_history(snapshot: Dict[str, Any], keep_days: int = 30) -> Dict[str, Any]:
    """資金流向更新後，記錄族群資金強度歷史。

    v80：
    - 使用「資料交易日」而不是掃描當天日期。
    - 週六/週日重掃週五資料時，只覆蓋週五那筆，不新增週末假資料。
    """
    trade_date = get_snapshot_trade_date(snapshot)
    scan_time = now_tw().strftime("%Y-%m-%d %H:%M:%S")
    rows = build_sector_flow_strength_table(snapshot, limit=999)
    history = snapshot.get("sector_flow_strength_history") or []
    if not isinstance(history, list):
        history = []

    # 同一交易日重掃時覆蓋，不重複堆疊。
    history = [h for h in history if isinstance(h, dict) and h.get("date") != trade_date]
    for r in rows:
        sector = str(r.get("族群") or "").strip()
        if not sector:
            continue
        history.append({
            "date": trade_date,
            "scan_time": scan_time,
            "族群": sector,
            "資金強度": to_float(r.get("資金強度")),
            "狀態": r.get("狀態"),
            "輪動階段": r.get("輪動階段"),
        })

    # 保留近 keep_days 個交易日；以交易日裁切。
    dates = sorted({str(h.get("date")) for h in history if h.get("date")})[-keep_days:]
    keep = set(dates)
    history = [h for h in history if str(h.get("date")) in keep]
    snapshot["sector_flow_strength_history"] = history
    snapshot["sector_flow_strength_trade_date"] = trade_date
    snapshot["sector_flow_strength_scan_time"] = scan_time
    return snapshot


def sector_flow_trend_note(snapshot: Dict[str, Any], sector: str, current_status: str, current_strength: Optional[float]) -> str:
    """產生族群趨勢標註文字。

    會標註：
    - 連續升溫 3 天
    - 主流第 N 天
    - 強度連續下滑
    - 從偷偷流入轉明面主流
    - 從主流轉鈍化
    """
    history = snapshot.get("sector_flow_strength_history") or []
    sector = str(sector or "").strip()
    if not sector or not isinstance(history, list):
        return "資料累積中"

    rows = [h for h in history if isinstance(h, dict) and str(h.get("族群") or "").strip() == sector]
    rows = sorted(rows, key=lambda x: str(x.get("date") or ""))
    if not rows:
        return "資料累積中"

    # 確保目前狀態參與判斷；如果目前交易日尚未寫入 history，就臨時補一筆。
    trade_date = get_snapshot_trade_date(snapshot)
    if not rows or rows[-1].get("date") != trade_date:
        rows.append({
            "date": trade_date,
            "族群": sector,
            "資金強度": current_strength,
            "狀態": current_status,
        })

    notes = []
    strengths = [to_float(r.get("資金強度")) for r in rows if to_float(r.get("資金強度")) is not None]
    statuses = [str(r.get("狀態") or "") for r in rows]

    if len(strengths) >= 3:
        last3 = strengths[-3:]
        if last3[0] < last3[1] < last3[2]:
            notes.append("連續升溫 3 天")
        elif last3[0] > last3[1] > last3[2]:
            notes.append("強度連續下滑")

    if statuses and statuses[-1] == "明面主流":
        main_days = 0
        for s in reversed(statuses):
            if s == "明面主流":
                main_days += 1
            else:
                break
        if main_days >= 2:
            notes.append(f"主流第 {main_days} 天")

    if len(statuses) >= 2:
        prev, cur = statuses[-2], statuses[-1]
        if prev == "偷偷流入" and cur == "明面主流":
            notes.append("從偷偷流入轉明面主流")
        if prev == "明面主流" and cur == "主流鈍化":
            notes.append("從主流轉鈍化")

    if not notes:
        if len(rows) < 3:
            return "趨勢累積中"
        return "暫無明顯轉折"

    return "｜".join(notes)



def build_sector_flow_strength_table(snapshot: Dict[str, Any], limit: int = 12) -> List[Dict[str, Any]]:
    """族群資金強度排行：把資金流向結果轉成總覽頁可讀的排行。

    這裡只整理既有資金流向 rows，不重新抓資料、不改資金流演算法。
    """
    rows = flow_rows_sorted(snapshot)
    out: List[Dict[str, Any]] = []
    status_weight = {
        "明面主流": 18,
        "偷偷流入": 12,
        "回檔轉強": 10,
        "低基期轉強": 8,
        "主流鈍化": -4,
        "觀察中": 0,
        "退潮轉弱": -18,
    }

    def _stage(status: str, score: Optional[float], d0: Optional[float], d5: Optional[float], d20: Optional[float]) -> str:
        status = str(status or "觀察中")
        if status == "退潮轉弱":
            return "退潮中"
        if status == "主流鈍化":
            return "鈍化中"
        if status == "明面主流":
            if score is not None and score >= 76:
                return "主升中"
            return "擴散中"
        if status == "偷偷流入":
            return "剛升溫"
        if status == "低基期轉強":
            return "低基期轉強"
        if status == "回檔轉強":
            return "回檔再攻"
        return "觀察中"

    def _radar(status: str, stage: str) -> str:
        if status == "退潮轉弱":
            return "資金流入成長股雷達"
        if status == "主流鈍化":
            return "資金流入成長股雷達｜舊主流觀察"
        if status in ["明面主流", "偷偷流入", "低基期轉強", "回檔轉強"]:
            return "資金流入成長股雷達"
        return "資金流向圖｜先觀察"

    def _action(status: str, stage: str) -> str:
        if stage == "主升中":
            return "不追高，等回檔強弱"
        if stage == "擴散中":
            return "優先找回檔轉強個股"
        if stage == "剛升溫":
            return "提前卡位觀察"
        if stage == "低基期轉強":
            return "找基本面驗證的轉機股"
        if stage == "回檔再攻":
            return "看支撐承接與反彈力"
        if stage == "鈍化中":
            return "續抱不追，等新主流"
        if stage == "退潮中":
            return "避開追高，檢查持股"
        return "先觀察"

    for r in rows:
        sector = str(r.get("族群") or "").strip()
        if not sector:
            continue
        status = str(r.get("狀態") or "觀察中")
        score = to_float(r.get("分數"))
        d0 = to_float(r.get("今日均漲跌"))
        d5 = to_float(r.get("5日均漲跌"))
        d20 = to_float(r.get("20日均漲跌"))
        ma20_ratio = to_float(r.get("站上MA20比例"))
        vol_ratio = to_float(r.get("量比"))
        strong = to_float(r.get("強勢股數"))
        weak = to_float(r.get("弱勢股數"))

        strength = score if score is not None else 50.0
        strength += status_weight.get(status, 0)
        if d0 is not None:
            strength += max(-6, min(6, d0 * 1.8))
        if d5 is not None:
            strength += max(-5, min(5, d5 * 0.8))
        if vol_ratio is not None:
            strength += max(-4, min(4, (vol_ratio - 1) * 6))
        if strong is not None and weak is not None:
            strength += max(-5, min(5, (strong - weak) * 1.2))
        strength = max(0, min(100, strength))

        stage = _stage(status, score, d0, d5, d20)
        strength_rounded = round(strength, 1)
        trend_note = sector_flow_trend_note(snapshot, sector, status, strength_rounded)
        out.append({
            "族群": sector,
            "資金強度": strength_rounded,
            "狀態": status,
            "輪動階段": stage,
            "趨勢標註": trend_note,
            "今日均漲跌": "—" if d0 is None else f"{d0:.2f}%",
            "5日均漲跌": "—" if d5 is None else f"{d5:.2f}%",
            "量比": "—" if vol_ratio is None else f"{vol_ratio:.2f}",
            "導向雷達": _radar(status, stage),
            "操作提醒": _action(status, stage),
        })

    out = sorted(out, key=lambda x: to_float(x.get("資金強度")) or 0, reverse=True)
    return out[:limit]


