    st.dataframe(show[compact_cols], use_container_width=True, hide_index=True)

    with st.expander("查看族群完整明細", expanded=False):
        detail_cols = [c for c in ["族群", "資金強度", "狀態", "輪動階段", "趨勢標註", "今日均漲跌", "5日均漲跌", "量比", "導向雷達", "操作提醒"] if c in show.columns]
        st.dataframe(show[detail_cols], use_container_width=True, hide_index=True)
        st.caption("趨勢標註說明：連續升溫3天＝資金強度連續上升；主流第N天＝連續維持明面主流；強度連續下滑＝資金熱度退；偷偷流入轉明面主流＝資金從低調卡位轉成明顯追價；主流轉鈍化＝舊主流開始降溫。")

    inflow = [r for r in rows if r.get("導向雷達") == "資金流入成長股雷達"]
