def update_market(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    statuses = snapshot.get("statuses") or {}
    df, err = fetch_market_kline()
    if df is None:
        statuses["大盤K線"] = status_item("fail", False, err)
        snapshot["statuses"] = statuses
        add_log(snapshot, "更新大盤資料", f"失敗：{err}")
        save_snapshot(snapshot)
        return snapshot

    # Yahoo 日K盤後常延遲；收盤後用 TWSE MIS 補上最新加權收盤，避免看起來沒更新。
    realtime_quote, realtime_err = fetch_market_realtime_quote()
    df, realtime_merged, realtime_note = merge_market_realtime_quote_for_update(df, realtime_quote)

    sr = detect_volume_k_sr_lines(df)
    levels = compute_key_levels(df, sr)
    ma_deduction = compute_ma_deduction(df)
    k_note = f"成功更新至 {normalize_date_str(df['date'].iloc[-1])}"
    twse_merge_note = getattr(df, "attrs", {}).get("twse_merge_note", "")
    if twse_merge_note:
        k_note += f"｜{twse_merge_note}"
    if realtime_merged:
        k_note += f"｜{realtime_note}"
    elif realtime_err:
        k_note += f"｜即時補值未使用：{realtime_err}"
    else:
        k_note += f"｜即時補值未使用：{realtime_note}"
    statuses["大盤K線"] = status_item("ok", True, k_note)
    statuses["支撐壓力"] = status_item("ok", True, f"偵測 {len(sr)} 條大量K支撐壓力")
    statuses["均線扣抵"] = status_item("ok", True, f"{ma_deduction.get('state', '—')}；{ma_deduction.get('summary', '')}")
    verdict = apply_context_to_verdict(compute_market_verdict(df, levels, statuses), snapshot)

    last = df.iloc[-1]
    snapshot["market"] = {
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "kline": df_to_records(df),
        "sr_lines": sr,
        "levels": levels,
        "ma_deduction": ma_deduction,
        "last": {
            "date": normalize_date_str(last.get("date")),
            "close": to_float(last.get("close")),
            "prev_close": to_float(df.iloc[-2].get("close")) if len(df) >= 2 else None,
            "change_points": (
                (to_float(last.get("close")) - to_float(df.iloc[-2].get("close")))
                if len(df) >= 2 and to_float(last.get("close")) is not None and to_float(df.iloc[-2].get("close")) is not None
                else None
            ),
            "change_pct": verdict.get("change_pct"),
        },
        "realtime_quote": realtime_quote,
        "realtime_merged": bool(realtime_merged),
        "realtime_note": realtime_note,
        "verdict": verdict,
    }

    # 盤後資金結構：跟大盤資料一起更新，避免總覽頁缺法人買賣超。
    # fix24:
    # - Streamlit Cloud / 不同裝置偶發 TWSE 抓取失敗時，不要把畫面變成外資/投信/自營商全是「—」。
    # - 若本次抓取失敗，但快照裡有上次成功資料，就沿用上次成功資料並清楚標示。
    _prev_inst = snapshot.get("institutional") or snapshot.get("institutional_last_success") or {}
    inst_data, inst_status = fetch_twse_institutional_amount(lookback_days=14)
    if inst_data:
        snapshot["institutional"] = inst_data
        snapshot["institutional_last_success"] = inst_data
    else:
        _has_prev_inst = any(to_float((_prev_inst or {}).get(k)) is not None for k in ["foreign", "investment_trust", "dealer", "total_inst"])
        if _has_prev_inst:
            snapshot["institutional"] = _prev_inst
            _prev_date = str((_prev_inst or {}).get("date", "") or "")
            _raw_note = inst_status.get("note", "本次法人資料抓取失敗")
            inst_status = status_item("partial", True, f"{_raw_note}｜沿用上次成功法人資料 {_prev_date}")
        else:
            snapshot["institutional"] = {}
    statuses["盤後資金結構"] = inst_status

    # 市場寬度：用上市＋上櫃日行情判斷今天是真的強，還是少數權值撐盤。
    # 注意：這裡只在「更新大盤資料」時執行，不在 App 開啟時自動抓，避免外部請求過多。
    _prev_breadth = snapshot.get("market_breadth") or {}
    breadth_df, breadth_err = fetch_twse_daily_all()
    if breadth_df is not None and not breadth_df.empty:
        price_history = update_market_breadth_price_history(snapshot, breadth_df)
        breadth = compute_market_breadth_from_daily_all(breadth_df, price_history)
        breadth["trade_date"] = get_snapshot_trade_date(snapshot)
        breadth["scan_time"] = now_tw().strftime("%Y-%m-%d %H:%M:%S")
        snapshot["market_breadth"] = breadth
        statuses["市場寬度"] = status_item(
            "ok" if breadth.get("ok") else "partial",
            True,
            f"{breadth.get('verdict', '—')}｜{breadth.get('score', '—')}/100｜樣本 {breadth.get('total', '—')} 檔"
        )
    else:
        if _prev_breadth:
            snapshot["market_breadth"] = _prev_breadth
            statuses["市場寬度"] = status_item("partial", True, f"本次市場寬度抓取失敗，沿用上次資料｜{breadth_err}")
        else:
            snapshot["market_breadth"] = {}
            statuses["市場寬度"] = status_item("fail", False, f"市場寬度抓取失敗：{breadth_err}")

    # 夜盤校正：跟「大盤資料」一起更新；不另外放更新夜盤按鈕，避免總覽流程變複雜。
    try:
        night, night_status = fetch_night_session_snapshot()
        snapshot["night_session"] = night
        statuses["夜盤校正"] = night_status
    except Exception as e:
        statuses["夜盤校正"] = status_item("fail", False, f"夜盤校正失敗：{e}")

    snapshot["statuses"] = statuses
    add_log(
        snapshot,
        "更新大盤資料",
        f"{k_note}｜{inst_status.get('note', '')}｜{statuses.get('市場寬度', {}).get('note', '')}｜{statuses.get('夜盤校正', {}).get('note', '')}"
    )
    save_snapshot(snapshot)
    return snapshot



def update_emerging_sector_tracking(snapshot: Dict[str, Any], discovery: Dict[str, Any]) -> Dict[str, Any]:
    """v165｜今日新冒出族群追蹤。

    把每次「新增-網路搜尋標的」抓到的新冒出族群，寫入 snapshot["emerging_sector_history"]。
    前台依照連續性 / 擴散 / 成長候選數分成三區：
    1. 連續升溫｜可進雷達
    2. 今日新冒出｜先追蹤
    3. 一日異動｜先觀察
    """
    emerging = discovery.get("emerging") or []
    if not emerging:
        discovery["emerging"] = []
        return discovery

    trade_date = get_snapshot_trade_date(snapshot) or now_tw().strftime("%Y-%m-%d")
    history = snapshot.get("emerging_sector_history") or {}
    if not isinstance(history, dict):
        history = {}

    current_sectors = []
    for row in emerging:
        sector = str(row.get("族群") or "").strip()
        if not sector:
            continue
        current_sectors.append(sector)
        records = history.get(sector) or []
        if not isinstance(records, list):
            records = []
        # 同一天只記一筆，避免重複按新增造成連續天數膨脹。
        records = [r for r in records if isinstance(r, dict) and r.get("日期") != trade_date]
        records.append({
            "日期": trade_date,
            "候選檔數": int(to_float(row.get("候選檔數")) or to_float(row.get("今日候選數")) or 0),
            "成交金額(億)": to_float(row.get("成交金額(億)")) or 0,
            "平均漲跌": to_float(row.get("平均漲跌")),
            "成長股候選": int(to_float(row.get("成長股候選")) or 0),
        })
        records = sorted(records, key=lambda x: str(x.get("日期", "")), reverse=True)[:8]
        history[sector] = records

    # 保留最近有出現的族群，避免 history 無限膨脹。
    history = {k: v for k, v in history.items() if isinstance(v, list) and v}
    snapshot["emerging_sector_history"] = history

    enriched = []
    for row in emerging:
        row = dict(row)
        sector = str(row.get("族群") or "").strip()
        records = history.get(sector) or []
        recent_days = len(records)
        count = int(to_float(row.get("候選檔數")) or to_float(row.get("今日候選數")) or 0)
        value = to_float(row.get("成交金額(億)")) or 0
        avg_chg = to_float(row.get("平均漲跌"))
        growth_count = int(to_float(row.get("成長股候選")) or 0)

        if "今日候選數" not in row:
            row["今日候選數"] = count

        if count >= 3:
            spread = "多檔擴散"
        elif count == 2:
            spread = "初步擴散"
        else:
            spread = "單點異動"
        row["主力擴散"] = row.get("主力擴散") or spread
        row["連續天數"] = recent_days

        # v165 三區判定
        # 連續升溫：不是只看今天，至少出現 2 次，且有擴散或成長候選。
        if recent_days >= 2 and (count >= 2 or growth_count >= 1) and value >= 50:
            status = "連續升溫｜可進雷達"
            action = "帶入成長股雷達"
            note = "連續出現，且有資金/候選擴散，可進雷達找個股。"
        # 一日異動：平均漲幅過大但擴散不足，或成長候選不足。
        elif (avg_chg is not None and avg_chg >= 8 and growth_count == 0) or count <= 1:
            status = "一日異動｜先觀察"
            action = "先觀察，不追"
            note = "可能是一日題材或單點拉抬，先看隔日是否延續。"
        else:
            status = "今日新冒出｜先追蹤"
            action = "加入追蹤"
            note = "今日資金有異動，但連續性還不足，先追蹤。"

        row["狀態"] = status
        row["動作"] = action
        row["提醒"] = note
        enriched.append(row)

    # 排序：連續升溫 → 新冒出 → 一日異動；同組再看成長候選、候選數、成交金額。
    rank = {
        "連續升溫｜可進雷達": 0,
        "今日新冒出｜先追蹤": 1,
        "一日異動｜先觀察": 2,
    }
    enriched = sorted(
        enriched,
        key=lambda x: (
            rank.get(x.get("狀態"), 9),
            -(to_float(x.get("連續天數")) or 0),
            -(to_float(x.get("成長股候選")) or 0),
            -(to_float(x.get("今日候選數")) or to_float(x.get("候選檔數")) or 0),
            -(to_float(x.get("成交金額(億)")) or 0),
        ),
    )
    discovery["emerging"] = enriched[:12]
    return discovery


