def update_flow(snapshot: Dict[str, Any], selected_sectors: List[str], max_stocks_each: int) -> Dict[str, Any]:
    flow, status = analyze_sector_flow(selected_sectors, max_stocks_each=max_stocks_each, extra_pool=snapshot.get("discovered_pool") or {})
    trade_date = get_snapshot_trade_date(snapshot)
    scan_time = now_tw().strftime("%Y-%m-%d %H:%M:%S")
