# =========================================================
def _parse_tw_datetime_safe(x: Any) -> Optional[datetime]:
    try:
        s = str(x or "").strip()
        if not s:
            return None
        for fmt in ["%Y-%m-%d %H:%M:%S", "%Y/%m/%d %H:%M:%S", "%Y-%m-%d", "%Y/%m/%d"]:
            try:
                dt = datetime.strptime(s[:19] if " " in fmt else s[:10], fmt)
                return dt.replace(tzinfo=TW_TZ)
            except Exception:
                continue
    except Exception:
        pass
    return None


def _minutes_since(x: Any) -> Optional[float]:
    dt = _parse_tw_datetime_safe(x)
    if dt is None:
        return None
    try:
        return (now_tw() - dt).total_seconds() / 60
    except Exception:
        return None


def _auto_market_refresh_base_time(snapshot: Dict[str, Any]) -> str:
    # 優先看自動更新時間；沒有就看大盤 / 外部 / 夜盤資料時間。
    candidates = [
        snapshot.get("auto_market_refresh_at"),
        (snapshot.get("market") or {}).get("updated_at"),
        (snapshot.get("external") or {}).get("updated_at"),
        (snapshot.get("night_session") or {}).get("updated_at"),
        snapshot.get("updated_at"),
    ]
    for c in candidates:
        if _parse_tw_datetime_safe(c):
            return str(c)
    return ""


def _snapshot_has_txf_quote(snapshot: Dict[str, Any]) -> bool:
    try:
        q = _get_night_session_quote(snapshot)
        if not q:
            return False
        return to_float(q.get("最新")) is not None
    except Exception:
        return False


def should_auto_refresh_market_bundle(snapshot: Dict[str, Any], minutes: int = AUTO_MARKET_REFRESH_MINUTES) -> Tuple[bool, str]:
    base_time = _auto_market_refresh_base_time(snapshot)
    age = _minutes_since(base_time)

    if age is None:
        return True, "尚未有大盤自動更新時間"
    if age >= minutes:
        return True, f"距離上次大盤更新約 {age:.0f} 分鐘"
    # 台指近缺資料時，不要每次 rerun 都重抓；仍依 10 分鐘節奏重試，避免卡住。
    if not _snapshot_has_txf_quote(snapshot) and age >= minutes:
        return True, "台指近尚未取得，且已超過更新間隔"
    return False, f"未滿 {minutes} 分鐘"


def run_auto_market_refresh_if_needed(snapshot: Dict[str, Any], force: bool = False) -> Dict[str, Any]:
    """v206｜每 10 分鐘自動更新：
    - 完整大盤資料
    - 大盤指數簡表 / 台指近
    - 外部風險簡表

    注意：不自動跑新聞、資金流向、掃股雷達，避免太重。
    """
    need, reason = should_auto_refresh_market_bundle(snapshot)
    if not force and not need:
        return snapshot

    statuses = snapshot.get("statuses") or {}
    start_s = now_tw().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with st.spinner(f"自動更新大盤資料中（每 {AUTO_MARKET_REFRESH_MINUTES} 分鐘）：{reason}"):
            snapshot = update_market(snapshot)
            snapshot = update_external(snapshot)
        snapshot["auto_market_refresh_at"] = now_tw().strftime("%Y-%m-%d %H:%M:%S")
        statuses = snapshot.get("statuses") or {}
        statuses["10分鐘自動更新"] = status_item(
            "ok",
            True,
            f"已更新完整大盤 / 台指近 / 外部風險｜{start_s}"
        )
        snapshot["statuses"] = statuses
        add_log(snapshot, "10分鐘自動更新", statuses["10分鐘自動更新"]["note"])
        save_snapshot(snapshot)
    except Exception as e:
        # 失敗也要寫入時間，避免每次 rerun 無限重試卡住。
        snapshot["auto_market_refresh_at"] = now_tw().strftime("%Y-%m-%d %H:%M:%S")
        statuses = snapshot.get("statuses") or {}
        statuses["10分鐘自動更新"] = status_item("partial", False, f"自動更新失敗：{e}")
        snapshot["statuses"] = statuses
        add_log(snapshot, "10分鐘自動更新", f"失敗：{e}")
        save_snapshot(snapshot)
    return snapshot


def render_auto_reload_timer() -> None:
    """前端每 10 分鐘自動 reload 一次。
    Replit / Streamlit 沒開 App 時不會真的背景跑；下次開啟時會由 run_auto_market_refresh_if_needed 補更新。
    """
    try:
        st.components.v1.html(
            f"""
            <script>
            setTimeout(function() {{
                try {{
                    window.parent.location.reload();
                }} catch(e) {{
                    window.location.reload();
                }}
            }}, {AUTO_MARKET_REFRESH_MS});
            </script>
            """,
            height=0,
        )
    except Exception:
        pass



