def _render_flow_sector_dialog_or_panel(snapshot: Dict[str, Any], row: Dict[str, Any]) -> Dict[str, Any]:
    """v118｜優先使用 st.dialog；若版本不支援，退回下方浮層卡片。"""
    sector = str(row.get("族群") or "—")
    status = str(row.get("狀態") or "觀察中")
    mode = _flow_sector_scan_mode(status)
    mode_label = RADAR_MODE_LABELS.get(mode, "資金流入佈局")
    target_page = "資金流入成長股雷達"

    def _dialog_body() -> None:
        nonlocal snapshot
        st.caption(_flow_sector_action_text(status))
        st.markdown("**代表標的（取樣 5 檔）**")
        snapshot = _render_flow_sector_stock_rows(snapshot, row)

        st.markdown("---")
        c1, c2 = st.columns([2.2, 1])
        with c1:
            if st.button(f"掃這個族群｜{mode_label}", use_container_width=True, type="primary", key=f"flow_modal_scan_{_flow_sector_safe_key(sector)}_{mode}"):
                st.session_state["radar_source"] = "手動選擇族群"
                st.session_state["radar_sectors"] = [sector]
                st.session_state["radar_max_each"] = 5
                st.session_state["radar_from_flow_sector"] = {
                    "sector": sector,
                    "status": status,
                    "mode": mode,
                    "mode_label": mode_label,
                    "locked_max_each": 5,
                }
                st.session_state["flow_sector_modal_row"] = sector
                st.session_state["selected_flow_sector"] = sector
                st.session_state["radar_source"] = "手動選擇族群"
                st.session_state["radar_sectors"] = [sector]
                with st.spinner(f"正在掃描 {sector}｜{mode_label}..."):
                    snapshot = update_radar(snapshot, [sector], max_stocks_each=5, radar_mode=mode)
                st.session_state.snapshot = snapshot
                st.session_state["pending_main_nav_page"] = target_page
                st.rerun()
        with c2:
            if st.button("關閉", use_container_width=True, key=f"flow_modal_close_{_flow_sector_safe_key(sector)}"):
                st.session_state.pop("flow_sector_modal_row", None)
                st.rerun()

    if hasattr(st, "dialog"):
        @st.dialog(f"{sector}｜{status}")
        def _sector_dialog():
            _dialog_body()
        _sector_dialog()
    else:
        st.markdown(
            f"""
            <div class="card" style="margin-top:12px;">
              <div class="card-title">{sector}｜{status}</div>
              <div class="subtle">目前 Streamlit 版本不支援真正彈窗，先用下方浮層顯示。</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        _dialog_body()

    return snapshot



