def _flow_group_key_to_name(group_key: str) -> str:
    return {
        "main": "明面主流",
        "stealth": "偷偷流入",
        "lowbase": "低基期轉強",
        "pullback": "回檔轉強",
        "slow": "主流鈍化",
        "outflow": "退潮轉弱",
        "watch": "觀察中",
    }.get(str(group_key), str(group_key))


def _flow_pill_nonce() -> int:
    try:
        return int(st.session_state.get("flow_pill_nonce", 0) or 0)
    except Exception:
        return 0


def _flow_pill_key(group_key: str, nonce: Optional[int] = None) -> str:
    """v182｜每次點選後換 key，強制 pills 前端重掛載。"""
    if nonce is None:
        nonce = _flow_pill_nonce()
    return f"flow_pills_{group_key}_{nonce}"


def _clear_old_flow_pill_widget_keys(current_nonce: Optional[int] = None) -> None:
    """清理舊版 / 舊 nonce 的 pills key。

    不清 flow_pill_nonce / flow_active_group_key 等業務狀態，只清 widget state。
    """
    if current_nonce is None:
        current_nonce = _flow_pill_nonce()
    keep_suffix = f"_{current_nonce}"
    for k in list(st.session_state.keys()):
        if str(k).startswith("flow_pills_") and not str(k).endswith(keep_suffix):
            st.session_state.pop(k, None)
    # 也清掉更舊版本沒有 nonce 的 key
    for g in FLOW_PILL_GROUP_KEYS:
        st.session_state.pop(f"flow_pills_{g}", None)


def _on_flow_group_pill_change(group_key: str) -> None:
    """v182｜多組 pills 最終修正。

    重點：
    1. 讀取當前 nonce 對應的 widget key。
    2. 儲存真正點選的族群到獨立業務狀態。
    3. nonce + 1，下一次 render 強制生成全新 pills widget。
    4. 舊 widget state 不再有機會覆蓋新選擇。
    """
    nonce = _flow_pill_nonce()
    current_key = _flow_pill_key(group_key, nonce)
    picked = st.session_state.get(current_key)
    if isinstance(picked, (list, tuple)):
        picked = picked[0] if picked else None
    picked = str(picked).strip() if picked else None

    if not picked:
        return

    st.session_state["selected_flow_sector"] = picked
    st.session_state["flow_sector_modal_row"] = picked
    st.session_state["flow_active_group_key"] = group_key
    st.session_state["flow_last_clicked_sector"] = picked
    st.session_state["flow_last_clicked_group_key"] = group_key

    # 同步雷達手動族群，避免後面掃描仍吃上一個族群。
    st.session_state["radar_source"] = "手動選擇族群"
    st.session_state["radar_sectors"] = [picked]
    st.session_state.pop("radar_from_flow_sector", None)

    # 核心：下一輪換 key，讓 Streamlit 前端重新掛載 pills，消除殘留 selection。
    st.session_state["flow_pill_nonce"] = nonce + 1


def _render_flow_group_pills(group_key: str, values: List[str]) -> None:
    """v182｜分類內互動族群 chips。

    外觀沿用 st.pills；行為用 nonce key 強制重掛載，解決連點後卡住。
    """
    values = [str(x) for x in (values or []) if str(x).strip()]
    if not values:
        st.markdown('<span class="subtle">目前沒有明確族群</span>', unsafe_allow_html=True)
        return

    nonce = _flow_pill_nonce()
    key = _flow_pill_key(group_key, nonce)

    # 若目前 key 的值不在 values，清掉避免 Streamlit 前端誤會。
    current = st.session_state.get(key)
    if current and current not in values:
        st.session_state.pop(key, None)

    if hasattr(st, "pills"):
        st.pills(
            " ",
            values,
            key=key,
            selection_mode="single",
            label_visibility="collapsed",
            on_change=_on_flow_group_pill_change,
            args=(group_key,),
        )
    else:
        picked = st.selectbox(
            " ",
            [""] + values,
            key=key,
            label_visibility="collapsed",
            format_func=lambda s: "點選族群" if not s else str(s),
        )
        if picked:
            _on_flow_group_pill_change(group_key)



