def render_external_risk(snapshot: Dict[str, Any]) -> None:
    external = snapshot.get("external") or {}
    st.markdown("### 國際風險觀測")
    if not external:
        st.info("尚未更新外部風險。請按上方『更新外部風險』。")
        return

    score = external.get("score")
    verdict = external.get("verdict", "—")
    summary = external.get("summary", "")
    st.markdown(
        f"""
<div class="card">
  <div class="card-title">外部環境：{verdict}</div>
  <div class="big-verdict">{score}/100</div>
  <div class="subtle">{summary}</div>
  <div class="subtle">來源：{external.get('source', '—')}｜更新：{external.get('updated_at', '—')}</div>
</div>
""",
        unsafe_allow_html=True,
    )

    rows = external.get("rows") or []
    if rows:
        df = pd.DataFrame(rows)
        show = df.copy()

        # 手機版欄位減量：
        # 1. 指標 + 代號 → 指標（代號）
        # 2. 漲跌幅 + 解讀 → 漲跌幅／解讀
        if "指標" in show.columns:
            def _indicator_label(r):
                name = str(r.get("指標", "") or "").strip()
                code = str(r.get("代號", "") or "").strip()
                return f"{name}（{code}）" if code else name
            show["指標（代號）"] = show.apply(_indicator_label, axis=1)

        if "最新" in show.columns:
            def _latest_label(r):
                price = fmt_price(r.get("最新"))
                data_time = str(r.get("資料時間", "") or "").strip()
                if data_time:
                    return f"{price}<br/><span style='font-size:0.72em;color:#94a3b8;'>資料 {data_time}</span>"
                return price
            show["最新"] = show.apply(_latest_label, axis=1)

        def _chg_reading_label(r):
            """
            組合漲跌幅與解讀為兩行文字：
            上行顯示百分比，下行顯示解讀，移除分隔符號。
            若沒有解讀，僅顯示漲跌幅。
            返回 HTML 字串以便 <br> 正確渲染。
            """
            chg = fmp(r.get("漲跌幅")) if "漲跌幅" in r.index else "—"
            reading = str(r.get("解讀", "") or "").strip()
            if reading:
                # 將解讀文字字級縮小，方便閱讀
                return f"{chg}<br/><span style='font-size:0.8em;'>{reading}</span>"
            else:
                return chg

        if "漲跌幅" in show.columns or "解讀" in show.columns:
            show["漲跌幅／解讀"] = show.apply(_chg_reading_label, axis=1)

        # 移除「分數影響」欄位，並且移除「分類」欄位（分類顯示大分類文字對新手意義不大），僅顯示對新手友善的重點資訊
        display_cols = [c for c in ["指標（代號）", "最新", "漲跌幅／解讀", "對台股"] if c in show.columns]

        # 手機版顏色判讀：
        # 依該列「漲跌幅」決定整列文字顏色：
        # 上漲＝紅色，下跌＝綠色，平盤＝白色。
        # 台股慣用色系：紅漲、綠跌。
        def _row_color_by_change(x):
            """
            根據漲跌幅回傳文字顏色，使用柔和的配色。
            - 平盤顯示灰白色 (#e5e7eb)
            - 上漲用柔和的紅色 (#f87171)
            - 下跌用柔和的綠色 (#6ee7b7)，較原色(#4ade80)更柔和。
            """
            v = to_float(x)
            if v is None or abs(v) < 0.0001:
                return "#e5e7eb"
            return "#f87171" if v > 0 else "#6ee7b7"

        # 依據漲跌幅及「對台股」判斷，針對不同欄位設定文字顏色。
        # 計算每列漲跌幅對應的顏色：上漲紅、下跌綠、平盤灰。
        price_colors: Dict[int, str] = {}
        if "漲跌幅" in show.columns:
            for idx2, val in show["漲跌幅"].items():
                v = to_float(val)
                if v is None or abs(v) < 1e-4:
                    price_colors[idx2] = "#e5e7eb"
                elif v > 0:
                    price_colors[idx2] = "#f87171"
                else:
                    price_colors[idx2] = "#6ee7b7"
        # 計算每列對台股結論的顏色：偏多紅、偏空綠、中性維持原色。
        verdict_colors: Dict[int, str] = {}
        if "對台股" in show.columns:
            for idx2, val in show["對台股"].items():
                s = str(val or "")
                if any(k in s for k in ["偏多", "助攻", "壓力下降", "壓力降低", "改善", "有利", "降低"]):
                    verdict_colors[idx2] = "#f87171"
                elif any(k in s for k in ["偏空", "壓力上升", "風險壓力", "不利", "升溫", "壓力"]):
                    verdict_colors[idx2] = "#6ee7b7"
                else:
                    verdict_colors[idx2] = "#e5e7eb"
        # 取出要顯示的欄位並複製，建立 HTML 表格。每欄自訂文字顏色及置中顯示。
        display_df = show[display_cols].copy()
        html_parts: List[str] = []
        html_parts.append("<div class='st-dark-table-container'><table class='st-dark-table'>")
        # 表頭
        html_parts.append("<thead><tr>")
        for col in display_df.columns:
            html_parts.append(f"<th style='text-align:center;'>{col}</th>")
        html_parts.append("</tr></thead><tbody>")
        # 資料列
        for idx2, row in display_df.iterrows():
            html_parts.append("<tr>")
            for col, val in row.items():
                cell = "" if (val is None or (isinstance(val, float) and pd.isna(val))) else str(val)
                # 決定本格的文字顏色
                if col in ["漲跌幅／解讀", "漲跌幅"]:
                    ccolor = price_colors.get(idx2, "#e5e7eb")
                elif col == "對台股":
                    ccolor = verdict_colors.get(idx2, "#e5e7eb")
                else:
                    ccolor = "#e5e7eb"
                # 加上 !important 確保自訂顏色覆蓋全域樣式
                html_parts.append(
                    f"<td style='color: {ccolor} !important; font-weight: 700; text-align:center;'>{cell}</td>"
                )
            html_parts.append("</tr>")
        html_parts.append("</tbody></table></div>")
        html_content = "".join(html_parts)
        st.markdown(html_content, unsafe_allow_html=True)

    errors = external.get("errors") or []
    if errors:
        with st.expander("外部資料抓取訊息"):
            for e in errors:
                st.caption(e)


