def trigger_radar_stock_analysis(stock_code: str, stock_name: str) -> None:
    """v167：雷達卡片內的「分析這檔」按鈕。

    不直接修改已建立的 main_nav_page widget，改用 pending_main_nav_page，
    下一輪 render_main_nav() 會在主頁籤建立前套用，避免 StreamlitAPIException。
    """
    code = clean_stock_id(stock_code or "")
