# v194｜掃股雷達進度條＋無標的提示優化
# v193｜掃股雷達目前掃描族群顯示修正
# v192｜掃股雷達展開卡片數值格式修正
def _format_radar_value(x: Any) -> str:
    return str(x if x not in [None, "", "nan", "None"] else "—")


def _format_radar_pct_value(x: Any) -> str:
    """v192｜雷達展開卡片百分比格式：避免出現 3.8493053840989577 這種長小數。"""
    v = to_float(x)
    if v is None:
        return "—"
    return f"{v:+.2f}%"


def _format_radar_price_value(x: Any) -> str:
    v = to_float(x)
    return fmt_price(v) if v is not None else _format_radar_value(x)


def _format_radar_share_value(x: Any) -> str:
    v = to_float(x)
    return fmt_shares(v) if v is not None else _format_radar_value(x)


def _format_radar_ratio_value(x: Any) -> str:
    v = to_float(x)
    if v is None:
        return "—"
    return f"{v:.2f}x"


def _format_radar_score_value(x: Any) -> str:
    v = to_float(x)
    if v is None:
        return _format_radar_value(x)
    return f"{v:.0f}" if abs(v - round(v)) < 0.05 else f"{v:.1f}"


def _radar_is_blank_value(x: Any) -> bool:
    s = str(x if x is not None else "").strip()
    return s == "" or s in {"—", "nan", "None", "null"}


def _radar_unique_list(values: Any, max_items: Optional[int] = None) -> List[str]:
    """保留順序去重，給雷達重複標的合併用。"""
    out: List[str] = []
    for v in values:
        if _radar_is_blank_value(v):
            continue
        # 既有欄位有時已經用 | / 、 串過，這裡只針對族群與提醒做輕量拆分。
        txt = str(v).strip()
        parts = [txt]
        if "、" in txt:
            parts = [x.strip() for x in txt.split("、")]
        for part in parts:
            if part and part not in out:
                out.append(part)
            if max_items and len(out) >= max_items:
                return out
    return out


def _radar_pick_first(values: Any, default: str = "—") -> str:
    for v in values:
        if not _radar_is_blank_value(v):
            return str(v).strip()
    return default


def _radar_pick_best_by_order(values: Any, order: List[str], default: str = "—") -> str:
    vals = _radar_unique_list(values)
    if not vals:
        return default
    for key in order:
        for v in vals:
            if key and key in v:
                return v
    return vals[0]


def merge_duplicate_radar_rows(df: pd.DataFrame) -> pd.DataFrame:
    """同一檔股票只顯示一次，但保留命中族群資訊。

    v53-16：雷達同股可能因多個族群命中重複出現。
    這裡合併成一張卡，不刪掉原因；命中族群清單與命中數會保留下來。
    """
    if df is None or df.empty or "股票" not in df.columns:
        return df

    work = df.copy()
    parsed = work["股票"].apply(parse_radar_stock_label)
    work["__code"] = parsed.apply(lambda x: clean_stock_id(x[0]) if x and x[0] else "")
    work["__name"] = parsed.apply(lambda x: x[1] if x and x[1] else "")
    # 無代號資料無法安全合併，保留原資料。
    if not bool(work["__code"].astype(bool).any()):
        return df

    status_order = [
        "回檔轉強｜承接佳", "回檔轉強｜承接觀察",
        "基本面轉強，法人剛卡位",
        "優先觀察｜資金與基本面同向",
        "偷偷回補｜法人初步卡位",
        "低基期轉強｜確認觀察", "低基期轉強｜早期觀察",
        "強股過熱｜等回檔", "回檔轉強｜已反彈不追",
        "權值/龍頭型｜需估值位置驗證",
        "不列主雷達｜題材待驗證", "不列主雷達｜過熱不追",
        "不列主雷達｜資料待補", "不列主雷達｜心法未過",
        "優質退潮｜等基本面支撐", "短線退潮｜等重新流入",
        "反彈賣點｜不要誤判轉強", "明確退潮｜先避開",
        "高檔鈍化", "明確退潮", "疑似洗盤", "反彈逃命",
        "只觀察", "佈局觀察中",
    ]

    sector_status_order = [
        "明面主流", "偷偷回補", "資金回流", "資金擴散", "退潮", "觀察", "中性",
    ]
    action_order = ["可觀察 / 等回檔", "等回檔", "小倉", "只觀察", "避開", "減碼", "出清"]
    risk_order = ["高", "中高", "中", "低"]

    merged_rows: List[Dict[str, Any]] = []
    for code, g in work.groupby("__code", sort=False):
        if not code:
            # 沒代號的資料逐筆保留。
            for _, row in g.drop(columns=["__code", "__name"], errors="ignore").iterrows():
                d = row.to_dict()
                d["命中族群數"] = 1
                d["命中族群清單"] = _radar_pick_first([d.get("族群")])
                merged_rows.append(d)
            continue

        first = g.iloc[0].to_dict()
        name = _radar_pick_first(g["__name"].tolist(), code)
        sectors = _radar_unique_list(g["族群"].tolist() if "族群" in g.columns else [])
        sector_statuses = _radar_unique_list(g["族群資金狀態"].tolist() if "族群資金狀態" in g.columns else [])
        statuses = _radar_unique_list(g["狀態"].tolist() if "狀態" in g.columns else [])
        positions = _radar_unique_list(g["位置"].tolist() if "位置" in g.columns else [], max_items=3)
        actions = _radar_unique_list(g["操作"].tolist() if "操作" in g.columns else [], max_items=3)
        notes = _radar_unique_list(g["操作提醒"].tolist() if "操作提醒" in g.columns else [], max_items=3)

        row: Dict[str, Any] = {}
        for col in df.columns:
            if col == "股票":
                row[col] = f"{name} {code}".strip()
            elif col == "族群":
                row[col] = "、".join(sectors) if sectors else _radar_pick_first(g.get(col, []))
            elif col == "族群資金狀態":
                row[col] = _radar_pick_best_by_order(sector_statuses, sector_status_order)
            elif col == "狀態":
                row[col] = _radar_pick_best_by_order(statuses, status_order)
            elif col == "位置":
                row[col] = "、".join(positions) if positions else _radar_pick_first(g.get(col, []))
            elif col == "操作":
                row[col] = _radar_pick_best_by_order(actions, action_order)
            elif col == "風險等級":
                row[col] = _radar_pick_best_by_order(g[col].tolist() if col in g.columns else [], risk_order, default="")
            elif col == "操作提醒":
                row[col] = "；".join(notes) if notes else _radar_pick_first(g.get(col, []), "")
            else:
                row[col] = _radar_pick_first(g[col].tolist() if col in g.columns else [], first.get(col, "—"))

        row["命中族群數"] = len(sectors) if sectors else 1
        row["命中族群清單"] = "、".join(sectors) if sectors else _radar_pick_first(g.get("族群", []))
        row["命中狀態清單"] = "、".join(statuses) if statuses else _radar_pick_first(g.get("狀態", []))
        row["跨族群標籤"] = f"跨族群主流｜命中 {len(sectors)}" if len(sectors) >= 2 else ""
        # 多重命中優先，再維持原本掃描順序。
        row["__hit_count_sort"] = len(sectors) if sectors else 1
        merged_rows.append(row)

    out = pd.DataFrame(merged_rows)
    if "__hit_count_sort" in out.columns:
        out = out.sort_values("__hit_count_sort", ascending=False, kind="stable").drop(columns=["__hit_count_sort"], errors="ignore")
    return out.reset_index(drop=True)



def _radar_parse_number_for_sort(value: Any) -> Optional[float]:
    """v146｜雷達排序專用數字解析：可處理 1,234、+5.2%、1.8x、文字混合。"""
    if value is None:
        return None
    if isinstance(value, (int, float, np.integer, np.floating)):
        try:
            if pd.isna(value):
                return None
        except Exception:
            pass
        return float(value)
    s = str(value).replace(",", "").replace("％", "%").strip()
    if s in ["", "—", "-", "--", "nan", "None", "NaN", "null"]:
        return None
    m = re.search(r"[-+]?\d+(?:\.\d+)?", s)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def _radar_has_text(row: Any, *keywords: str) -> bool:
    text = ""
    try:
        if isinstance(row, pd.Series):
            text = "｜".join(str(row.get(c, "")) for c in row.index)
        else:
            text = str(row or "")
    except Exception:
        text = str(row or "")
    return any(k and k in text for k in keywords)


def _radar_hit_score(row: pd.Series) -> float:
    v = _radar_parse_number_for_sort(row.get("命中族群數"))
    return v if v is not None else 1.0


def _radar_basic_score(row: pd.Series) -> float:
    """基本面正向分數：月營收YoY 為主。"""
    yoy = _radar_parse_number_for_sort(row.get("月營收YoY"))
    if yoy is None:
        return 1.0
    if yoy >= 20:
        return 3.0
    if yoy > 0:
        return 2.3
    if yoy > -5:
        return 0.8
    return 0.0


def _radar_inst_score(row: pd.Series, mode: str = "inflow") -> float:
    """法人剛轉買 / 賣壓縮小分數。"""
    inst5 = _radar_parse_number_for_sort(row.get("法人5日"))
    inst20 = _radar_parse_number_for_sort(row.get("法人20日"))

    if inst5 is None and inst20 is None:
        return 1.0

    if mode == "outflow":
        # 退潮頁：不是看誰買最多，而是看賣壓是否縮小。
        if inst5 is not None and inst5 >= 0:
            return 3.0
        if inst5 is not None and inst20 is not None and inst20 < 0 and inst5 > inst20:
            return 2.2
        if inst5 is not None and inst5 > -300:
            return 1.4
        return 0.0

    # 流入頁：法人剛轉買最高；長短買都正向次之。
    if inst5 is not None and inst5 > 0 and (inst20 is None or inst20 <= 0):
        return 3.2
    if inst5 is not None and inst20 is not None and inst5 > 0 and inst20 > 0:
        return 2.8
    if inst5 is not None and inst5 >= 0:
        return 2.0
    if inst5 is not None and inst20 is not None and inst20 < 0 and inst5 > inst20:
        return 1.5
    return 0.0


def _radar_support_or_turn_score(row: pd.Series, mode: str = "inflow") -> float:
    """靠近支撐 / 剛轉強分數。"""
    status = str(row.get("狀態", ""))
    position = str(row.get("位置", ""))
    action = str(row.get("操作", ""))
    note = str(row.get("操作提醒", ""))
    text = "｜".join([status, position, action, note])

    if "承接佳" in text:
        return 3.5
    if "回檔轉強" in text or "觀察支撐" in text or "支撐守住" in text:
        return 3.0
    if "跌破MA20，MA60仍守住" in text:
        return 2.6
    if "站上MA20，仍在MA60下" in text:
        return 2.4
    if "基本面轉強" in text or "法人剛卡位" in text or "偷偷回補" in text:
        return 2.2
    if "低基期轉強" in text:
        return 2.0
    if "站上MA20/MA60" in text:
        return 1.8
    if "跌破MA20/MA60" in text:
        return 0.0
    return 1.0


def _radar_sector_strength_score(row: pd.Series) -> float:
    s = "｜".join([
        str(row.get("族群資金狀態", "")),
        str(row.get("命中族群清單", "")),
        str(row.get("族群", "")),
    ])
    if "明面主流" in s:
        return 5.0
    if "回檔轉強" in s:
        return 4.2
    if "低基期轉強" in s:
        return 4.0
    if "偷偷流入" in s or "偷偷回補" in s:
        return 3.3
    if "主流鈍化" in s:
        return 2.0
    if "觀察" in s:
        return 1.0
    if "退潮" in s:
        return 0.0
    return 1.5


def _radar_not_overheat_score(row: pd.Series) -> float:
    """不過熱分數：越高越適合先看。"""
    status = str(row.get("狀態", ""))
    chg5 = _radar_parse_number_for_sort(row.get("5日漲跌"))
    chg20 = _radar_parse_number_for_sort(row.get("20日漲跌"))
    volr = _radar_parse_number_for_sort(row.get("量比"))

    if "強股過熱" in status or "過熱" in status:
        return 0.0
    if (chg5 is not None and chg5 >= 8) or (chg20 is not None and chg20 >= 20) or (volr is not None and volr >= 2.2):
        return 0.4
    if (chg5 is not None and chg5 >= 5) or (chg20 is not None and chg20 >= 12) or (volr is not None and volr >= 1.8):
        return 1.3
    if chg5 is not None and chg5 < 0 and chg20 is not None and chg20 >= 0:
        return 3.0
    return 2.2


def infer_radar_sort_mode(df: pd.DataFrame, mode: str = "") -> str:
    if mode in ["inflow", "outflow"]:
        return mode
    if df is None or df.empty or "狀態" not in df.columns:
        return "inflow"
    text = "｜".join(df["狀態"].astype(str).head(20).tolist())
    if any(k in text for k in ["優質退潮", "短線退潮", "反彈賣點", "明確退潮", "退潮"]):
        return "outflow"
    return "inflow"


def sort_radar_cards_for_mode(df: pd.DataFrame, mode: str = "") -> pd.DataFrame:
    """v146｜雷達卡片依頁面目的排序。

    退潮頁：
    命中數高 → 明面主流 → 法人賣壓縮小 → 靠近支撐 → 基本面仍正向

    資金流入頁：
    基本面正向 → 法人剛轉買/賣壓縮小 → 靠近支撐或剛轉強 → 命中數高 → 族群資金狀態強 → 不過熱
    """
    if df is None or df.empty:
        return df
    work = df.copy()
    mode = infer_radar_sort_mode(work, mode)

    for col, default in [
        ("命中族群數", 1),
        ("族群資金狀態", ""),
        ("法人5日", None),
        ("法人20日", None),
        ("月營收YoY", None),
        ("位置", ""),
        ("狀態", ""),
        ("5日漲跌", None),
        ("20日漲跌", None),
        ("量比", None),
    ]:
        if col not in work.columns:
            work[col] = default

    work["__priority_score_sort"] = work["優先分數"].apply(_radar_parse_number_for_sort) if "優先分數" in work.columns else None
    work["__hit_sort"] = work.apply(_radar_hit_score, axis=1)
    work["__sector_sort"] = work.apply(_radar_sector_strength_score, axis=1)
    work["__inst_sort"] = work.apply(lambda r: _radar_inst_score(r, mode), axis=1)
    work["__support_sort"] = work.apply(lambda r: _radar_support_or_turn_score(r, mode), axis=1)
    work["__basic_sort"] = work.apply(_radar_basic_score, axis=1)
    work["__heat_sort"] = work.apply(_radar_not_overheat_score, axis=1)

    if "優先分數" in work.columns:
        # v164｜成長股買點雷達以內部優先排序值為第一排序依據。
        # 分數相同時，再看基本面、買點、法人、命中數、族群與過熱扣分。
        sort_cols = ["__priority_score_sort", "__basic_sort", "__support_sort", "__inst_sort", "__hit_sort", "__sector_sort", "__heat_sort"]
    elif mode == "outflow":
        sort_cols = ["__hit_sort", "__sector_sort", "__inst_sort", "__support_sort", "__basic_sort", "__heat_sort"]
    else:
        sort_cols = ["__basic_sort", "__inst_sort", "__support_sort", "__hit_sort", "__sector_sort", "__heat_sort"]

    work = work.sort_values(sort_cols, ascending=[False] * len(sort_cols), kind="stable")
    return work.drop(columns=[c for c in work.columns if c.startswith("__")], errors="ignore").reset_index(drop=True)



def _radar_price_momentum_reading(chg5: Any, chg20: Any) -> str:
    """解讀雷達卡片的股價5日/20日漲跌。

    5日漲跌看短線力道，20日漲跌看波段位置。
    這只做雷達快速篩選，不直接改 Core / Attack / Focus。
    """
    c5 = to_float(chg5)
    c20 = to_float(chg20)
    if c5 is None or c20 is None:
        return "股價動能資料不足，先看法人與基本面。"
    if c5 >= 3 and c20 >= 3:
        return "短線與20日同步轉強，屬資金推升型；仍要看是否接近壓力。"
    if c5 >= 0 and c20 >= 0:
        return "短線與20日偏多，趨勢有支撐；適合觀察回檔品質。"
    if c5 >= 3 and c20 < 0:
        return "短線剛反彈，但20日仍偏弱；屬剛點火，需確認能否站穩。"
    if c5 >= 0 and c20 < 0:
        return "短線止跌轉穩，但波段尚未翻多；先觀察承接。"
    if c5 < 0 and c20 >= 3:
        return "短線回檔，但20日仍偏強；可能是強勢整理或洗盤。"
    if c5 < 0 and c20 >= 0:
        return "短線拉回，波段尚未轉弱；需看是否守支撐。"
    return "5日與20日同步偏弱，股價動能退潮，先保守觀察。"

def render_radar_mobile_cards(df: pd.DataFrame, key_prefix: str = "radar_cards", enable_pending_add: bool = False, sort_mode: str = "", overlap_codes: Optional[set] = None) -> None:
    """手機優先原生短卡。

    v81：可在資金流入成長股雷達每檔旁邊用「＋」加入待分析清單。
    """
    if df is None or df.empty:
        st.caption("目前沒有符合標的。")
        return

    # 同一股票可能由多個族群命中，先合併成一張卡，再依頁面目的排序。
    df = merge_duplicate_radar_rows(df)
    df = sort_radar_cards_for_mode(df, sort_mode)

    # v213｜只有高分標的才排 1、2、3；低分不硬排，避免誤導。
    eligible_rank_counter = 0

    for idx, (_, r) in enumerate(df.iterrows()):
        code, name = parse_radar_stock_label(r.get("股票", ""))
        stock_name = name or str(r.get("股票", "—"))
        stock_code = code or ""

        sector = _format_radar_value(r.get("族群", "—"))
        sector_status = _format_radar_value(r.get("族群資金狀態", "—"))
        price = _format_radar_price_value(r.get("即時股價", "—"))
        status = _format_radar_value(r.get("狀態", "—"))
        position = _format_radar_value(r.get("位置", "—"))
        action = _format_radar_value(r.get("操作", "—"))
        risk = _format_radar_value(r.get("風險等級", ""))
        note = _format_radar_value(r.get("操作提醒", ""))
        inst5_raw = r.get("法人5日", "—")
        inst20_raw = r.get("法人20日", "—")
        yoy_raw = r.get("月營收YoY", "—")
        chg5_raw = r.get("5日漲跌", "—")
        chg20_raw = r.get("20日漲跌", "—")
        eps_yoy_raw = r.get("近1季EPSYoY", "—")
        gp_yoy_raw = r.get("近1季毛利YoY", "—")
        op_yoy_raw = r.get("近1季營益YoY", "—")

        inst5 = _format_radar_share_value(inst5_raw)
        inst20 = _format_radar_share_value(inst20_raw)
        yoy = _format_radar_pct_value(yoy_raw)
        chg5 = _format_radar_pct_value(chg5_raw)
        chg20 = _format_radar_pct_value(chg20_raw)
        volr = _format_radar_ratio_value(r.get("量比", "—"))
        priority_score_raw = to_float(r.get("優先分數"))
        priority_score = _format_radar_score_value(r.get("優先分數", "—"))
        # v213｜前台顯示「優先順序」：
        # >=70 才給排名 1、2、3...
        # 60~69 顯示「觀察」
        # <60 顯示「先略過」
        # 無資料顯示「待資料」
        if priority_score_raw is None:
            priority_order_display = "待資料"
        elif priority_score_raw >= 70:
            eligible_rank_counter += 1
            priority_order_display = str(eligible_rank_counter)
        elif priority_score_raw >= 60:
            priority_order_display = "觀察"
        else:
            priority_order_display = "先略過"
        strategy_tag = _format_radar_value(r.get("策略標籤", ""))
        strategy_score = _format_radar_score_value(r.get("策略分數", ""))
        strategy_reason = _format_radar_value(r.get("策略理由", ""))
        eps_yoy = _format_radar_pct_value(eps_yoy_raw)
        gp_yoy = _format_radar_pct_value(gp_yoy_raw)
        op_yoy = _format_radar_pct_value(op_yoy_raw)
        gm = _format_radar_pct_value(r.get("近1季毛利率", "—"))

        # v205｜卡片內方向性數字上紅下綠；純分數 / 毛利率本身不套色。
        inst5_html = tw_direction_html(inst5_raw, inst5)
        inst20_html = tw_direction_html(inst20_raw, inst20)
        yoy_html = tw_direction_html(yoy_raw, yoy)
        chg5_html = tw_direction_html(chg5_raw, chg5)
        chg20_html = tw_direction_html(chg20_raw, chg20)
        eps_yoy_html = tw_direction_html(eps_yoy_raw, eps_yoy)
        gp_yoy_html = tw_direction_html(gp_yoy_raw, gp_yoy)
        op_yoy_html = tw_direction_html(op_yoy_raw, op_yoy)
        hit_count = int(to_float(r.get("命中族群數")) or 1)
        hit_tag = _format_radar_value(r.get("跨族群標籤", ""))
        hit_list = _format_radar_value(r.get("命中族群清單", sector))

        label_name = f"{stock_name} {stock_code}".strip()
        overlap_codes = overlap_codes or set()
        is_overlap_signal = bool(stock_code and clean_stock_id(stock_code) in overlap_codes)
        display_label_name = f"⚠️ {label_name}" if is_overlap_signal else label_name

        if _radar_is_blank_value(price) and stock_code:
            px0 = get_single_radar_latest_price(stock_code)
            if px0 is not None:
                price = fmt_price(px0)
        summary_parts = [f"{display_label_name}", f"即時 {price}"]
        if priority_order_display:
            summary_parts.append(f"優先順序 {priority_order_display}")
        if strategy_tag and strategy_tag != "—":
            summary_parts.append(_trim_radar_text(strategy_tag, 8))
        if hit_count >= 2:
            summary_parts.append(f"命中 {hit_count}")
        summary_parts.extend([_trim_radar_text(sector_status, 12)])
        summary = "｜".join([p for p in summary_parts if p and p != "—"])
        with st.expander(summary, expanded=False):
            if _radar_is_blank_value(price) and stock_code:
                px = get_single_radar_latest_price(stock_code)
                if px is not None:
                    price = fmt_price(px)

            if hit_count >= 2:
                st.caption(f"{hit_tag or '跨族群命中'}｜{_trim_radar_text(sector_status, 16)}")
            else:
                st.caption(f"{_trim_radar_text(sector, 24)}｜{_trim_radar_text(sector_status, 16)}")
            if is_overlap_signal:
                st.caption("⚠️ 訊號重複")

            st.markdown(f"**{display_label_name}**")
            if hit_count >= 2:
                st.caption(_trim_radar_text(hit_list, 80))
            else:
                st.caption(_trim_radar_text(sector, 80))

            st.markdown(f"即時價：**{price}**")
            if priority_order_display:
                st.markdown(f"優先順序：**{priority_order_display}**")
            if strategy_tag and strategy_tag != "—":
                line = f"策略標籤：**{strategy_tag}**"
                if strategy_score and strategy_score != "—":
                    line += f"｜策略分數：**{strategy_score}**"
                st.markdown(line)
                if strategy_reason and strategy_reason != "—":
                    st.caption(_trim_radar_text(strategy_reason, 88))
            st.markdown("**法人買超：**")
            st.markdown(f"5日：**{inst5_html}** ｜ 法人20日：**{inst20_html}**", unsafe_allow_html=True)

            st.markdown(f"月營收YoY：**{yoy_html}**", unsafe_allow_html=True)
            st.markdown(f"財報接棒：EPS YoY **{eps_yoy_html}**｜毛利 YoY **{gp_yoy_html}**｜營益 YoY **{op_yoy_html}**｜毛利率 **{gm}**", unsafe_allow_html=True)
            st.markdown("**股價漲跌：**")
            st.markdown(f"5日：**{chg5_html}** ｜ 20日漲跌：**{chg20_html}** ｜ 量比：**{volr}**", unsafe_allow_html=True)

            st.markdown("**解讀：**")
            st.caption(_radar_price_momentum_reading(chg5, chg20))

            tag_line = f"{status}｜{position}｜{action}"
            if risk and risk != "—":
                tag_line += f"｜風險 {risk}"
            st.caption(tag_line)
            if note and note != "—":
                st.caption(_trim_radar_text(note, 88))

            st.divider()
            if enable_pending_add:
                already_added = pending_analysis_has_stock(stock_code, st.session_state.get("snapshot", {}))
                c_add, c_analyze = st.columns([1, 4])
                with c_add:
                    if st.button(
                        "✅" if already_added else "＋",
                        key=f"{key_prefix}_pending_{stock_code or idx}_{idx}",
                        use_container_width=True,
                        disabled=already_added,
                        help="加入待分析清單" if not already_added else "已在待分析清單",
                    ):
                        snapshot = st.session_state.get("snapshot", {}) or {}
                        snapshot, added = add_pending_analysis_stock(
                            stock_code,
                            stock_name,
                            sector=hit_list if hit_count >= 2 else sector,
                            source_category=status,
                            source_status=sector_status,
                            source_page="資金流入成長股雷達",
                            snapshot=snapshot,
                        )
                        st.session_state["snapshot"] = snapshot
                        if added:
                            st.success(f"已加入待分析：{label_name}")
                        else:
                            st.info(f"{label_name} 已在待分析清單")
                        st.rerun()
                with c_analyze:
                    if st.button(
                        f"🔍 分析{label_name}",
                        key=f"{key_prefix}_analyze_{stock_code or idx}_{idx}",
                        use_container_width=True,
                    ):
                        trigger_radar_stock_analysis(stock_code, stock_name)
            else:
                if st.button(
                    f"🔍 分析{label_name}",
                    key=f"{key_prefix}_analyze_{stock_code or idx}_{idx}",
                    use_container_width=True,
                ):
                    trigger_radar_stock_analysis(stock_code, stock_name)


