def render_radar_by_sector_expander(show: pd.DataFrame, cols: List[str], title: str, allowed_statuses: Optional[List[str]] = None, enable_pending_add: bool = False, sort_mode: str = "", overlap_codes: Optional[set] = None) -> None:
    if show.empty or "族群" not in show.columns:
        with st.expander(f"{title}（0）", expanded=False):
            st.caption("目前沒有資料。")
        return

    work = show.copy()
    if allowed_statuses and "狀態" in work.columns:
        work = work[work["狀態"].isin(allowed_statuses)].copy()

    sectors = sorted([x for x in work["族群"].dropna().unique() if str(x).strip()])
    with st.expander(f"{title}（{len(sectors)} 組）", expanded=False):
        if "資金流入族群" in title:
            st.caption("改用族群角度看強勢族群，方便從同族群裡找回檔、轉強或承接個股。")
        elif "資金退潮族群" in title:
            st.caption("用族群角度追蹤資金退潮：看哪些族群只是整理、哪些正在轉弱、哪些反彈不該追。這區是輔助判斷，不直接等於買賣訊號。")
        if work.empty:
            st.caption("目前沒有符合標的。")
            return
        # Enumerate sectors to ensure each quick-analyze key is unique even if the sanitized
        # sector name would be identical (e.g. Chinese names become underscores).
        for idx, sector in enumerate(sectors):
            st.markdown(f"##### {sector}")
            sdf = work[work["族群"] == sector]
            display_cols = [c for c in cols if c in sdf.columns]
            render_radar_mobile_cards(sdf[display_cols], key_prefix=f"sector_{idx}", enable_pending_add=enable_pending_add, sort_mode=sort_mode, overlap_codes=overlap_codes)



def _overlap_stock_key(row: pd.Series) -> Tuple[str, str]:
    code, name = parse_radar_stock_label(row.get("股票", ""))
    return clean_stock_id(code or ""), name or str(row.get("股票", "")).strip()


def _overlap_short_status(status: Any) -> str:
    s = str(status or "—").strip()
    s = normalize_outflow_status(s)
    # 手機短卡用：保留關鍵，不讓標題太長
    replacements = {
        "回檔轉強｜承接佳": "回檔轉強",
        "回檔轉強｜承接觀察": "回檔轉強",
        "基本面轉強，法人剛卡位": "基本面轉強",
        "偷偷回補｜法人初步卡位": "偷偷回補",
        "低基期轉強｜確認觀察": "低基期轉強",
        "低基期轉強｜早期觀察": "低基期轉強",
        "優先觀察｜資金與基本面同向": "優先觀察",
        "強股過熱｜等回檔": "強股過熱",
        "回檔轉強｜已反彈不追": "已反彈不追",
        "優質退潮｜等基本面支撐": "優質退潮",
        "短線退潮｜等重新流入": "短線退潮",
        "反彈賣點｜不要誤判轉強": "反彈賣點",
        "明確退潮｜先避開": "明確退潮",
    }
    return replacements.get(s, s)


def interpret_overlap_combo(inflow_status: Any, outflow_status: Any) -> Tuple[str, str, str, int]:
    """v147｜流入類別 × 退潮類別 的組合解讀。

    回傳：重判結果、簡單解讀、操作口令、排序權重
    """
    inflow = str(inflow_status or "").strip()
    outflow = normalize_outflow_status(outflow_status)

    if "反彈賣點" in outflow:
        return (
            "反彈賣點優先",
            "流入端有訊號，但退潮端已把它歸到反彈賣點；這種最容易把弱勢反彈誤判成轉強。",
            "反彈先看減碼 / 不追，等真正重新流入。",
            40,
        )

    if "明確退潮" in outflow:
        if any(k in inflow for k in ["低基期轉強", "偷偷回補", "基本面轉強"]):
            return (
                "退潮優先｜轉強先暫停",
                "有早期轉強味道，但短線退潮壓力更明確；此時流入訊號先當背景，不當買點。",
                "先避開，不買；等它離開明確退潮並重新流入。",
                30,
            )
        return (
            "退潮優先｜先避開",
            "同時有流入訊號與明確退潮時，先尊重退潮訊號，避免把反彈或短線承接誤判成主升。",
            "先避開，等趨勢與法人賣壓修復。",
            31,
        )

    if "短線退潮" in outflow:
        if any(k in inflow for k in ["回檔轉強", "基本面轉強", "優先觀察", "低基期轉強"]):
            return (
                "等重新流入",
                "基本面或轉強條件仍在，但短線買盤降溫；這類不是直接買，而是等重新回到流入頁確認。",
                "列觀察，等站回支撐、法人賣壓縮小。",
                20,
            )
        return (
            "短線衝突｜先觀察",
            "流入端有訊號，但退潮端顯示短線買盤還沒回來；先看支撐與量能是否恢復。",
            "不追，等下一次重新流入。",
            21,
        )

    if "優質退潮" in outflow:
        if any(k in inflow for k in ["回檔轉強", "基本面轉強", "優先觀察"]):
            return (
                "偏正面｜等支撐確認",
                "這是比較有價值的衝突：基本面或資金條件還在，只是短線退潮；重點看回檔支撐能不能守住。",
                "等基本面支撐 / 技術支撐確認，不追高。",
                10,
            )
        if "強股過熱" in inflow:
            return (
                "強股降溫｜等回檔",
                "強勢股短線降溫進入退潮觀察，不是壞事；但現在不是追價點。",
                "等回支撐與承接，再重新評估。",
                11,
            )
        return (
            "觀察型衝突｜等支撐",
            "退潮端尚未否定基本面，但流入端也還不是乾淨買點；需要看支撐與法人賣壓。",
            "只觀察，等支撐確認。",
            12,
        )

    return (
        "訊號重複｜需重判",
        "同時出現在流入與退潮，代表訊號不乾淨；不要只看單一頁下結論。",
        "回到法醫判斷，確認支撐、法人與基本面。",
        50,
    )


def build_signal_overlap_df(snapshot: Dict[str, Any]) -> pd.DataFrame:
    """v147｜建立「訊號重複」清單：流入雷達 ∩ 退潮雷達。

    依股票代號交集，再保留流入類別、退潮類別、組合解讀與操作口令。
    """
    inflow_radar = get_radar_data_for_mode(snapshot, "inflow")
    outflow_radar = get_radar_data_for_mode(snapshot, "outflow")

    inflow = prepare_radar_display_df(inflow_radar, snapshot=snapshot)
    outflow = prepare_radar_display_df(outflow_radar, snapshot=snapshot)

    if inflow is None or outflow is None or inflow.empty or outflow.empty:
        return pd.DataFrame()

    inflow = merge_duplicate_radar_rows(inflow)
    outflow = merge_duplicate_radar_rows(outflow)

    inflow_map: Dict[str, pd.Series] = {}
    outflow_map: Dict[str, pd.Series] = {}

    for _, row in inflow.iterrows():
        code, name = _overlap_stock_key(row)
        if code:
            inflow_map[code] = row

    for _, row in outflow.iterrows():
        code, name = _overlap_stock_key(row)
        if code:
            outflow_map[code] = row

    common_codes = [code for code in inflow_map.keys() if code in outflow_map]
    rows: List[Dict[str, Any]] = []

    for code in common_codes:
        ir = inflow_map[code]
        orow = outflow_map[code]
        _code, name = _overlap_stock_key(ir)
        if not name:
            _code2, name = _overlap_stock_key(orow)

        inflow_status = str(ir.get("狀態", "—"))
        outflow_status = normalize_outflow_status(orow.get("狀態", "—"))
        combo_title = f"{_overlap_short_status(inflow_status)} × {_overlap_short_status(outflow_status)}"
        verdict, explanation, action, rank = interpret_overlap_combo(inflow_status, outflow_status)

        price = ir.get("即時股價", "—")
        if str(price) in ["", "—", "nan", "None"]:
            price = orow.get("即時股價", "—")

        rows.append({
            "股票": f"{name} {code}".strip(),
            "代號": code,
            "名稱": name,
            "即時股價": price,
            "流入類別": inflow_status,
            "退潮類別": outflow_status,
            "組合": combo_title,
            "重判結果": verdict,
            "簡單解讀": explanation,
            "操作口令": action,
            "流入族群": ir.get("族群", "—"),
            "退潮族群": orow.get("族群", "—"),
            "流入族群狀態": ir.get("族群資金狀態", "—"),
            "退潮族群狀態": orow.get("族群資金狀態", "—"),
            "流入位置": ir.get("位置", "—"),
            "退潮位置": orow.get("位置", "—"),
            "法人5日": ir.get("法人5日", orow.get("法人5日", "—")),
            "法人20日": ir.get("法人20日", orow.get("法人20日", "—")),
            "月營收YoY": ir.get("月營收YoY", orow.get("月營收YoY", "—")),
            "_rank": rank,
            "_hit": max(_radar_hit_score(ir), _radar_hit_score(orow)),
        })

    if not rows:
        return pd.DataFrame()

    df = pd.DataFrame(rows)
    df = df.sort_values(["_rank", "_hit"], ascending=[True, False], kind="stable").drop(columns=["_rank", "_hit"], errors="ignore")
    return df.reset_index(drop=True)



def overlap_strategy_bucket(verdict: Any, inflow_status: Any = "", outflow_status: Any = "") -> Tuple[str, str, str, int]:
    """v154｜訊號重複頁改為三大策略分區。

    三大策略：
    1. 第一區找機會｜等支撐 / 等重新流入
    2. 第二區防誤追｜反彈是賣點，不是轉強
    3. 第三區避風險｜轉空轉弱，先避開

    保證一檔股票只會進一個策略分區：
    反彈賣點優先歸第二區；明確退潮/退潮優先歸第三區；其他可觀察轉折歸第一區。
    """
    v = str(verdict or "")
    inflow = str(inflow_status or "")
    outflow = normalize_outflow_status(outflow_status)

    # 第二區：最容易誤追，反彈不是轉強
    if "反彈賣點" in outflow or "反彈賣點" in v:
        return (
            "第二區防誤追｜反彈是賣點，不是轉強",
            "防誤追",
            "這區是防誤追：股價可能有彈，但反彈不等於轉強。先把它當成減碼或觀察點，不追買。",
            20,
        )

    # 第三區：明確轉弱 / 退潮優先
    if any(k in outflow for k in ["明確退潮"]) or any(k in v for k in ["退潮優先", "先避開"]):
        return (
            "第三區避風險｜轉空轉弱，先避開",
            "避風險",
            "這區是風險池：退潮、法人賣壓或技術轉弱較明確。不是等便宜撿，先避開，等未來重新站回趨勢。",
            30,
        )

    # 第一區：回流前兆 / 正常降溫 / 優質退潮 / 短線退潮
    return (
        "第一區找機會｜等支撐 / 等重新流入",
        "找機會",
        "這區是機會池：流入與退潮同時出現，代表狀態正在轉折。等支撐、等基本面支撐區，或等它重新回到乾淨流入。",
        10,
    )


def overlap_strategy_rank(strategy: str) -> int:
    order = {
        "第一區找機會｜等支撐 / 等重新流入": 0,
        "第二區防誤追｜反彈是賣點，不是轉強": 1,
        "第三區避風險｜轉空轉弱，先避開": 2,
    }
    return order.get(str(strategy), 9)


def dedupe_signal_overlap_df(df: pd.DataFrame) -> pd.DataFrame:
    """v154｜訊號重複頁安全去重，避免同一股票出現在不同策略分區。

    理論上 build_signal_overlap_df 已經一檔一筆；
    這裡再做一次保險，若同代號重複，依策略風險優先：
    第二區防誤追 > 第三區避風險 > 第一區找機會。
    """
    if df is None or df.empty or "代號" not in df.columns:
        return df

    work = df.copy()

    def _priority(row: pd.Series) -> int:
        strategy = str(row.get("策略分區", ""))
        # 若真的撞到同代號，先保留最需要提醒的
        if "防誤追" in strategy:
            return 0
        if "避風險" in strategy:
            return 1
        return 2

    work["_dedupe_priority"] = work.apply(_priority, axis=1)
    work = work.sort_values(["代號", "_dedupe_priority"], ascending=[True, True], kind="stable")
    work = work.drop_duplicates(subset=["代號"], keep="first")
    return work.drop(columns=["_dedupe_priority"], errors="ignore").reset_index(drop=True)


def render_signal_overlap_cards(df: pd.DataFrame) -> None:
    """v154｜訊號重複卡片：三大策略分區，小白版。"""
    if df is None or df.empty:
        st.info("目前沒有同時出現在流入 / 退潮的重複訊號。")
        return

    work = df.copy()
    strategy_rows = []
    for _, r in work.iterrows():
        strategy, short_label, strategy_desc, rank = overlap_strategy_bucket(
            r.get("重判結果", ""),
            r.get("流入類別", ""),
            r.get("退潮類別", ""),
        )
        strategy_rows.append((strategy, short_label, strategy_desc, rank))

    work["策略分區"] = [x[0] for x in strategy_rows]
    work["策略標籤"] = [x[1] for x in strategy_rows]
    work["策略說明"] = [x[2] for x in strategy_rows]
    work["_strategy_rank"] = [x[3] for x in strategy_rows]

    # 安全去重：同一檔股票只能在一個策略分區出現
    work = dedupe_signal_overlap_df(work)

    if "_strategy_rank" not in work.columns:
        work["_strategy_rank"] = work["策略分區"].apply(overlap_strategy_rank)

    work = work.sort_values(["_strategy_rank"], ascending=[True], kind="stable").drop(columns=["_strategy_rank"], errors="ignore")

    strategy_order = [
        "第一區找機會｜等支撐 / 等重新流入",
        "第二區防誤追｜反彈是賣點，不是轉強",
        "第三區避風險｜轉空轉弱，先避開",
    ]

    for strategy in strategy_order:
        strategy_df = work[work["策略分區"].astype(str) == strategy].copy()
        if strategy_df.empty:
            continue

        strategy_desc = str(strategy_df["策略說明"].iloc[0] or "")
        with st.expander(f"{strategy}（{len(strategy_df)}）", expanded=False):
            st.caption(strategy_desc)

            combo_order = list(dict.fromkeys(strategy_df["組合"].astype(str).tolist()))
            for combo_idx, combo in enumerate(combo_order):
                part = strategy_df[strategy_df["組合"].astype(str) == combo].copy()
                if part.empty:
                    continue

                first = part.iloc[0]
                verdict = str(first.get("重判結果", "需重判"))
                explanation = str(first.get("簡單解讀", ""))
                action = str(first.get("操作口令", ""))

                with st.expander(f"{combo}（{len(part)}）", expanded=False):
                    st.caption(f"重判：{verdict}")
                    if explanation:
                        st.caption(explanation)
                    if action:
                        st.caption(f"操作口令：{action}")

                    # 再保險：同組內也依代號去重
                    if "代號" in part.columns:
                        part = part.drop_duplicates(subset=["代號"], keep="first")

                    for idx, (_, r) in enumerate(part.iterrows()):
                        stock = str(r.get("股票", "—"))
                        price = str(r.get("即時股價", "—"))
                        inflow_s = _overlap_short_status(r.get("流入類別", "—"))
                        outflow_s = _overlap_short_status(r.get("退潮類別", "—"))
                        with st.expander(f"{stock}｜即時 {price}｜{inflow_s} × {outflow_s}", expanded=False):
                            st.markdown(f"**策略分區：** {r.get('策略分區', '—')}")
                            st.markdown(f"**流入類別：** {r.get('流入類別', '—')}")
                            st.markdown(f"**退潮類別：** {r.get('退潮類別', '—')}")
                            st.markdown(f"**重判結果：** {r.get('重判結果', '—')}")
                            st.caption(str(r.get("簡單解讀", "")))
                            st.markdown(f"**操作口令：** {r.get('操作口令', '—')}")
                            st.markdown("---")
                            st.caption(f"流入族群：{r.get('流入族群', '—')}｜{r.get('流入族群狀態', '—')}")
                            st.caption(f"退潮族群：{r.get('退潮族群', '—')}｜{r.get('退潮族群狀態', '—')}")
                            st.caption(f"法人5日：{r.get('法人5日', '—')}｜法人20日：{r.get('法人20日', '—')}｜月營收YoY：{r.get('月營收YoY', '—')}")



def render_signal_overlap_page(snapshot: Dict[str, Any]) -> None:
    """v147｜掃股雷達第三分頁：訊號重複。

    用「流入類別 × 退潮類別」排列組合，判斷同一檔股票的訊號衝突意義。
    """
    st.markdown("### ⚠️ 族群個股雷達｜訊號重複重判")
    st.caption("流入看機會，退潮看風險，重複看轉折。這頁把重複訊號統整成三大策略：第一區找機會、第二區防誤追、第三區避風險。")

    inflow_radar = get_radar_data_for_mode(snapshot, "inflow")
    outflow_radar = get_radar_data_for_mode(snapshot, "outflow")
    inflow_rows = inflow_radar.get("rows") or []
    outflow_rows = outflow_radar.get("rows") or []

    if not inflow_rows or not outflow_rows:
        st.info("需要先各自掃過『資金流入成長股雷達』與『資金流入成長股雷達』，這頁才有辦法比對重複訊號。")
        return

    df = build_signal_overlap_df(snapshot)
    if df.empty:
        st.success("目前沒有同時出現在流入 / 退潮的標的，訊號相對乾淨。")
        return

    before_count = len(df)
    df, overheat_overlap_removed = filter_overheat_radar_rows(df)
    if df.empty:
        st.success("重複訊號扣除過熱 / 不追高標的後，目前沒有需要列出的標的。")
        return

    st.caption(f"目前重複訊號：{len(df)} 檔｜已從流入/退潮分流，並依三大策略分區。")
    if overheat_overlap_removed:
        st.caption(f"已排除 {overheat_overlap_removed} 檔過熱 / 不追高標的；過熱股先不列入三大策略清單。")
    render_signal_overlap_cards(df)




def normalize_inflow_strategy_rows(df: pd.DataFrame) -> Tuple[pd.DataFrame, int]:
    """v156｜資金流入成長股雷達簡化成兩大策略。

    只保留符合使用者心法的流入標的：
    1. 買點接近｜等支撐切入
    2. 盤整重估｜等重新定價

    過熱、不追高、心法未過、資料不足、只適合回法醫驗證但買點不近的標的，
    不在資金流入主畫面列出。
    """
    if df is None or df.empty or "狀態" not in df.columns:
        return df, 0

    buy_point_statuses = {
        "回檔轉強｜承接佳",
        "回檔轉強｜承接觀察",
        "回檔轉強觀察",
        "基本面轉強，法人剛卡位",
    }

    rerating_statuses = {
        "偷偷回補｜法人初步卡位",
        "偷偷回補觀察",
        "低基期轉強｜確認觀察",
        "低基期轉強｜早期觀察",
        "低基期轉強觀察",
        "優先觀察｜資金與基本面同向",
        "優先佈局觀察",
    }

    work = df.copy()
    if "原始狀態" not in work.columns:
        work["原始狀態"] = work["狀態"]

    keep_rows = []
    removed_codes = set()

    for idx, row in work.iterrows():
        status = str(row.get("狀態", "")).strip()
        new_status = ""

        if status in buy_point_statuses:
            new_status = "買點接近｜等支撐切入"
        elif status in rerating_statuses:
            new_status = "盤整重估｜等重新定價"
        else:
            code, _name = parse_radar_stock_label(row.get("股票", ""))
            code = clean_stock_id(code or "")
            if code:
                removed_codes.add(code)
            continue

        row = row.copy()
        row["狀態"] = new_status

        # 操作口令也一起變小白版，不改底層資料，只改雷達前台顯示。
        old_action = str(row.get("操作", "") or "")
        if new_status == "買點接近｜等支撐切入":
            row["操作"] = "等支撐確認 / 可丟法醫"
            if not old_action or old_action in ["—", "-"]:
                row["操作提醒"] = "資金有進，買點較接近；等支撐不破或法人賣壓縮小，再進個股法醫確認。"
        elif new_status == "盤整重估｜等重新定價":
            row["操作"] = "盤整觀察 / 等重估"
            if not old_action or old_action in ["—", "-"]:
                row["操作提醒"] = "股價尚未過度反應，若基本面持續驗證，後續有重新定價機會。"

        keep_rows.append(row)

    if not keep_rows:
        return work.iloc[0:0].copy(), len(removed_codes)

    out = pd.DataFrame(keep_rows).reset_index(drop=True)
    return out, len(removed_codes)


def normalize_outflow_strategy_rows(df: pd.DataFrame) -> Tuple[pd.DataFrame, int]:
    """v158｜資金流入成長股雷達四大策略 + 強勢股防誤殺。

    核心修正：
    - 法人賣超不等於出貨賣壓。
    - 若個股仍屬明面主流、20日仍偏強、沒有跌破關鍵支撐，不得判為「真的轉空轉弱」。
    - 強勢股高檔調節最多歸為「盤整重估｜重新定價」或「買點接近｜等待支撐切入」。
    - 若只是高檔強勢整理、離支撐太遠且沒有買點，不列入「真的轉空轉弱」。
    """
    if df is None or df.empty or "狀態" not in df.columns:
        return df, 0

    work = df.copy()
    if "原始狀態" not in work.columns:
        work["原始狀態"] = work["狀態"]

    keep_rows = []
    removed_codes = set()

    def _text(row: pd.Series) -> str:
        watch_cols = [
            "狀態", "位置", "操作", "操作提醒", "族群資金狀態",
            "月營收YoY", "5日漲跌", "20日漲跌", "法人5日", "法人20日",
        ]
        return "｜".join(str(row.get(c, "")) for c in watch_cols if c in row.index)

    def _num(row: pd.Series, col: str) -> Optional[float]:
        try:
            return to_float(row.get(col))
        except Exception:
            return None

    def _drop(row: pd.Series) -> None:
        code, _name = parse_radar_stock_label(row.get("股票", ""))
        code = clean_stock_id(code or "")
        if code:
            removed_codes.add(code)

    for idx, row in work.iterrows():
        raw_status = normalize_outflow_status(row.get("狀態", ""))
        text = _text(row)
        sector_status = str(row.get("族群資金狀態", "") or "")

        chg5 = _num(row, "5日漲跌")
        chg20 = _num(row, "20日漲跌")
        yoy = _num(row, "月營收YoY")
        inst5 = _num(row, "法人5日")
        inst20 = _num(row, "法人20日")

        new_status = ""

        is_mainstream = ("明面主流" in sector_status) or ("主流" in sector_status and "退潮" not in sector_status)
        is_sector_weak = any(k in sector_status for k in ["退潮轉弱", "退潮", "轉弱"])
        trend_still_ok = (
            (chg20 is not None and chg20 >= 0)
            or any(k in text for k in ["仍站上", "MA20之上", "MA60仍守住", "支撐守住", "未跌破"])
        )
        support_near_or_hold = any(k in text for k in ["支撐", "MA60仍守住", "靠近", "回檔", "守住", "未跌破"])
        hard_break = any(k in text for k in ["跌破MA20/MA60", "跌破 MA20", "跌破 MA60", "跌破關鍵支撐", "同步偏弱", "結構轉弱", "趨勢轉弱"])
        inst_heavy_sell = (inst5 is not None and inst5 < 0) and (inst20 is not None and inst20 < 0)
        basic_weak = yoy is not None and yoy <= 0
        price_weak = (chg5 is not None and chg5 < 0) and (chg20 is not None and chg20 < 0)

        # v158 防誤殺：明面主流 + 趨勢未破，不准判「真的轉空轉弱」
        strong_not_broken = is_mainstream and trend_still_ok and not hard_break and not (basic_weak and inst_heavy_sell and price_weak)

        # 3. 反彈不買：反彈賣點優先處理，避免小白誤追。
        if "反彈賣點" in raw_status or "反彈逃命" in raw_status or ("反彈" in text and ("波段仍弱" in text or "趨勢仍弱" in text)):
            new_status = "反彈不買"

        # 4. 真的轉空轉弱：必須有硬轉弱證據，不能只因法人調節就判死。
        elif (
            ("明確退潮" in raw_status or is_sector_weak or hard_break)
            and not strong_not_broken
            and (
                hard_break
                or (inst_heavy_sell and price_weak)
                or (inst_heavy_sell and basic_weak)
                or (is_sector_weak and price_weak)
            )
        ):
            new_status = "真的轉空轉弱"

        # 強勢主流 / 趨勢未破但被掃進退潮：改為健康調節，不放轉弱。
        elif strong_not_broken:
            if support_near_or_hold:
                new_status = "買點接近｜等待支撐切入"
            else:
                new_status = "盤整重估｜重新定價"

        # 1. 買點接近：優質退潮或短線退潮，但接近支撐 / 支撐未破。
        elif "優質退潮" in raw_status or "疑似洗盤" in raw_status:
            if support_near_or_hold:
                new_status = "買點接近｜等待支撐切入"
            else:
                new_status = "盤整重估｜重新定價"

        # 2. 盤整重估：短線退潮但未確認轉弱，等待重新定價。
        elif "短線退潮" in raw_status or "資金短退" in raw_status or "退潮觀察" in raw_status:
            if support_near_or_hold:
                new_status = "買點接近｜等待支撐切入"
            else:
                new_status = "盤整重估｜重新定價"

        # 暫無明確退潮 / 其他雜訊不列入退潮主畫面。
        else:
            _drop(row)
            continue

        row = row.copy()
        row["狀態"] = new_status

        # 小白版操作口令
        if new_status == "買點接近｜等待支撐切入":
            row["操作"] = "等支撐確認 / 可丟法醫"
            row["操作提醒"] = "法人健康調節不等於出貨；若支撐守住、賣壓縮小，可回到法醫確認買點。"
        elif new_status == "盤整重估｜重新定價":
            row["操作"] = "盤整觀察 / 等重新定價"
            row["操作提醒"] = "短線資金調節但趨勢未必壞；等營收、法人或技術重新流入確認。"
        elif new_status == "反彈不買":
            row["操作"] = "反彈不追 / 持有降風險"
            row["操作提醒"] = "股價有彈不代表轉強；空手不追，持有者可趁反彈降低風險。"
        elif new_status == "真的轉空轉弱":
            row["操作"] = "先避開 / 不接刀"
            row["操作提醒"] = "資金、法人、技術或基本面轉弱較明確；不是等便宜撿，先等未來重新站回趨勢。"

        keep_rows.append(row)

    if not keep_rows:
        return work.iloc[0:0].copy(), len(removed_codes)

    out = pd.DataFrame(keep_rows).reset_index(drop=True)
    return out, len(removed_codes)



def is_overheat_radar_row(row: pd.Series) -> bool:
    """v155｜過熱標的先不列出。

    目的：
    - 不把「強股過熱 / 已反彈不追 / 過熱不追」放在流入候選或重複策略裡。
    - 過熱股不是不好，但不符合目前「等支撐 / 不追高」心法。
    """
    if row is None:
        return False

    watch_cols = [
        "狀態", "流入類別", "退潮類別", "組合", "重判結果", "簡單解讀", "操作口令",
        "位置", "操作", "操作提醒",
    ]
    text = "｜".join(str(row.get(c, "")) for c in watch_cols if c in row.index)

    hot_keywords = [
        "強股過熱",
        "過熱",
        "已反彈不追",
        "過熱不追",
        "不追高",
    ]
    return any(k in text for k in hot_keywords)


def filter_overheat_radar_rows(df: pd.DataFrame) -> Tuple[pd.DataFrame, int]:
    """v155｜把過熱股從畫面列表先拿掉。"""
    if df is None or df.empty:
        return df, 0
    work = df.copy()
    keep_mask = []
    removed_codes = set()
    for _, row in work.iterrows():
        is_hot = is_overheat_radar_row(row)
        keep_mask.append(not is_hot)
        if is_hot and "股票" in row.index:
            code, _name = parse_radar_stock_label(row.get("股票", ""))
            code = clean_stock_id(code or "")
            if code:
                removed_codes.add(code)

    filtered = work[pd.Series(keep_mask, index=work.index)].copy()
    return filtered.reset_index(drop=True), len(removed_codes)


def filter_out_signal_overlap_rows(df: pd.DataFrame, overlap_codes: set) -> Tuple[pd.DataFrame, int]:
    """v153｜流入/退潮頁分流重複訊號。

    只要同一股票同時出現在流入與退潮，就從原本流入/退潮頁移除，
    集中到「重複」頁做狀態轉換判讀。
    """
    if df is None or df.empty or not overlap_codes or "股票" not in df.columns:
        return df, 0

    work = df.copy()
    before_codes = set()
    keep_mask = []
    for _, row in work.iterrows():
        code, _name = parse_radar_stock_label(row.get("股票", ""))
        code = clean_stock_id(code or "")
        if code:
            before_codes.add(code)
        keep_mask.append(not (code and code in overlap_codes))

    filtered = work[pd.Series(keep_mask, index=work.index)].copy()
    after_codes = set()
    if not filtered.empty and "股票" in filtered.columns:
        for _, row in filtered.iterrows():
            code, _name = parse_radar_stock_label(row.get("股票", ""))
            code = clean_stock_id(code or "")
            if code:
                after_codes.add(code)

    removed_count = len(before_codes - after_codes)
    return filtered.reset_index(drop=True), removed_count


def get_signal_overlap_code_set(snapshot: Dict[str, Any]) -> set:
    """v150｜取得同時出現在流入/退潮雷達的股票代號集合。

    用途：
    - 找出要從原本「流入」「退潮」頁分流出去的重複訊號
    - 重複標的集中到「重複」頁做狀態轉換判讀

    v150 修正：
    - v149 新增偏多/偏空分組時，漏帶此 helper，造成 NameError。
    """
    try:
        df = build_signal_overlap_df(snapshot)
        if df is None or df.empty or "代號" not in df.columns:
            return set()
        return {clean_stock_id(x) for x in df["代號"].dropna().tolist() if clean_stock_id(x)}
    except Exception:
        return set()


def classify_revenue_growth_stage2_from_row(row: pd.Series) -> Dict[str, Any]:
    """v172｜營收成長二段買點策略。

    來源：使用者提供的「月營收強勢二段布局」與「成長加速，沿20/60均買」條件。
    這裡先做成雷達可用的輕量版：用現有資料 + 新增月營收/均線欄位判斷。
    EPS/毛利/營益率若目前資料源沒有，先不硬卡死；後續可再接財報模組。
    """
    def _num(col: str) -> Optional[float]:
        try:
            return to_float(row.get(col))
        except Exception:
            return None

    def _bool(col: str) -> bool:
        try:
            return bool(row.get(col))
        except Exception:
            return False

    status_text = "｜".join(str(row.get(c, "")) for c in ["狀態", "原始狀態", "位置", "族群資金狀態", "操作提醒"] if c in row.index)

    rev1 = _num("近1月營收YoY")
    rev3_min = _num("近3月營收YoY低")
    rev3_avg = _num("近3月營收YoY均")
    yoy = _num("月營收YoY")
    eps_yoy = _num("近1季EPSYoY")
    eps_qoq = _num("近1季EPSQoQ")
    op_yoy = _num("近1季營益YoY")
    gp_yoy = _num("近1季毛利YoY")
    gm = _num("近1季毛利率")
    gm_yoy_pp = _num("近1季毛利率YoY差")
    op_margin = _num("近1季營益率")
    inst5 = _num("法人5日")
    inst20 = _num("法人20日")
    chg5 = _num("5日漲跌")
    chg20 = _num("20日漲跌")
    vol_ratio = _num("量比")
    bias20 = _num("20乖離")
    bias60 = _num("60乖離")
    trade_value = _num("今日成交值")
    avg_vol20 = _num("20日均量")
    angle = _num("MA60角度")

    above_ma60 = _bool("站上MA60") or ("站上MA20/MA60" in status_text) or ("MA60仍守住" in status_text)
    angle_ok = _bool("MA60角度>3") or (angle is not None and angle > 3) or ("角度>3" in status_text)
    ma20_gt_ma60 = _bool("MA20>MA60") or ("站上MA20/MA60" in status_text)
    ma60_gt_ma120 = _bool("MA60>MA120")
    ma20_up = _bool("MA20上升")
    rev3_all_gt10 = _bool("近3月營收全>10")

    # 排除：短線過熱 / 波段過熱 / 爆量過熱
    if chg5 is not None and chg5 > 10:
        return {"pass": False, "tag": "", "score": 0, "reason": "5日漲幅過大，二段買點不追"}
    if chg20 is not None and chg20 > 28:
        return {"pass": False, "tag": "", "score": 0, "reason": "20日漲幅過大，離二段買點太遠"}
    if vol_ratio is not None and vol_ratio > 2.5:
        return {"pass": False, "tag": "", "score": 0, "reason": "量比過熱，先等降溫"}

    # v214｜財報接棒硬門檻：
    # 成長股買點不能只看月營收；若 EPS / 毛利 / 營益 YoY 同步衰退，
    # 代表營收沒有轉成獲利，不能被歸為二段主攻或可先卡位。
    fin_values = [v for v in [eps_yoy, gp_yoy, op_yoy] if v is not None]
    fin_negative_count = sum(1 for v in fin_values if v < 0)
    hard_financial_decline = (
        eps_yoy is not None and gp_yoy is not None and op_yoy is not None
        and eps_yoy < 0 and gp_yoy < 0 and op_yoy < 0
    )
    if hard_financial_decline:
        return {
            "pass": False,
            "tag": "",
            "score": 0,
            "reason": "EPS/毛利/營益 YoY 同步衰退，財報接棒失敗，先略過",
        }
    if len(fin_values) >= 2 and fin_negative_count >= 2:
        return {
            "pass": False,
            "tag": "",
            "score": 0,
            "reason": "EPS/毛利/營益至少兩項 YoY 衰退，財報接棒不足，先觀察",
        }

    # 基本面成長分：v173 接入 EPS / 毛利 / 營益率。
    basic_score = 0
    if rev3_all_gt10 or (rev3_min is not None and rev3_min > 10):
        basic_score += 2
    if rev1 is not None and rev1 > 15:
        basic_score += 1
    if yoy is not None and yoy > 20:
        basic_score += 1
    if rev3_avg is not None and rev3_avg > 20:
        basic_score += 1

    # EPS / 營益 / 毛利接棒
    if eps_yoy is not None and eps_yoy > 10:
        basic_score += 1
    if eps_yoy is not None and eps_yoy > 20:
        basic_score += 1
    if eps_qoq is not None and eps_qoq > 5:
        basic_score += 1
    if op_yoy is not None and op_yoy > 0:
        basic_score += 1
    if op_yoy is not None and op_yoy > 20:
        basic_score += 1
    if gp_yoy is not None and gp_yoy > 0:
        basic_score += 1
    if gm is not None and gm > 20:
        basic_score += 1
    if gm_yoy_pp is not None and gm_yoy_pp > 0:
        basic_score += 1
    if op_margin is not None and op_margin > 10:
        basic_score += 1

    if any(k in status_text for k in ["基本面轉強", "低基期轉強", "營收有改善", "資金與基本面同向"]):
        basic_score += 1

    # 趨勢分：二段布局 / 成長加速沿均線
    trend_score = 0
    if above_ma60 and ma20_gt_ma60:
        trend_score += 2
    if above_ma60 and angle_ok:
        trend_score += 2
    if ma60_gt_ma120:
        trend_score += 1
    if ma20_up:
        trend_score += 1

    # 買點分：沿20/60均附近，避免追太遠
    buy_point_score = 0
    if bias20 is not None and -5 <= bias20 <= 10:
        buy_point_score += 1
    if bias60 is not None and 0 <= bias60 <= 20:
        buy_point_score += 1
    if chg5 is not None and -5 <= chg5 <= 8:
        buy_point_score += 1
    if vol_ratio is not None and 0.6 <= vol_ratio <= 1.8:
        buy_point_score += 1

    # 法人/資金卡位
    inst_score = 0
    if inst5 is not None and inst5 > 0:
        inst_score += 1
    if inst20 is not None and inst20 > 0:
        inst_score += 1

    # 流動性：若有資料才檢查，不硬卡資料缺口
    liquidity_score = 0
    if trade_value is None or trade_value >= 100_000_000:
        liquidity_score += 1
    if avg_vol20 is None or avg_vol20 >= 1000:
        liquidity_score += 1

    # 基本面底線：至少要有營收成長路徑；EPS/毛利只能加分，不能完全取代營收。
    revenue_path_ok = (
        (rev1 is not None and rev1 > 10)
        or (rev3_min is not None and rev3_min > 5)
        or rev3_all_gt10
        or (yoy is not None and yoy > 10)
    )
    if basic_score < 3 or not revenue_path_ok:
        return {"pass": False, "tag": "", "score": 0, "reason": "營收/EPS/毛利接棒條件不足"}

    # 趨勢底線：健康盤整策略一定要站上MA60且角度>3
    if not (above_ma60 and angle_ok):
        return {"pass": False, "tag": "", "score": 0, "reason": "尚未通過站上MA60且MA60角度>3"}

    raw_score = basic_score * 18 + trend_score * 15 + buy_point_score * 12 + inst_score * 8 + liquidity_score * 5
    score = int(max(0, min(100, round(raw_score))))

    if basic_score >= 4 and trend_score >= 4 and buy_point_score >= 3 and inst_score >= 1:
        return {
            "pass": True,
            "tag": "營收二段主攻",
            "score": score,
            "reason": "營收、EPS/毛利或營益率有接棒，均線多頭、買點未過熱，且法人已有卡位跡象",
            "status_hint": "健康盤整｜等重新定價",
        }

    if basic_score >= 3 and trend_score >= 4 and buy_point_score >= 2:
        return {
            "pass": True,
            "tag": "營收二段盤整",
            "score": score,
            "reason": "營收仍成長，EPS/毛利或營益率有加分，股價站上MA60且角度>3，等待整理後重新給價",
            "status_hint": "健康盤整｜等重新定價",
        }

    if basic_score >= 3 and trend_score >= 3 and buy_point_score >= 2:
        return {
            "pass": True,
            "tag": "成長加速觀察",
            "score": score,
            "reason": "基本面轉強且趨勢偏多，但仍需法人或買點再確認",
            "status_hint": "可先卡位｜成長剛轉強",
        }

    return {"pass": False, "tag": "", "score": score, "reason": "二段買點條件尚未完整"}


def normalize_growth_buy_point_rows(df: pd.DataFrame) -> Tuple[pd.DataFrame, int]:
    """v215｜資金流入成長股買點雷達四區。

    共同條件 = 排雷
    可先卡位 = 強營收 + 強財報 + 趨勢剛轉多 + 不追高
    健康盤整 = 多頭趨勢 + 均線收斂 + 基本面沒壞 + 等重估
    回檔承接 = 靠近明確支撐 + 量縮回檔 + 未跌破 MA60
    低基期吃貨 = 低位階整理 + 營收改善 + 主力吃貨 + 等約一個月
    """
    if df is None or df.empty or "狀態" not in df.columns:
        return df, 0

    work = df.copy()
    if "原始狀態" not in work.columns:
        work["原始狀態"] = work["狀態"]

    keep_rows = []
    removed_codes = set()

    def _num(row: pd.Series, col: str) -> Optional[float]:
        try:
            return to_float(row.get(col))
        except Exception:
            return None

    def _bool(row: pd.Series, col: str) -> bool:
        try:
            return bool(row.get(col))
        except Exception:
            return False

    def _remove(row: pd.Series) -> None:
        code, _name = parse_radar_stock_label(row.get("股票", ""))
        code = clean_stock_id(code or "")
        if code:
            removed_codes.add(code)

    def _sector_excluded(row: pd.Series) -> bool:
        sector_txt = str(row.get("族群", "") or "") + "｜" + str(row.get("產業", "") or "")
        blocked = ["水泥", "生技醫療", "存託憑證", "金融保險", "建材營造", "造紙", "鋼鐵"]
        return any(k in sector_txt for k in blocked)

    def _priority(status: str) -> int:
        if status == "可先卡位｜成長剛轉強":
            return 0
        if status == "健康盤整｜等重新定價":
            return 1
        if status == "回檔承接｜等支撐切入":
            return 2
        if status == "低基期吃貨｜等待轉強":
            return 3
        return 9

    def _score(row: pd.Series, new_status: str, text: str) -> float:
        yoy = _num(row, "月營收YoY")
        rev1 = _num(row, "近1月營收YoY")
        rev_mom = _num(row, "近1月營收MoM")
        rev_ytd = _num(row, "近1月累計營收YoY")
        eps_yoy = _num(row, "近1季EPSYoY")
        gp_yoy = _num(row, "近1季毛利YoY")
        op_yoy = _num(row, "近1季營益YoY")
        inst5 = _num(row, "法人5日")
        inst20 = _num(row, "法人20日")
        inst40 = _num(row, "法人40日")
        inst_buy_days5 = _num(row, "法人5日買超天數")
        chg5 = _num(row, "5日漲跌")
        chg20 = _num(row, "20日漲跌")
        vol_ratio = _num(row, "量比")
        sector_status = str(row.get("族群資金狀態", "") or "")
        ma60_angle = _num(row, "MA60角度")
        ma60_change = _num(row, "MA60十日變化")
        ma_spread = _num(row, "均線差距")
        bias60 = _num(row, "60乖離")
        short_support_dist = _num(row, "短線支撐距離")
        swing_support_dist = _num(row, "波段支撐距離")
        tech_k = _num(row, "技術線K")
        beta60 = _num(row, "Beta60")
        avg_vol20 = _num(row, "20日均量")
        avg_vol40 = _num(row, "40日均量")
        trade_value = _num(row, "今日成交值")

        s = 0.0
        # 營收 / 財報
        if rev1 is not None and rev1 > 20: s += 18
        elif yoy is not None and yoy > 10: s += 12
        if rev_ytd is not None and rev_ytd > 15: s += 10
        if rev_mom is not None and rev_mom > 5: s += 8
        if eps_yoy is not None and eps_yoy > 10: s += 14
        elif eps_yoy is not None and eps_yoy > 5: s += 8
        if op_yoy is not None and op_yoy > 0: s += 10
        if gp_yoy is not None and gp_yoy > 0: s += 6

        fin_values = [v for v in [eps_yoy, gp_yoy, op_yoy] if v is not None]
        fin_neg_count = sum(1 for v in fin_values if v < 0)
        if len(fin_values) >= 3 and fin_neg_count >= 3: s -= 80
        elif len(fin_values) >= 2 and fin_neg_count >= 2: s -= 42
        elif len(fin_values) >= 1 and fin_neg_count >= 1: s -= 18

        # 趨勢 / 買點
        if _bool(row, "站上MA60"): s += 8
        if _bool(row, "MA20>MA60"): s += 8
        if ma60_angle is not None and ma60_angle > 3: s += 10
        if ma60_change is not None and ma60_change >= 1: s += 8
        if ma_spread is not None and ma_spread <= 8: s += 8
        if bias60 is not None and abs(bias60) < 10: s += 8
        if chg5 is not None and -5 <= chg5 <= 6: s += 10
        if vol_ratio is not None and 0.6 <= vol_ratio <= 1.8: s += 6
        if short_support_dist is not None and 0 <= short_support_dist <= 5: s += 10
        elif swing_support_dist is not None and 0 <= swing_support_dist <= 8: s += 8

        # 法人 / 吃貨 / 流動性
        if inst5 is not None and inst5 > 0: s += 7
        if inst20 is not None and inst20 > 0: s += 5
        if inst40 is not None and inst40 > 500: s += 9
        if inst_buy_days5 is not None and inst_buy_days5 > 3: s += 8
        if trade_value is not None and trade_value >= 50_000_000: s += 5
        if avg_vol20 is not None and avg_vol20 >= 3000: s += 5
        if avg_vol40 is not None and avg_vol40 >= 2000: s += 5
        if tech_k is not None and tech_k < 40: s += 5
        if beta60 is not None and beta60 < 2: s += 4

        if sector_status in ["明面主流", "偷偷流入", "低基期轉強", "回檔轉強"]: s += 8
        elif sector_status == "主流鈍化": s += 2
        elif "退潮" in sector_status: s -= 30

        if new_status == "可先卡位｜成長剛轉強": s += 10
        elif new_status == "健康盤整｜等重新定價": s += 6
        elif new_status == "回檔承接｜等支撐切入": s += 4
        elif new_status == "低基期吃貨｜等待轉強": s = min(s, 69)  # 低基期吃貨以觀察為主，不直接衝前順位
        return s

    for _, row in work.iterrows():
        status = str(row.get("狀態", "")).strip()
        text = "｜".join(
            str(row.get(c, ""))
            for c in ["狀態", "原始狀態", "位置", "操作", "操作提醒", "族群資金狀態"]
            if c in row.index
        )

        yoy = _num(row, "月營收YoY")
        rev1 = _num(row, "近1月營收YoY")
        rev_mom = _num(row, "近1月營收MoM")
        rev_ytd = _num(row, "近1月累計營收YoY")
        rev3_avg = _num(row, "近3月營收YoY均")
        eps_yoy = _num(row, "近1季EPSYoY")
        gp_yoy = _num(row, "近1季毛利YoY")
        op_yoy = _num(row, "近1季營益YoY")
        inst5 = _num(row, "法人5日")
        inst20 = _num(row, "法人20日")
        inst40 = _num(row, "法人40日")
        inst_buy_days5 = _num(row, "法人5日買超天數")
        chg5 = _num(row, "5日漲跌")
        chg20 = _num(row, "20日漲跌")
        vol_ratio = _num(row, "量比")
        sector_status = str(row.get("族群資金狀態", "") or "")
        trade_value = _num(row, "今日成交值")
        avg_vol20 = _num(row, "20日均量")
        avg_vol40 = _num(row, "40日均量")
        bias60 = _num(row, "60乖離")
        ma60_angle = _num(row, "MA60角度")
        ma60_change = _num(row, "MA60十日變化")
        ma_spread = _num(row, "均線差距")
        tech_k = _num(row, "技術線K")
        beta60 = _num(row, "Beta60")
        short_support_dist = _num(row, "短線支撐距離")
        swing_support_dist = _num(row, "波段支撐距離")

        fin_values = [v for v in [eps_yoy, gp_yoy, op_yoy] if v is not None]
        fin_negative_count = sum(1 for v in fin_values if v < 0)
        hard_financial_decline = (
            eps_yoy is not None and gp_yoy is not None and op_yoy is not None
            and eps_yoy < 0 and gp_yoy < 0 and op_yoy < 0
        )

        position_txt = str(row.get("位置", "") or "")
        above_ma60_flag = bool(row.get("站上MA60")) or ("MA60仍守住" in position_txt) or ("站上MA20/MA60" in position_txt)
        ma20_gt_ma60_flag = bool(row.get("MA20>MA60")) or ("站上MA20/MA60" in position_txt)
        ma60_angle_ok_flag = bool(row.get("MA60角度>3")) or (ma60_angle is not None and ma60_angle > 3) or ("角度>3" in position_txt)
        sector_blocked = _sector_excluded(row)

        exclude_words = [
            "退潮中", "短線退潮", "明確退潮", "反彈賣點", "過熱", "不追高", "已反彈不追",
            "資料待補", "心法未過", "題材待驗證", "法醫驗證", "權值/龍頭型"
        ]
        if any(k in text for k in exclude_words) or ("退潮" in sector_status):
            _remove(row)
            continue

        # 共同條件 = 排雷
        hot_by_number = (
            (chg5 is not None and chg5 > 8)
            or (chg20 is not None and chg20 > 20)
            or (vol_ratio is not None and vol_ratio >= 2.2)
        )
        if hot_by_number:
            _remove(row)
            continue

        price_broken = (chg5 is not None and chg5 < -8) and (chg20 is not None and chg20 < -10)
        basic_bad = yoy is not None and yoy <= 0 and not any(k in text for k in ["營收有改善", "基本面轉強", "資金與基本面同向"])
        # v215：法人20日賣超不再一票否決；只看法人5日明顯倒貨。
        inst_short_dumping = inst5 is not None and inst5 < -500
        if price_broken or (inst_short_dumping and basic_bad):
            _remove(row)
            continue

        if hard_financial_decline:
            _remove(row)
            continue

        # 低基期吃貨：獨立分類，不再由共同條件的「低基期」放行。
        low_base_eating_pass = (
            ma60_angle is not None and -3 < ma60_angle < 5
            and bias60 is not None and abs(bias60) < 13
            and tech_k is not None and tech_k < 40
            and rev_mom is not None and rev_mom > 5
            and rev1 is not None and rev1 > 10
            and eps_yoy is not None and eps_yoy > 5
            and inst40 is not None and inst40 > 500
            and avg_vol40 is not None and avg_vol40 > 2000
            and beta60 is not None and beta60 < 2
        )

        basic_has_path = (
            (yoy is not None and yoy > 0)
            or any(k in text for k in ["基本面轉強", "營收有改善", "資金與基本面同向"])
        )
        if not basic_has_path and not low_base_eating_pass:
            _remove(row)
            continue

        strong_revenue = (rev1 is not None and rev1 > 20) and (rev_ytd is not None and rev_ytd > 15)
        strong_fin = (eps_yoy is not None and eps_yoy > 10) and (op_yoy is not None and op_yoy > 0) and fin_negative_count == 0
        trend_turning = above_ma60_flag and ma20_gt_ma60_flag and (ma60_change is not None and ma60_change >= 1) and (bias60 is not None and bias60 < 10)
        no_chase = (chg5 is not None and -5 <= chg5 <= 6) and (vol_ratio is None or vol_ratio < 2.2)
        liquid_enough = (trade_value is None or trade_value >= 50_000_000) and (avg_vol20 is None or avg_vol20 >= 3000)
        inst_days_ok = inst_buy_days5 is not None and inst_buy_days5 > 3
        can_card_pass = strong_revenue and strong_fin and trend_turning and no_chase and liquid_enough and inst_days_ok and not sector_blocked

        healthy_revenue = (rev1 is not None and rev1 > 10) or (rev3_avg is not None and rev3_avg > 10) or (yoy is not None and yoy > 10)
        fin_not_bad = len(fin_values) == 0 or any(v > 0 for v in fin_values)
        trend_healthy = above_ma60_flag and ma20_gt_ma60_flag and ma60_angle_ok_flag and (bias60 is None or bias60 < 10)
        ma_converge = ma_spread is None or ma_spread <= 8
        healthy_buyzone = (chg5 is None or -5 <= chg5 <= 6) and (chg20 is None or chg20 <= 20) and (vol_ratio is None or vol_ratio < 2.2)
        healthy_pass = trend_healthy and ma_converge and healthy_revenue and fin_not_bad and healthy_buyzone

        support_near = (
            (short_support_dist is not None and 0 <= short_support_dist <= 5)
            or (swing_support_dist is not None and 0 <= swing_support_dist <= 8)
        )
        pullback_quality = (chg5 is not None and -8 <= chg5 <= 3) and (chg20 is None or chg20 > -10) and (vol_ratio is None or 0.6 <= vol_ratio <= 1.5)
        pullback_pass = support_near and pullback_quality and above_ma60_flag and basic_has_path

        new_status = ""
        strategy_tag = ""
        strategy_reason = ""
        strategy_score = ""

        if can_card_pass:
            new_status = "可先卡位｜成長剛轉強"
            strategy_tag = "可先卡位"
            strategy_reason = "強營收、強財報、趨勢剛轉多，且近5日未過熱。"
            strategy_score = 100
        elif healthy_pass:
            new_status = "健康盤整｜等重新定價"
            strategy_tag = "健康盤整"
            strategy_reason = "多頭趨勢、均線收斂、基本面沒壞，等待市場重新定價。"
            strategy_score = 90
        elif pullback_pass:
            new_status = "回檔承接｜等支撐切入"
            strategy_tag = "回檔承接"
            support_txt = "短線支撐" if (short_support_dist is not None and 0 <= short_support_dist <= 5) else "波段支撐"
            strategy_reason = f"靠近{support_txt}、量縮回檔，且尚未跌破 MA60。"
            strategy_score = 82
        elif low_base_eating_pass:
            new_status = "低基期吃貨｜等待轉強"
            strategy_tag = "低基期吃貨"
            strategy_reason = "低位階整理、營收改善、主力近40日吃貨，先觀察約一個月。"
            strategy_score = 68
        else:
            _remove(row)
            continue

        row = row.copy()
        row["狀態"] = new_status
        row["策略標籤"] = strategy_tag
        row["策略分數"] = strategy_score
        row["策略理由"] = strategy_reason
        row["_growth_priority"] = _priority(new_status)
        raw_score = _score(row, new_status, text)

        financial_cap_note = ""
        if len(fin_values) >= 2 and fin_negative_count >= 2:
            raw_score = min(raw_score, 59)
            financial_cap_note = "財報接棒不足：EPS/毛利/營益至少兩項 YoY 衰退，先略過。"
        elif len(fin_values) >= 1 and fin_negative_count >= 1:
            raw_score = min(raw_score, 69)
            financial_cap_note = "財報接棒仍有一項 YoY 衰退，先列觀察，不排前順位。"

        row["_growth_score"] = raw_score
        try:
            row["優先分數"] = int(max(0, min(100, round(raw_score))))
        except Exception:
            row["優先分數"] = "—"

        if new_status == "可先卡位｜成長剛轉強":
            row["操作"] = "先放待分析 / 找低風險切入"
            row["操作提醒"] = "強營收 + 強財報 + 趨勢剛轉多 + 不追高；可排前面進法醫驗證。"
        elif new_status == "健康盤整｜等重新定價":
            row["操作"] = "盤整不破 / 等重新定價"
            row["操作提醒"] = "多頭趨勢 + 均線收斂 + 基本面沒壞；等資金重新推動與市場重估。"
        elif new_status == "回檔承接｜等支撐切入":
            row["操作"] = "等支撐確認 / 不追高"
            row["操作提醒"] = "靠近明確支撐 + 量縮回檔 + 未跌破 MA60；重點看支撐守住。"
        elif new_status == "低基期吃貨｜等待轉強":
            row["操作"] = "放觀察池 / 等約一個月驗證"
            row["操作提醒"] = "低位階整理 + 營收改善 + 主力吃貨；先觀察，不直接排主攻順位。"
        if financial_cap_note:
            row["操作提醒"] = str(row.get("操作提醒", "") or "") + "｜" + financial_cap_note

        keep_rows.append(row)

    if not keep_rows:
        return work.iloc[0:0].copy(), len(removed_codes)

    out = pd.DataFrame(keep_rows)
    if "股票" in out.columns:
        out["_code"] = out["股票"].apply(lambda x: clean_stock_id(parse_radar_stock_label(x)[0] or ""))
        out = out.sort_values(["_code", "_growth_priority", "_growth_score"], ascending=[True, True, False], kind="stable")
        out = out.drop_duplicates(subset=["_code"], keep="first")
        out = out.drop(columns=["_code"], errors="ignore")

    out = out.sort_values(["_growth_priority", "_growth_score"], ascending=[True, False], kind="stable")
    out = out.drop(columns=["_growth_priority", "_growth_score"], errors="ignore")
    return out.reset_index(drop=True), len(removed_codes)

def render_radar_page(snapshot: Dict[str, Any], mode: str) -> None:
    radar = get_radar_data_for_mode(snapshot, mode)
    rows = radar.get("rows") or []
    mode_label = RADAR_MODE_LABELS.get(mode, "資金流入成長股買點")
    title_emoji = "🧬"

    st.markdown(f"### {title_emoji} 族群個股雷達｜{mode_label}")
    st.caption(
        f"資料交易日：{radar.get('trade_date') or get_snapshot_trade_date(snapshot)}｜"
        f"掃描時間：{radar.get('scan_time') or radar.get('updated_at', '—')}｜"
        f"族群來源：{radar.get('sector_source', '—')}｜"
        f"掃描狀態：{', '.join(radar.get('scan_statuses', [])) or '—'}"
    )

    if not rows:
        st.info("尚未掃描這一頁。請按上方『掃描資金流入成長股買點』。")
        return

    show = prepare_radar_display_df(radar, snapshot=snapshot)
    if show.empty:
        st.info("目前沒有個股雷達資料。")
        return

    # v163：主雷達只做「資金流入成長股買點」。
    overheat_removed_count = 0
    growth_removed_count = 0

    if mode in ["growth", "inflow"]:
        show, overheat_removed_count = filter_overheat_radar_rows(show)
        show, growth_removed_count = normalize_growth_buy_point_rows(show)

        if show.empty:
            raw_count = len(rows or [])
            removed_total = int(overheat_removed_count or 0) + int(growth_removed_count or 0)
            unique_total = radar.get("scan_unique_total") or radar.get("scan_total") or raw_count
            cache_hits = radar.get("cache_hits") or 0
            dup_hits = radar.get("scan_duplicate_hits") or 0
            fast_skips = radar.get("fast_skips") or 0
            fin_fetches = radar.get("fin_fetches") or 0
            workers = radar.get("parallel_workers") or RADAR_PARALLEL_WORKERS
            st.warning(
                f"本次去重後掃描 {unique_total} 檔（族群命中 {raw_count} 筆，重複命中省略 {dup_hits} 筆，"
                f"平行掃描 {workers} 檔，快篩省財報 {fast_skips} 檔，進財報驗證 {fin_fetches} 檔，快取命中 {cache_hits} 檔），"
                f"經過「未過熱、財報接棒、法人未倒貨、技術未破壞、買點接近」過濾後，"
                f"目前沒有符合成長股買點的標的。"
            )
            if removed_total:
                st.caption(f"已排除 {removed_total} 檔；今天先不硬選，等資金重新聚焦或標的回到更好的買點。")
            else:
                st.caption("今天先不硬選，等資金重新聚焦或標的回到更好的買點。")
            return

        cols = ["族群", "族群資金狀態", "股票", "即時股價", "優先分數", "策略標籤", "策略分數", "狀態", "法人5日", "法人20日", "法人40日", "法人5日買超天數", "月營收YoY", "近1月營收YoY", "近1月營收MoM", "近1月累計營收YoY", "近3月營收YoY低", "近1季EPSYoY", "近1季EPSQoQ", "近1季毛利YoY", "近1季營益YoY", "近1季毛利率", "近1季營益率", "二段快篩", "二段快篩原因", "5日漲跌", "20日漲跌", "20乖離", "60乖離", "量比", "技術線K", "Beta60", "MA60", "MA60角度", "MA60十日變化", "均線差距", "短線支撐", "短線支撐距離", "波段支撐", "波段支撐距離", "MA60角度>3", "位置", "操作", "操作提醒", "策略理由"]
        sections = [
            ("可先卡位｜成長剛轉強", ["可先卡位｜成長剛轉強"]),
            ("健康盤整｜等重新定價", ["健康盤整｜等重新定價"]),
            ("回檔承接｜等支撐切入", ["回檔承接｜等支撐切入"]),
            ("低基期吃貨｜等待轉強", ["低基期吃貨｜等待轉強"]),
        ]
        pending_count = len(get_pending_analysis_list(st.session_state.get("snapshot", {})))
        with st.expander("雷達定位與四種策略說明", expanded=False):
            st.markdown(
                """
**共同條件 = 排雷**  
先排除過熱、不追高、技術破壞、法人短線倒貨、財報明顯沒接棒的標的。法人20日賣超只做扣分與提醒，不再一票否決。

**可先卡位 = 強營收 + 強財報 + 趨勢剛轉多 + 不追高**  
找營收轉強、財報有接棒、均線剛轉多，且短線尚未噴遠的標的。

**健康盤整 = 多頭趨勢 + 均線收斂 + 基本面沒壞 + 等重估**  
找基本面仍好、股價站上多頭結構、正在盤整，等待市場重新定價的標的。

**回檔承接 = 靠近明確支撐 + 量縮回檔 + 未跌破 MA60**  
明確支撐包含短線支撐（MA20 / 近20日低點）與波段支撐（MA60 / 近60日低點）。

**低基期吃貨 = 低位階整理 + 營收改善 + 主力吃貨 + 等約一個月**  
找原本低位階、營收開始改善、主力開始卡位，但尚未正式主升的觀察型標的。
                """
            )
        st.caption(f"待分析清單：{pending_count} 檔｜展開股票卡後按「＋」即可加入。")
        removed_total = int(overheat_removed_count or 0) + int(growth_removed_count or 0)
        if removed_total:
            st.caption(f"已排除 {removed_total} 檔過熱、不追高、法人短線倒貨、財報接棒失敗、技術破壞或不符合四種策略條件的標的。")

        render_radar_group_expanders(show, sections, cols, enable_pending_add=True, sort_mode="inflow", overlap_codes=set())
        allowed = []
        for _, values in sections:
            allowed.extend(values)
        render_radar_by_sector_expander(show, cols, "依族群查看｜資金流入成長股", allowed_statuses=allowed, enable_pending_add=True, sort_mode="inflow", overlap_codes=set())
    else:
        st.info("此版本已改為單一『資金流入成長股買點雷達』。請回掃股雷達主頁按『掃描資金流入成長股買點』。")


def render_flow_settings() -> None:
    """v112｜資金流向頁固定設定，不顯示設定區。

    固定每個資金族群取樣 5 檔代表股，並移除手機畫面上的滑桿與進階設定。
    不讓舊 session_state 的選項殘留影響全市場掃描。
    """
    st.session_state["flow_max_each"] = 5
