def render_radar_settings(key_suffix: str = "main") -> None:
    with st.expander("資金流入成長股雷達設定（初始收合）", expanded=False):
        snapshot = st.session_state.get("snapshot", {})
        options = radar_sector_options(snapshot)
        if not options:
            options = list(SECTOR_STOCK_POOL.keys())

        source_options = ["依最新資金流向自動帶入", "手動選擇族群"]
        current_source = st.session_state.get("radar_source", source_options[0])
        source_index = source_options.index(current_source) if current_source in source_options else 0
        source_mode = st.radio(
            "雷達族群來源",
            source_options,
            index=source_index,
            horizontal=True,
            key=f"radar_source_selector_{key_suffix}",
        )
        st.session_state.radar_source = source_mode

        if source_mode == "依最新資金流向自動帶入":
            inflow_sectors = auto_radar_sectors_from_flow(snapshot, RADAR_INFLOW_STATUSES) or snapshot.get("radar_auto_sectors") or DEFAULT_RADAR_SECTORS
            st.session_state.radar_sectors = inflow_sectors

            with st.expander("本次自動帶入族群", expanded=False):
                st.markdown("#### 資金流入成長股買點雷達會帶入")
                st.caption("只看資金流入方向：明面主流、偷偷流入、低基期轉強、回檔轉強、主流鈍化。退潮不當主掃描，只作為排除風險。")
                st.markdown("".join(tag_html(x, "blue") for x in inflow_sectors) if inflow_sectors else "<span class='subtle'>尚無自動族群</span>", unsafe_allow_html=True)
        else:
            manual_default = st.session_state.get("radar_sectors", DEFAULT_RADAR_SECTORS)
            manual_default = [x for x in manual_default if x in options] or [x for x in DEFAULT_RADAR_SECTORS if x in options]
            st.session_state.radar_sectors = st.multiselect(
                "手動選擇掃描族群",
                options,
                default=manual_default,
                key=f"radar_sectors_selector_{key_suffix}",
            )
            st.caption("手動模式下，仍然使用同一套「資金流入成長股買點」條件篩選。")

        st.session_state.radar_max_each = st.slider(
            "每個族群掃描幾檔",
            2,
            8,
            int(st.session_state.get("radar_max_each", 5)),
            key=f"radar_max_each_selector_{key_suffix}",
        )
        st.session_state.discovery_max_each = st.slider(
            "每個族群聯網新增幾檔候選",
            1,
            5,
            int(st.session_state.get("discovery_max_each", 3)),
            key=f"discovery_max_each_selector_{key_suffix}",
        )
        flow_count = len({str(r.get("族群")) for r in flow_rows_sorted(snapshot) if r.get("族群")})
        discovered_count = sum(len(v or []) for v in (snapshot.get("discovered_pool") or {}).values())
        st.caption(f"目前資金流向族群：{flow_count} 組｜暫存聯網候選：{discovered_count} 檔。建議順序：更新資金流向 → 掃描資金流入成長股買點。")


def render_update_log(snapshot: Dict[str, Any]) -> None:
    logs = snapshot.get("log") or []
    st.markdown("### 🧾 更新紀錄")
    if not logs:
        st.caption("尚無更新紀錄。")
        return
    st.dataframe(pd.DataFrame(logs), use_container_width=True, hide_index=True)



# =========================================================
# Embedded original stock analyzer app
# =========================================================
# 合併原則：
# 1. 大盤分析 App(app27) 作為主體。
# 2. 個股分析 App(app28) 以原始碼內嵌執行。
# 3. 僅移除 app28 的 st.set_page_config，避免 Streamlit 重複設定頁面而報錯。
# 4. 不改寫 app28 的估值、K線、法人、營收、財報、法醫核心邏輯。

# =========================================================
# Main navigation and app entry restored
# =========================================================

STOCK_ANALYZER_CORE_FILE = Path(__file__).with_name("stock_analyzer_core.py")

def load_stock_analyzer_core_code() -> str:
    """Lazy load the stock analyzer core.

    fix23:
    不再使用 st.cache_resource 快取 stock_analyzer_core.py。
    原因：覆蓋新版核心檔後，Streamlit 可能仍執行舊快取內容，
    造成已修正的錯誤仍反覆出現。
    """
    if not STOCK_ANALYZER_CORE_FILE.exists():
        raise FileNotFoundError(
            f"找不到 {STOCK_ANALYZER_CORE_FILE.name}，請確認它和 app.py 放在同一個資料夾。"
        )
    return STOCK_ANALYZER_CORE_FILE.read_text(encoding="utf-8")


def render_original_stock_analyzer_app() -> None:
    # 個股分析器頁面：不再顯示額外說明標題，直接進入原本個股分析器內容。
    # 仍保留共用大盤資金流同步功能，避免影響原本分析邏輯。
    try:
        _shared_snapshot = st.session_state.get("snapshot", {})
        _sync_result = sync_market_flow_to_stock_app(_shared_snapshot)
        _shared_flow = (_shared_snapshot or {}).get("flow") or {}

        _ns = {
            "__name__": "__embedded_original_stock_app__",
            "__file__": "embedded_original_stock_app.py",
            "NICK_SHARED_FLOW_SNAPSHOT": _shared_flow,
            "NICK_PENDING_ANALYSIS_HOOK": render_pending_analysis_hook_for_stock_app,
        }
        exec(load_stock_analyzer_core_code(), _ns)
    except Exception as e:
        st.error(f"個股分析器載入失敗：{e}")
        st.exception(e)


# =========================================================
# Main navigation and app entry restored
# =========================================================

STOCK_ANALYZER_CORE_FILE = Path(__file__).with_name("stock_analyzer_core.py")

def load_stock_analyzer_core_code() -> str:
    """Lazy load the stock analyzer core.

    fix23:
    不再使用 st.cache_resource 快取 stock_analyzer_core.py。
    原因：覆蓋新版核心檔後，Streamlit 可能仍執行舊快取內容，
    造成已修正的錯誤仍反覆出現。
    """
    if not STOCK_ANALYZER_CORE_FILE.exists():
        raise FileNotFoundError(
            f"找不到 {STOCK_ANALYZER_CORE_FILE.name}，請確認它和 app.py 放在同一個資料夾。"
        )
    return STOCK_ANALYZER_CORE_FILE.read_text(encoding="utf-8")


def render_original_stock_analyzer_app() -> None:
    # 個股分析器頁面：不再顯示額外說明標題，直接進入原本個股分析器內容。
    # 仍保留共用大盤資金流同步功能，避免影響原本分析邏輯。
    try:
        _shared_snapshot = st.session_state.get("snapshot", {})
        _sync_result = sync_market_flow_to_stock_app(_shared_snapshot)
        _shared_flow = (_shared_snapshot or {}).get("flow") or {}

        _ns = {
            "__name__": "__embedded_original_stock_app__",
            "__file__": "embedded_original_stock_app.py",
            "NICK_SHARED_FLOW_SNAPSHOT": _shared_flow,
            "NICK_PENDING_ANALYSIS_HOOK": render_pending_analysis_hook_for_stock_app,
        }
        exec(load_stock_analyzer_core_code(), _ns)
    except Exception as e:
        st.error(f"個股分析器載入失敗：{e}")
        st.exception(e)


def render_main_nav() -> str:
    """v102｜Streamlit 原生狀態導覽，不再用 HTML <a> 跳頁。

    修正重點：
    - 不使用 query params / href，所以點導覽不會觸發瀏覽器整頁重新載入。
    - 改用 st.radio 管理狀態，只做 Streamlit 內部 rerun。
    - 用 CSS 把 radio 做成無外框、置中、底線式 tab。
    - 主標題與子標題字體大小拉開，主層較大、子層較小。
    """
    nav_groups = {
        "大盤": ["總覽", "外部風險", "新聞快照", "資金流向"],
        "掃股雷達": ["資金流入成長股雷達"],
        "個股分析器": ["個股法醫分析器"],
        "系統": ["更新紀錄"],
    }
    sub_labels = {
        "總覽": "總覽",
        "外部風險": "國際風險",
        "新聞快照": "新聞快照",
        "資金流向": "資金流向",
        "資金流入成長股雷達": "成長股",
        "個股法醫分析器": "個股分析器",
        "更新紀錄": "紀錄",
    }
    group_first_page = {
        "大盤": "總覽",
        "掃股雷達": "資金流入成長股雷達",
        "個股分析器": "個股法醫分析器",
        "系統": "更新紀錄",
    }

    pages = [p for group_pages in nav_groups.values() for p in group_pages]
    valid_pages = set(pages)
    page_to_group = {page: group for group, group_pages in nav_groups.items() for page in group_pages}
    legacy_radar_pages = {"資金流入雷達", "資金退潮雷達", "訊號重複雷達"}
    if st.session_state.get("main_nav_page") in legacy_radar_pages:
        st.session_state["main_nav_page"] = "資金流入成長股雷達"
        st.session_state["main_nav_group"] = "掃股雷達"
    if st.session_state.get("pending_main_nav_page") in legacy_radar_pages:
        st.session_state["pending_main_nav_page"] = "資金流入成長股雷達"
    if st.session_state.get("force_main_nav_page_once") in legacy_radar_pages:
        st.session_state["force_main_nav_page_once"] = "資金流入成長股雷達"


    # 1) 先吃內部 pending / force，讓更新按鈕、雷達按鈕仍可導頁。
    pending_page = st.session_state.pop("pending_main_nav_page", None)
    force_page = st.session_state.pop("force_main_nav_page_once", None)
    target_page = force_page if force_page in valid_pages else pending_page
    if target_page in valid_pages:
        target_group = page_to_group[target_page]
        st.session_state["main_nav_page"] = target_page
        st.session_state["main_nav_group"] = target_group

        # v167｜關鍵修正：
        # st.radio 有自己的 widget key；只改 main_nav_page/main_nav_group 不夠，
        # 手機前端可能仍保留舊 radio 值，造成「按分析但不跳頁」。
        # 這裡在 radio 建立前同步 widget key，避免被舊值覆蓋。
        st.session_state["nick_main_nav_group_radio"] = target_group
        if len(nav_groups.get(target_group, [])) > 1:
            st.session_state["nick_sub_nav_page_radio"] = target_page
        elif "nick_sub_nav_page_radio" in st.session_state:
            # 單頁群組不會顯示子 radio，清掉舊子頁值，避免下次切回多頁群組殘留。
            st.session_state.pop("nick_sub_nav_page_radio", None)

    # 2) 預設值與防呆。
    if "main_nav_page" not in st.session_state or st.session_state["main_nav_page"] not in valid_pages:
        st.session_state["main_nav_page"] = "總覽"
        st.session_state["nick_main_nav_group_radio"] = "大盤"
        st.session_state["nick_sub_nav_page_radio"] = "總覽"
    # 舊版群組名稱相容：雷達 -> 掃股雷達；法醫 -> 個股分析器
    _saved_group = st.session_state.get("main_nav_group", "大盤")
    if _saved_group == "雷達":
        _saved_group = "掃股雷達"
        st.session_state["main_nav_group"] = _saved_group
    elif _saved_group == "法醫":
        _saved_group = "個股分析器"
        st.session_state["main_nav_group"] = _saved_group
    selected_page = st.session_state["main_nav_page"]
    selected_group = page_to_group.get(selected_page, _saved_group)
    if selected_group not in nav_groups:
        selected_group = "大盤"
        selected_page = "總覽"
    if selected_page not in nav_groups[selected_group]:
        selected_page = group_first_page.get(selected_group, nav_groups[selected_group][0])

    st.session_state["main_nav_group"] = selected_group
    st.session_state["main_nav_page"] = selected_page

    css = """
<style>
/* v105：移除 header 橫線、導覽往上收、減少主/子導覽上方空白 */
.st-key-nick_main_nav_group_radio,
.st-key-nick_sub_nav_page_radio {
  width: 100%;
  margin: 0 auto !important;
  padding: 0 !important;
}
/* 把 radio 外層多餘空白壓掉 */
.st-key-nick_main_nav_group_radio > div,
.st-key-nick_sub_nav_page_radio > div {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}
.st-key-nick_main_nav_group_radio [data-testid="stRadio"] > div,
.st-key-nick_sub_nav_page_radio [data-testid="stRadio"] > div {
  padding-top: 0 !important;
  margin-top: 0 !important;
}

.st-key-nick_main_nav_group_radio {
  margin-top: -18px !important;
  margin-bottom: -6px !important;
}
.st-key-nick_sub_nav_page_radio {
  margin-top: -10px !important;
}
.st-key-nick_main_nav_group_radio [data-testid="stRadio"],
.st-key-nick_sub_nav_page_radio [data-testid="stRadio"] {
  width: 100%;
}
/* 隱藏 radio 本身的標題，只保留選項文字 */
.st-key-nick_main_nav_group_radio [data-testid="stWidgetLabel"],
.st-key-nick_sub_nav_page_radio [data-testid="stWidgetLabel"] {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.st-key-nick_main_nav_group_radio [role="radiogroup"],
.st-key-nick_sub_nav_page_radio [role="radiogroup"] {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  flex-wrap: wrap !important;
  width: 100% !important;
}
.st-key-nick_main_nav_group_radio [role="radiogroup"] {
  gap: 36px !important;
  margin: 0 auto -4px auto !important;
}
.st-key-nick_sub_nav_page_radio [role="radiogroup"] {
  gap: 34px !important;
  margin: -8px auto 10px auto !important;
}
.st-key-nick_main_nav_group_radio label,
.st-key-nick_sub_nav_page_radio label {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 54px !important;
  margin: 0 !important;
  padding: 4px 2px 10px 2px !important;
  background: transparent !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  cursor: pointer !important;
}
/* 隱藏 radio 圓點，只保留文字 */
.st-key-nick_main_nav_group_radio label > div:first-child,
.st-key-nick_sub_nav_page_radio label > div:first-child {
  display: none !important;
}
.st-key-nick_main_nav_group_radio label p,
.st-key-nick_sub_nav_page_radio label p {
  margin: 0 !important;
  padding: 0 !important;
  color: #a7b0c2 !important;
  text-align: center !important;
  white-space: nowrap !important;
  line-height: 1.08 !important;
  letter-spacing: .04em !important;
  transition: color .15s ease, transform .15s ease, opacity .15s ease !important;
}
/* 主標題：明顯較大 */
.st-key-nick_main_nav_group_radio label p {
  font-size: 1.22rem !important;
  font-weight: 950 !important;
}
/* 子標題：比主標題小一階 */
.st-key-nick_sub_nav_page_radio label p {
  font-size: .96rem !important;
  font-weight: 850 !important;
  opacity: .94 !important;
}
.st-key-nick_main_nav_group_radio label:hover p,
.st-key-nick_sub_nav_page_radio label:hover p {
  color: #f8fafc !important;
  transform: translateY(-1px) !important;
}
.st-key-nick_main_nav_group_radio label:has(input:checked) p,
.st-key-nick_sub_nav_page_radio label:has(input:checked) p {
  color: #f8fafc !important;
  opacity: 1 !important;
}
.st-key-nick_main_nav_group_radio label:has(input:checked)::after,
.st-key-nick_sub_nav_page_radio label:has(input:checked)::after {
  content: "";
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 999px;
  background: linear-gradient(90deg, #ff4b4b, #f97316);
  box-shadow: 0 0 7px rgba(255, 75, 75, .24), 0 0 10px rgba(249, 115, 22, .16);
}
.st-key-nick_main_nav_group_radio label:has(input:checked)::after {
  bottom: 3px;
  width: 28px;
  height: 2.2px;
}
.st-key-nick_sub_nav_page_radio label:has(input:checked)::after {
  bottom: 4px;
  width: 20px;
  height: 1.8px;
}
@media (max-width: 680px) {
  .st-key-nick_main_nav_group_radio [role="radiogroup"] {
    gap: 31px !important;
    margin-top: -2px !important;
    margin-bottom: -4px !important;
  }
  .st-key-nick_sub_nav_page_radio [role="radiogroup"] {
    gap: 30px !important;
    margin-top: -8px !important;
    margin-bottom: 10px !important;
  }
  .st-key-nick_main_nav_group_radio label,
  .st-key-nick_sub_nav_page_radio label {
    min-width: 46px !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
  .st-key-nick_main_nav_group_radio label p {
    font-size: 1.14rem !important;
  }
  .st-key-nick_sub_nav_page_radio label p {
    font-size: .90rem !important;
  }
}
@media (max-width: 390px) {
  .st-key-nick_main_nav_group_radio [role="radiogroup"] {
    gap: 24px !important;
  }
  .st-key-nick_sub_nav_page_radio [role="radiogroup"] {
    gap: 23px !important;
  }
  .st-key-nick_main_nav_group_radio label p {
    font-size: 1.08rem !important;
  }
  .st-key-nick_sub_nav_page_radio label p {
    font-size: .86rem !important;
  }
}
</style>
"""
    st.markdown(css, unsafe_allow_html=True)

    # 3) 主層導覽：使用 Streamlit radio，不使用 href，所以不會瀏覽器整頁刷新。
    group_options = list(nav_groups.keys())
    try:
        group_index = group_options.index(selected_group)
    except ValueError:
        group_index = 0

    chosen_group = st.radio(
        " ",
        group_options,
        index=group_index,
        horizontal=True,
        label_visibility="collapsed",
        key="nick_main_nav_group_radio",
    )

    # 若主層切換，頁面切到該群組的第一個合理頁。
    if chosen_group != st.session_state.get("main_nav_group"):
        st.session_state["main_nav_group"] = chosen_group
        st.session_state["main_nav_page"] = group_first_page.get(chosen_group, nav_groups[chosen_group][0])
        selected_group = chosen_group
        selected_page = st.session_state["main_nav_page"]
    else:
        selected_group = chosen_group
        selected_page = st.session_state.get("main_nav_page", group_first_page.get(selected_group, nav_groups[selected_group][0]))

    # 4) 子層導覽：只有多頁群組顯示。主層與子層字級已在 CSS 拉開。
    if len(nav_groups[selected_group]) > 1:
        sub_options = nav_groups[selected_group]
        if selected_page not in sub_options:
            selected_page = sub_options[0]
            st.session_state["main_nav_page"] = selected_page
        try:
            sub_index = sub_options.index(selected_page)
        except ValueError:
            sub_index = 0

        chosen_page = st.radio(
            " ",
            sub_options,
            index=sub_index,
            horizontal=True,
            format_func=lambda page: sub_labels.get(page, page),
            label_visibility="collapsed",
            key="nick_sub_nav_page_radio",
        )
        st.session_state["main_nav_page"] = chosen_page
        st.session_state["main_nav_group"] = selected_group
    else:
        st.session_state["main_nav_page"] = group_first_page.get(selected_group, nav_groups[selected_group][0])
        st.session_state["main_nav_group"] = selected_group

    return st.session_state.get("main_nav_page", "總覽")

# =========================================================
# Main
# =========================================================
def main() -> None:
    inject_css()
    if "snapshot" not in st.session_state:
        st.session_state.snapshot = load_snapshot()
    snapshot = st.session_state.snapshot

    # v207｜取消10分鐘自動更新，改回手動按「更新-大盤資訊」。
    render_header(snapshot)
    snapshot = render_update_controls(snapshot)
    st.session_state.snapshot = snapshot

    # 改用自訂導覽，不再依賴 st.tabs 的預設選取狀態。
    # 原本各頁面的內容函式完全保留，只是由 main_nav_page 決定顯示哪一頁。
    # 這樣更新按鈕完成後才能穩定導向指定頁面。
    selected_page = render_main_nav()

    if selected_page == "總覽":
        render_verdict_card(snapshot)
        render_market_chart(snapshot)
        render_market_breadth_card(snapshot)
        render_market_rise_sources_card(snapshot)
        render_sector_flow_strength_card(snapshot)
        render_ma_deduction_card(snapshot)
        render_data_health(snapshot)
        render_scenarios(snapshot)

    elif selected_page == "外部風險":
        render_external_risk(snapshot)

    elif selected_page == "新聞快照":
        render_news_snapshot(snapshot)

    elif selected_page == "資金流向":
        render_flow_settings()
        render_flow_map(snapshot)
        render_discovery(snapshot)

    elif selected_page == "資金流入成長股雷達":
        render_radar_settings("growth")
        snapshot = render_radar_scan_action(snapshot, "growth")
        render_radar_page(snapshot, "growth")

    elif selected_page == "個股法醫分析器":
        render_original_stock_analyzer_app()

    elif selected_page == "更新紀錄":
        render_data_health(snapshot)
        render_update_log(snapshot)
        with st.expander("清除本地快照"):
            st.warning("清除後 App 會回到尚未更新狀態，不會刪除程式碼。")
            if st.button("清除 market_radar_snapshot.json", type="secondary"):
                try:
                    if SNAPSHOT_PATH.exists():
                        SNAPSHOT_PATH.unlink()
                    st.session_state.snapshot = empty_snapshot()
                    st.success("已清除，請重新整理或按更新。")
                except Exception as e:
                    st.error(f"清除失敗：{e}")


if __name__ == "__main__":
    main()
